insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
('Мединский курс (Том 4)', '1', 'الْفِعْلُ الْمُتَعَدِّي وَاللَّازِمُ (переходный и непереходный глагол)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ الْمُتَعَدِّي وَاللَّازِمُ</span><p class="rule-study-text">переходный и непереходный глагол. المتعدي требует فاعل и مفعول به; اللازم не требует прямого дополнения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمُتَعَدِّي وَاللَّازِمُ</span><span class="rule-term-ru">الْفِعْلُ الْمُتَعَدِّي وَاللَّازِمُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">الفعلُ ينقسمُ باعتبارِ معناه إلى قسمين : مُتَعَدٍٍّ ، ولاَزِمٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">المتعدِّي، هو : ما تَجَاوَزَ أَثَرُهُ الفاعلَ إلى المفعولِ به، نحو : فهمتُ الدَّرسَ وقرأتُ الكتابَ.</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">فهو يحتاجُ إلى فاعلٍ ، ومفعولٍ به .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">علامته : قبول الضَّمير ( الهاء ) العائد إلى المفعول به ، نحو : فهمتُ الدرسَ وحفظتُهُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : ضربتُ الْحَيَّةَ وقَتَلْتُهَا .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">فضمير الغِيبة في ( حفظتُهُ, وقتلتُها ) عائد إلى المفعول به .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ومن علاماته : أن يُصَاغَ منه اسمُ المفعول مباشرة ( أي : غيرُ مُقْتَرِنٍ بحرفِ جرٍّ ) نحو : مكتوب ، ومضروب ، ومفهوم .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الأَوَّلُ</div><div class="rule-source-line">الفعلُ ينقسمُ باعتبارِ معناه إلى قسمين : مُتَعَدٍٍّ ، ولاَزِمٍ .</div><div class="rule-source-line">1- الْمُتَعَدَّي</div><div class="rule-source-line">المتعدِّي، هو : ما تَجَاوَزَ أَثَرُهُ الفاعلَ إلى المفعولِ به، نحو : فهمتُ الدَّرسَ وقرأتُ الكتابَ.</div><div class="rule-source-line">فهو يحتاجُ إلى فاعلٍ ، ومفعولٍ به .</div><div class="rule-source-line">علامته : قبول الضَّمير ( الهاء ) العائد إلى المفعول به ، نحو : فهمتُ الدرسَ وحفظتُهُ .</div><div class="rule-source-line">ونحو : ضربتُ الْحَيَّةَ وقَتَلْتُهَا .</div><div class="rule-source-line">فضمير الغِيبة في ( حفظتُهُ, وقتلتُها ) عائد إلى المفعول به .</div><div class="rule-source-line">ومن علاماته : أن يُصَاغَ منه اسمُ المفعول مباشرة ( أي : غيرُ مُقْتَرِنٍ بحرفِ جرٍّ ) نحو : مكتوب ، ومضروب ، ومفهوم .</div><div class="rule-source-line">2- اللاَّزِمُ ( القَاصِرُ )</div><div class="rule-source-line">اللاَّزِمُ ، هو : ما لم يتعدَّ أَثَرُهُ الفاعلَ .</div><div class="rule-source-line">نحو : بَكَى الطِّفْلُ ونَامَ . جلستُ في البيتِ. نزل السائقُ من السيارةِ . خرجتُ من البيت. سِرْتُ وَرَاءَهُ .</div><div class="rule-source-line">فهو لا يحتاج إلى مفعول به . ولا يُصَاغ منه اسمُ المفعول إلا بواسطةِ حرفِ جَرٍّ ، أو ظرفٍ ، نحو : مَذْهُوب إليه ، ومَخْرُوج منه ، ومَجْلُوس فيه، ومَسِير وَرَاءَهُ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'المتعدي требует فاعل и مفعول به; اللازم не требует прямого дополнения.'),
('Мединский курс (Том 4)', '1', 'طَرَائِقُ تَعْدِيَةِ الْفِعْلِ اللَّازِمِ (способы сделать непереходный глагол переходным)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">طَرَائِقُ تَعْدِيَةِ الْفِعْلِ اللَّازِمِ</span><p class="rule-study-text">способы сделать непереходный глагол переходным. اللازم становится متعدياً через باب أفعل, باب فعّل или через حرف جرّ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">طَرَائِقُ تَعْدِيَةِ الْفِعْلِ اللَّازِمِ</span><span class="rule-term-ru">طَرَائِقُ تَعْدِيَةِ الْفِعْلِ اللَّازِمِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ فَعَّلَ</span><span class="rule-term-ru">порода فَعَّلَ: усиление, многократность или перевод в переходность</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ أَفْعَلَ</span><span class="rule-term-ru">порода أَفْعَلَ: часто делает لازим переходным</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنْ</span><span class="rule-term-ru">облегчённая لكنّ; не работает как إنّ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">لتعدية الفعل اللاَّزم ثلاث طرائق , هي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أ- نقله إلى باب أَفْعَلَ ، نحو : أَبْكَى الرَّجُلُ الطفلَ . أَجْلَسَ المراقبُ الطَّالِبَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ب- نقله إلى باب فَعَّلَ ، نحو : بَكَّى الرَّجُلُ الطفلَ . جلَّس المراقبُ الطَّالِبَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ج- تَعْدِيَةُ اللاَّزمِ بواسطةِ حرفِ الجرِّ ، نحو : غَضِبَ اللهُ على اليهودِ . فالمجرور (اليهود ) بمعنى المفعول به ؛ ولذلك نقول في إعرابه : الجار والمجرور في محل نصب مفعول به غير صريح .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ومن الأمثلة قولك: نظرتُ إلى الجبلِ . رَغِبْتُ في السُّنَّةِ . تَمَسَّكْ بِالفَضِيلَةِ . اِطَّلَعَ الْمُدِيرُ على الكِتَابِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">طَرَائِقُ تَعْدِيَةِ الفِعْلِ اللاَّزِمِ</div><div class="rule-source-line">لتعدية الفعل اللاَّزم ثلاث طرائق , هي :</div><div class="rule-source-line">أ- نقله إلى باب أَفْعَلَ ، نحو : أَبْكَى الرَّجُلُ الطفلَ . أَجْلَسَ المراقبُ الطَّالِبَ .</div><div class="rule-source-line">ب- نقله إلى باب فَعَّلَ ، نحو : بَكَّى الرَّجُلُ الطفلَ . جلَّس المراقبُ الطَّالِبَ .</div><div class="rule-source-line">ج- تَعْدِيَةُ اللاَّزمِ بواسطةِ حرفِ الجرِّ ، نحو : غَضِبَ اللهُ على اليهودِ . فالمجرور (اليهود ) بمعنى المفعول به ؛ ولذلك نقول في إعرابه : الجار والمجرور في محل نصب مفعول به غير صريح .</div><div class="rule-source-line">ومن الأمثلة قولك: نظرتُ إلى الجبلِ . رَغِبْتُ في السُّنَّةِ . تَمَسَّكْ بِالفَضِيلَةِ . اِطَّلَعَ الْمُدِيرُ على الكِتَابِ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'اللازم становится متعدياً через باب أفعل, باب فعّل или через حرف جرّ.'),
('Мединский курс (Том 4)', '1', 'مِنْ مَعَانِي فَعَّلَ (значения породы فَعَّلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مِنْ مَعَانِي فَعَّلَ</span><p class="rule-study-text">значения породы فَعَّلَ. من معاني فعّل: التعدية والتكثير والمبالغة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">مِنْ مَعَانِي فَعَّلَ</span><span class="rule-term-ru">مِنْ مَعَانِي فَعَّلَ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">1- التَّعْدِيَةُ : نحو : جَلَّسَ الْمُرَاقِبُ الطَّالِبَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- التَّكْثِيرُ : وذلك إذا كان المفعول به كثيرا ، نحو: كَسَّرْتُ الأَقْلامَ . فَتَّحْتُ الأَبْوَابَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">3- الْمُبَالَغَةُ : وذلك إذا كان المفعول به شيئا واحدا ،نحو:كَسَّرْتُ القَلَمَ . فَتَّحْتُ البابَ.</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">مِنْ مَعَاني فَعَّلَ</div><div class="rule-source-line">1- التَّعْدِيَةُ : نحو : جَلَّسَ الْمُرَاقِبُ الطَّالِبَ .</div><div class="rule-source-line">2- التَّكْثِيرُ : وذلك إذا كان المفعول به كثيرا ، نحو: كَسَّرْتُ الأَقْلامَ . فَتَّحْتُ الأَبْوَابَ .</div><div class="rule-source-line">3- الْمُبَالَغَةُ : وذلك إذا كان المفعول به شيئا واحدا ،نحو:كَسَّرْتُ القَلَمَ . فَتَّحْتُ البابَ.</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'من معاني فعّل: التعدية والتكثير والمبالغة.'),
('Мединский курс (Том 4)', '1', 'أَرَى مِنْ بَابِ أَفْعَلَ (أرى из породы أفعل)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَرَى مِنْ بَابِ أَفْعَلَ</span><p class="rule-study-text">أرى из породы أفعل. أرى المزيد من رأى ينصب مفعولين لأنه متعدٍّ منقول إلى باب أفعل.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">أَرَى مِنْ بَابِ أَفْعَلَ</span><span class="rule-term-ru">أَرَى مِنْ بَابِ أَفْعَلَ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ أَفْعَلَ</span><span class="rule-term-ru">порода أَفْعَلَ: часто делает لازим переходным</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَى الثُّلاثي المجرَّد، مضارعه : يَرَى ، والأمر منه : رَ ؛ تقول : رَهْ ( بهاء السَّكتْ ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">وهو ينصب مفعولاً واحداً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أما أرى الثلاثي المزيد فهو من باب أفعل ، فأصله : أَرْأَى ، حذفت الهمزة تخفيفا، فصار: أَرَى ، ومضارعه : يُرِى ، والأمر منه : أَرِ ؛ تقول: أَرِني كتابَك .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">وهو ينصب مفعولين ؛ لأنه مُتَعَدٍّ نُقِل إلى باب أَفْعَل .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">أَرَى من بَـابِ أَفْعَلَ</div><div class="rule-source-line">رَأَى الثُّلاثي المجرَّد، مضارعه : يَرَى ، والأمر منه : رَ ؛ تقول : رَهْ ( بهاء السَّكتْ ) .</div><div class="rule-source-line">وهو ينصب مفعولاً واحداً .</div><div class="rule-source-line">أما أرى الثلاثي المزيد فهو من باب أفعل ، فأصله : أَرْأَى ، حذفت الهمزة تخفيفا، فصار: أَرَى ، ومضارعه : يُرِى ، والأمر منه : أَرِ ؛ تقول: أَرِني كتابَك .</div><div class="rule-source-line">وهو ينصب مفعولين ؛ لأنه مُتَعَدٍّ نُقِل إلى باب أَفْعَل .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'أرى المزيد من رأى ينصب مفعولين لأنه متعدٍّ منقول إلى باب أفعل.'),
('Мединский курс (Том 4)', '1', 'جَمْعُ الْجَمْعِ (множественное от множественного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَمْعُ الْجَمْعِ</span><p class="rule-study-text">множественное от множественного. جمع الجمع سماعي يحفظ ولا يقاس عليه.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">جَمْعُ الْجَمْعِ</span><span class="rule-term-ru">جَمْعُ الْجَمْعِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">قد يُجْمَعُ الْجَمْعُ ، وهو سَمَاعِيّ يُحْفَظُ ، ولا يُقاس عليه .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">إناءٌ - آنيةٌ - أَوَانٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">سِوَارٌ - أَسْوِرَةٌ - أَسَاوِرُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">يَدٌ - أَيْدٍ - أَيَادٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">طَرِيقٌ - طُرُقٌ - طُرُقَاتٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَكَانٌ - أَمْكِنَةٌ - أَمَاكِنُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">جَمْعُ الْجَمْعِ</div><div class="rule-source-line">قد يُجْمَعُ الْجَمْعُ ، وهو سَمَاعِيّ يُحْفَظُ ، ولا يُقاس عليه .</div><div class="rule-source-line">من أمثلته :</div><div class="rule-source-line">إناءٌ - آنيةٌ - أَوَانٍ .</div><div class="rule-source-line">سِوَارٌ - أَسْوِرَةٌ - أَسَاوِرُ .</div><div class="rule-source-line">يَدٌ - أَيْدٍ - أَيَادٍ .</div><div class="rule-source-line">طَرِيقٌ - طُرُقٌ - طُرُقَاتٌ .</div><div class="rule-source-line">مَكَانٌ - أَمْكِنَةٌ - أَمَاكِنُ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'جمع الجمع سماعي يحفظ ولا يقاس عليه.'),
('Мединский курс (Том 4)', '1', 'إِنَّمَا (частица ограничения «только»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِنَّمَا</span><p class="rule-study-text">частица ограничения «только». إنما مركبة من إنّ وما الكافة، وتفيد الحصر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّمَا</span><span class="rule-term-ru">إِنَّمَا — частица ограничения: «только, лишь»</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هي عِبَارَةٌ عن دخولِ ( ما ) الزَّائدةِ الكَافَّةِ على ( إنَّ ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فإذا دخلت ( ما ) الزَّائدة الكافَّة على ( إنَّ ) أَثَّرَتْ فيها من جهتين :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">1- تُبْطِلُ عَمَلَهَا في الجملةِ الاسميَّةِ ، نحو قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">2- تَجْعَلُهَا تدخلُ على الجملةِ الفعليَّةِ , كما في قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">معناها : تُفِيدُ الْحَصْرَ، (التَّعْيِين) أي : إِثْبَاتُ وتَعْيِينُ صفة واحدة دون غيرها من الصفات، نحو : إنما محمدٌ طالبٌ، أَثْبَتْنَا أنه طالبٌ فقط، وليس له صفة أخرى ، فهو ليس بطبيب ، ولا معلّم ... إلخ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب : إنَّما محمدٌ طالبٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">إنما : إنَّ : حرف نصب مُهْمَل ( لا عمل له ) مبني على الفتح .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">إِنَّمَا</div><div class="rule-source-line">هي عِبَارَةٌ عن دخولِ ( ما ) الزَّائدةِ الكَافَّةِ على ( إنَّ ) .</div><div class="rule-source-line">فإذا دخلت ( ما ) الزَّائدة الكافَّة على ( إنَّ ) أَثَّرَتْ فيها من جهتين :</div><div class="rule-source-line">1- تُبْطِلُ عَمَلَهَا في الجملةِ الاسميَّةِ ، نحو قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">2- تَجْعَلُهَا تدخلُ على الجملةِ الفعليَّةِ , كما في قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">معناها : تُفِيدُ الْحَصْرَ، (التَّعْيِين) أي : إِثْبَاتُ وتَعْيِينُ صفة واحدة دون غيرها من الصفات، نحو : إنما محمدٌ طالبٌ، أَثْبَتْنَا أنه طالبٌ فقط، وليس له صفة أخرى ، فهو ليس بطبيب ، ولا معلّم ... إلخ .</div><div class="rule-source-line">الإعراب : إنَّما محمدٌ طالبٌ .</div><div class="rule-source-line">إنما : إنَّ : حرف نصب مُهْمَل ( لا عمل له ) مبني على الفتح .</div><div class="rule-source-line">ما : حرف زائد مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">محمدٌ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">طالبٌ : خبر مرفوع وعلامة رفعه الضمة الظاهرة .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'إنما مركبة من إنّ وما الكافة، وتفيد الحصر.'),
('Мединский курс (Том 4)', '1', 'أُسْلُوبُ التَّحْذِيرِ (конструкция предостережения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أُسْلُوبُ التَّحْذِيرِ</span><p class="rule-study-text">конструкция предостережения. التحذير منصوب بفعل محذوف تقديره احذر، مثل: إياك والكذب.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أُسْلُوبُ التَّحْذِيرِ</span><span class="rule-term-ru">أُسْلُوبُ التَّحْذِيرِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">التحذيرُ : تَنْبِيهُ الْمُخَاطَبِ على أمرٍ مكروهٍ ؛ ليجتنبه .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مثاله : إِيَّاكَ والكَذِبَ . إِيَّاكُمَا والغِيبَةَ . إِيَّاكُمْ والزِّنَا . إِيَّاكُنَّ والتَّبَرُّجَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">إعرابه : إِيَّاكَ والكذبَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">إياك : ضمير نصب منفصل مبني على الفتح في محل نصب مفعول به لفعل محذوف ,</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">تقديره : أُحَذِّرُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">وَ : حرف عطف مبني على الفتح لا محلَّ له من الإعراب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">الكذبَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة, وفعله محذوف تقديره : اِحْذَرْ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">أُسْلُوبُ التَّحْذِيرِ</div><div class="rule-source-line">التحذيرُ : تَنْبِيهُ الْمُخَاطَبِ على أمرٍ مكروهٍ ؛ ليجتنبه .</div><div class="rule-source-line">مثاله : إِيَّاكَ والكَذِبَ . إِيَّاكُمَا والغِيبَةَ . إِيَّاكُمْ والزِّنَا . إِيَّاكُنَّ والتَّبَرُّجَ .</div><div class="rule-source-line">إعرابه : إِيَّاكَ والكذبَ .</div><div class="rule-source-line">إياك : ضمير نصب منفصل مبني على الفتح في محل نصب مفعول به لفعل محذوف ,</div><div class="rule-source-line">تقديره : أُحَذِّرُ .</div><div class="rule-source-line">وَ : حرف عطف مبني على الفتح لا محلَّ له من الإعراب .</div><div class="rule-source-line">الكذبَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة, وفعله محذوف تقديره : اِحْذَرْ</div><div class="rule-source-line">وجملة ( الكذب ) معطوفة على جملة ( إياك ) .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 7, 'rule', 'التحذير منصوب بفعل محذوف تقديره احذر، مثل: إياك والكذب.'),
('Мединский курс (Том 4)', '1', 'تَأْكِيدُ الْفِعْلِ الْمَاضِي بِاللَّامِ وَقَدْ (усиление прошедшего глагола через لَـ и قَدْ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَأْكِيدُ الْفِعْلِ الْمَاضِي بِاللَّامِ وَقَدْ</span><p class="rule-study-text">усиление прошедшего глагола через لَـ и قَدْ. الفعل الماضي يؤكد بقد وباللام وقد، ولا سيما في جواب القسم.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">تَأْكِيدُ الْفِعْلِ الْمَاضِي بِاللَّامِ وَقَدْ</span><span class="rule-term-ru">تَأْكِيدُ الْفِعْلِ الْمَاضِي بِاللَّامِ وَقَدْ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَقَدْ</span><span class="rule-term-ru">усиление прошедшего действия через لام и قد</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">إذا كان جواب القسم فعلا ماضيا مثبتاً أُكِّدَ باللاَّم وقد .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">قال تعالى : [موضع غير واضح في المصدر]</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">وقال تعالى : [موضع غير واضح في المصدر]</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وتقول : والله لقد فرحتُ بنجاحك . والله لقد فهمتُ الدرس .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">تأكيدُ الفعلِ الماضي بـ اللاَّم وقَدْ</div><div class="rule-source-line">إذا كان جواب القسم فعلا ماضيا مثبتاً أُكِّدَ باللاَّم وقد .</div><div class="rule-source-line">قال تعالى : [موضع غير واضح في المصدر]</div><div class="rule-source-line">وقال تعالى : [موضع غير واضح في المصدر]</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div><div class="rule-source-line">وتقول : والله لقد فرحتُ بنجاحك . والله لقد فهمتُ الدرس .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 8, 'rule', 'الفعل الماضي يؤكد بقد وباللام وقد، ولا سيما في جواب القسم.'),
('Мединский курс (Том 4)', '1', 'أَمْسَى (أمسى как одна из сестёр كان)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَمْسَى</span><p class="rule-study-text">أمسى как одна из сестёр كان. أمسى تعمل عمل كان: ترفع الاسم وتنصب الخبر، وتأتي بمعنى دخل في المساء أو صار.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَمْسَى</span><span class="rule-term-ru">أَمْسَى — одна из сестёр كان: поднимает اسم и ставит خبر в نصب</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">أمسى : فعل ناسخ من أخوات كان يرفع الاسم وينصب الخبر ،</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : أمسى الجوُّ بارداً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أمستِ الأمُّ مريضةً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">أَمْسَى</div><div class="rule-source-line">أمسى : فعل ناسخ من أخوات كان يرفع الاسم وينصب الخبر ،</div><div class="rule-source-line">نحو : أمسى الجوُّ بارداً .</div><div class="rule-source-line">أمستِ الأمُّ مريضةً .</div><div class="rule-source-line">اسم أمسى     خبر أمسى</div><div class="rule-source-line">مرفوع         منصوب</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 9, 'rule', 'أمسى تعمل عمل كان: ترفع الاسم وتنصب الخبر، وتأتي بمعنى دخل في المساء أو صار.'),
('Мединский курс (Том 4)', '2', 'بَابُ فَاعَلَ (порода فَاعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ فَاعَلَ</span><p class="rule-study-text">порода فَاعَلَ. باب فاعل مزيد بالألف بعد الفاء؛ مصدره غالباً مفاعلة أو فعال، وقد يكون لازماً أو متعدياً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ فَاعَلَ</span><span class="rule-term-ru">بَابُ فَاعَلَ — порода فَاعَلَ: участие/взаимность или направленное действие</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلتِه : صَافَحَ , نَادَى , قَاتَلَ , سَافَرَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفُ الزِّيادةِ : الألف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">مَصدرُه : له وزنان , هما :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- مُفَاعَلَةٌ , نحو : قَاتَلَ : مُقَاتَلَة , شَارَكَ : مُشَارَكَة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">2- فِعَالٌ , نحو : قَاتَلَ : ِقتَال , نَادَى : ِندَاء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من معانِيهِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">1- الْمُشَارَكَةُ , نحو : صافحَ الرَّجلُ أخاه , قاتلَ المسلمون المشركين .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الثَّانِي</div><div class="rule-source-line">بَـابُ فَاعَلَ</div><div class="rule-source-line">من أمثلتِه : صَافَحَ , نَادَى , قَاتَلَ , سَافَرَ .</div><div class="rule-source-line">حرفُ الزِّيادةِ : الألف .</div><div class="rule-source-line">مَصدرُه : له وزنان , هما :</div><div class="rule-source-line">1- مُفَاعَلَةٌ , نحو : قَاتَلَ : مُقَاتَلَة , شَارَكَ : مُشَارَكَة .</div><div class="rule-source-line">2- فِعَالٌ , نحو : قَاتَلَ : ِقتَال , نَادَى : ِندَاء .</div><div class="rule-source-line">من معانِيهِ :</div><div class="rule-source-line">1- الْمُشَارَكَةُ , نحو : صافحَ الرَّجلُ أخاه , قاتلَ المسلمون المشركين .</div><div class="rule-source-line">2- بمعنى فَعَلَ , نحو : سَافَرَ ,  هَاجَرَ ,  جَاوَزَ .</div><div class="rule-source-line">مُشْتَقَّاتُهُ :</div><div class="rule-source-line">اسم المفعول</div><div class="rule-source-line">| اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُصَافَحٌ</div><div class="rule-source-line">| مُصَافِحٌ</div><div class="rule-source-line">| مُصَافََحَةٌ</div><div class="rule-source-line">| صَاْفِحْ</div><div class="rule-source-line">| يُصَاْفِحُ</div><div class="rule-source-line">| صَاْفَحَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُسَاْفِرٌ</div><div class="rule-source-line">| سَفَرٌ ومُسَافَرَةٌ</div><div class="rule-source-line">| سَاْفِرْ</div><div class="rule-source-line">| يُسَاْفِرُ</div><div class="rule-source-line">| سَاْفَرَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُنَادًى(الْمُنَادَى)</div><div class="rule-source-line">| مُنَادٍ (الْمُنَادِي)</div><div class="rule-source-line">| مُنَادَاةٌ ونِدَاءٌ</div><div class="rule-source-line">| نَادِ</div><div class="rule-source-line">| يُنَادِي</div><div class="rule-source-line">| نَادَى</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'باب فاعل مزيد بالألف بعد الفاء؛ مصدره غالباً مفاعلة أو فعال، وقد يكون لازماً أو متعدياً.'),
('Мединский курс (Том 4)', '2', 'مَعَانِي قَدْ (значения قَدْ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَعَانِي قَدْ</span><p class="rule-study-text">значения قَدْ. قد مع الماضي للتحقيق غالباً، ومع المضارع قد تفيد التقليل أو التكثير بحسب السياق.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَعَانِي قَدْ</span><span class="rule-term-ru">مَعَانِي قَدْ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">| معاني قَدْ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">قَدْ : تأتي بمعنى التَّوكيدِ مع الفعل  الماضي ، وتأتي بمعنى الاحتمالِ والشَّكِّ ، والتَّقليلِ، والتَّحقيقِ مع المضارع ، وإليك البيان :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- إذا دخلت قد على الفعل الماضي أفادت التَّوكيد ( التَّحقيق ) كما في قوله تعالى :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">[موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  وكما في قولك : قد نجحت .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">2- إذا دخلت على المضارع أفادت أحدَ أمورٍ ثلاثةٍ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">( أ ) الاحتمال والشَّك ، نحو : قد يأتي المديرُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">(ب) التَّقليل ، نحو : قد يرسب المجتهدُ ، وقد يصدق الكَذُوبُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">| معاني قَدْ</div><div class="rule-source-line">قَدْ : تأتي بمعنى التَّوكيدِ مع الفعل  الماضي ، وتأتي بمعنى الاحتمالِ والشَّكِّ ، والتَّقليلِ، والتَّحقيقِ مع المضارع ، وإليك البيان :</div><div class="rule-source-line">1- إذا دخلت قد على الفعل الماضي أفادت التَّوكيد ( التَّحقيق ) كما في قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  وكما في قولك : قد نجحت .</div><div class="rule-source-line">2- إذا دخلت على المضارع أفادت أحدَ أمورٍ ثلاثةٍ :</div><div class="rule-source-line">( أ ) الاحتمال والشَّك ، نحو : قد يأتي المديرُ .</div><div class="rule-source-line">(ب) التَّقليل ، نحو : قد يرسب المجتهدُ ، وقد يصدق الكَذُوبُ .</div><div class="rule-source-line">(ج) التَّحقيق ، نحو قوله تعالى : [موضع غير واضح في المصدر] وقوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'قد مع الماضي للتحقيق غالباً، ومع المضارع قد تفيد التقليل أو التكثير بحسب السياق.'),
('Мединский курс (Том 4)', '2', 'تَخْفِيفُ لَكِنَّ: لَكِنْ (облегчение لَكِنَّ до لَكِنْ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَخْفِيفُ لَكِنَّ: لَكِنْ</span><p class="rule-study-text">облегчение لَكِنَّ до لَكِنْ. إذا خففت لكنّ صارت لكنْ ولا تعمل عمل إنّ، ويجوز دخول الواو عليها.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">تَخْفِيفُ لَكِنَّ: لَكِنْ</span><span class="rule-term-ru">تَخْفِيفُ لَكِنَّ: لَكِنْ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنْ</span><span class="rule-term-ru">облегчённая لكنّ; не работает как إنّ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">إذا خُفَّفَتْ لكنَّ : بطل عملها ، ودخلت على الجملة الفعلية .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">فمثال إبطال عملها ، قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وكقولك : جاء عليٌ لكنْ أخوه غائبٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ومثال دخولها على الجملة الفعلية ، قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وكقولك : جاء عليٌ لكنْ غابَ خالدٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ويجوز أن تسبقها واو العطف ؛ فتقول : جاء عليٌّ ولكنْ غابَ خالدٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فائدتها : الاسْتِدْرَاك .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">تَخْفِيفُ لَكِنَّ  ( لَكِنْ )</div><div class="rule-source-line">إذا خُفَّفَتْ لكنَّ : بطل عملها ، ودخلت على الجملة الفعلية .</div><div class="rule-source-line">فمثال إبطال عملها ، قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">وكقولك : جاء عليٌ لكنْ أخوه غائبٌ .</div><div class="rule-source-line">ومثال دخولها على الجملة الفعلية ، قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">وكقولك : جاء عليٌ لكنْ غابَ خالدٌ .</div><div class="rule-source-line">ويجوز أن تسبقها واو العطف ؛ فتقول : جاء عليٌّ ولكنْ غابَ خالدٌ .</div><div class="rule-source-line">فائدتها : الاسْتِدْرَاك .</div><div class="rule-source-line">الإعراب : جاء المدرسُ لكنِ الطُّلاَّبُ غابوا .</div><div class="rule-source-line">جاءَ : فعلٌ ماضٍ مبنيٌّ على الفتح .</div><div class="rule-source-line">المدرسُ : فاعل مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">لكنْ : حرف ابتداء واستدراك مبني على السكون لا محل له من الإعراب.</div><div class="rule-source-line">الطُّلابُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">غابوا : فعل وفاعل، والجملة الفعلية في محل رفع خبر المبتدأ، وجملة ( الطلاب غابوا ) ابتدائية لا محل لها من الإعراب .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'إذا خففت لكنّ صارت لكنْ ولا تعمل عمل إنّ، ويجوز دخول الواو عليها.'),
('Мединский курс (Том 4)', '2', 'ذَوُو وَأُولُو (ذوو и أولو со значением «обладатели»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذَوُو وَأُولُو</span><p class="rule-study-text">ذوو и أولو со значением «обладатели». ذوو وأولو بمعنى أصحاب، ولا تستعملان إلا مضافتين، وتعربان إعراب جمع المذكر السالم.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذَوُو وَأُولُو</span><span class="rule-term-ru">ذَوُو وَأُولُو — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">مُلْحَقَتَانِ  بجمعِ المذكَّرِ السَّالمِ ، وتعربان إعرابه , رفعاً بالواو , ونصباً وجَرًّا بالياء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وهما بمعنى ( أصحاب ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">مثالُ الرَّفْعِ: نحن ذَوُو عِلْمٍ، وأُوْلُو فَضْلٍ . مثالُ النَّصْبِ : رأيت ذَوِي علمٍ، وأُولِي فضلٍ.</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">مثالُ الْجَرِّ : ذهبت إلى ذَوِي علمٍ ، وَأُولِي فضلٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">معنى تَصَرُّفِ كافِ الخطابِ : مُرَاعَاةُ الْمُخَاطَبِ ، فالكاف يُرَاعَى في لفظها المخاطَب مُفرداً ، أو مُثنىًّ ، أو جَمعاً ؛ مُذكَّراً ، أو مُؤنَّثاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الأمثلة :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">قال تعالى: [موضع غير واضح في المصدر] وقال تعالى: [موضع غير واضح في المصدر]</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">ذَوُو – أُوْلُو</div><div class="rule-source-line">مُلْحَقَتَانِ  بجمعِ المذكَّرِ السَّالمِ ، وتعربان إعرابه , رفعاً بالواو , ونصباً وجَرًّا بالياء .</div><div class="rule-source-line">وهما بمعنى ( أصحاب ) .</div><div class="rule-source-line">مثالُ الرَّفْعِ: نحن ذَوُو عِلْمٍ، وأُوْلُو فَضْلٍ . مثالُ النَّصْبِ : رأيت ذَوِي علمٍ، وأُولِي فضلٍ.</div><div class="rule-source-line">مثالُ الْجَرِّ : ذهبت إلى ذَوِي علمٍ ، وَأُولِي فضلٍ .</div><div class="rule-source-line">تَصَرُّفُ كَافِ الْخِطَابِ في اسمي الإشارة ( ذَلِكَ ، وتِلْكَ )</div><div class="rule-source-line">معنى تَصَرُّفِ كافِ الخطابِ : مُرَاعَاةُ الْمُخَاطَبِ ، فالكاف يُرَاعَى في لفظها المخاطَب مُفرداً ، أو مُثنىًّ ، أو جَمعاً ؛ مُذكَّراً ، أو مُؤنَّثاً .</div><div class="rule-source-line">الأمثلة :</div><div class="rule-source-line">قال تعالى: [موضع غير واضح في المصدر] وقال تعالى: [موضع غير واضح في المصدر]</div><div class="rule-source-line">وقال تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">وكقولك : أذلكمُ القلمُ لكم يا إخوانُ ؟   أتلكِ المجلةُ لكِ يا فاطمةُ ؟</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'ذوو وأولو بمعنى أصحاب، ولا تستعملان إلا مضافتين، وتعربان إعراب جمع المذكر السالم.'),
('Мединский курс (Том 4)', '2', 'اللَّامُ الْمُزَحْلَقَةُ (сдвинутая لام усиления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اللَّامُ الْمُزَحْلَقَةُ</span><p class="rule-study-text">сдвинутая لام усиления. لام الابتداء تتزحلق إلى خبر إنّ غالباً، وقد تدخل على الاسم إذا تأخر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">اللَّامُ الْمُزَحْلَقَةُ</span><span class="rule-term-ru">اللَّامُ الْمُزَحْلَقَةُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هي لام الابتداء انتقلت إلى الخبر بسبب دخول إنَّ ( مكسورة الهمزة ) عليها .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فائدتها : التوكيد ؛ ولذلك انتقلت إلى الخبر بعد دخول إنّ عليها ؛ كراهة اجتماع مُؤَكِّدَيْنِ في أوَّل الكلام .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الأمثلة :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">قال تعالى : [موضع غير واضح في المصدر] وقال تعالى : [موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">وكقولك : إنّ هذا لَطَالِبٌ . إنّ الدرسَ لَمُفيدٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">قد تدخل على اسم إنّ ، وذلك إذا تأخر الاسم ،كما في قوله تعالى :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">[موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">اللاَّمُ الْمُزَحْلَقَةُ</div><div class="rule-source-line">هي لام الابتداء انتقلت إلى الخبر بسبب دخول إنَّ ( مكسورة الهمزة ) عليها .</div><div class="rule-source-line">فائدتها : التوكيد ؛ ولذلك انتقلت إلى الخبر بعد دخول إنّ عليها ؛ كراهة اجتماع مُؤَكِّدَيْنِ في أوَّل الكلام .</div><div class="rule-source-line">الأمثلة :</div><div class="rule-source-line">قال تعالى : [موضع غير واضح في المصدر] وقال تعالى : [موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]</div><div class="rule-source-line">وكقولك : إنّ هذا لَطَالِبٌ . إنّ الدرسَ لَمُفيدٌ .</div><div class="rule-source-line">قد تدخل على اسم إنّ ، وذلك إذا تأخر الاسم ،كما في قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب : إنّ الدرسَ لمفيدٌ .</div><div class="rule-source-line">إنَّ : حرف نصب وتوكيد مبني على الفتح .</div><div class="rule-source-line">الدرسَ : اسم إن منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">لمفيدٌ : اللام المزحلقة : حرف مبني على الفتح لا محل له من الإعراب .</div><div class="rule-source-line">مفيد : خبر إن مرفوع وعلامة رفعه الضمة الظاهرة .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'لام الابتداء تتزحلق إلى خبر إنّ غالباً، وقد تدخل على الاسم إذا تأخر.'),
('Мединский курс (Том 4)', '2', 'جَمْعُ بَرْنَامَجٍ عَلَى بَرَامِجَ (множественное بَرْنَامَجٌ → بَرَامِجُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَمْعُ بَرْنَامَجٍ عَلَى بَرَامِجَ</span><p class="rule-study-text">множественное بَرْنَامَجٌ → بَرَامِجُ. برنامج يجمع على برامج على وزن فعالل.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">جَمْعُ بَرْنَامَجٍ عَلَى بَرَامِجَ</span><span class="rule-term-ru">جَمْعُ بَرْنَامَجٍ عَلَى بَرَامِجَ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">صِيغَةُ مُنْتَهَى الْجُمُوعِ</span><span class="rule-term-ru">крайняя форма ломаного множественного</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">على الأربعة ( وذلك بالرجوع إلى أصول الكلمات في المعاجم ) نحو :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">سَفَرْجَل : سَفَارِج . عَنْدَلِيب : عَنَادِل . عَنْكَبُوت : عَنَاكِب . مُسْتَشْفَى : مَشَافٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">جَمْعُ بَرْنَامَجٍ على بَرَامِجَ</div><div class="rule-source-line">إذا جُمِعَ الاسم الذي حروفه خمسة، أو أكثر على صيغة منتهى الجموع حُذِفَ ما زاد</div><div class="rule-source-line">على الأربعة ( وذلك بالرجوع إلى أصول الكلمات في المعاجم ) نحو :</div><div class="rule-source-line">سَفَرْجَل : سَفَارِج . عَنْدَلِيب : عَنَادِل . عَنْكَبُوت : عَنَاكِب . مُسْتَشْفَى : مَشَافٍ .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'برنامج يجمع على برامج على وزن فعالل.'),
('Мединский курс (Том 4)', '3', 'بَابُ تَفَعَّلَ (порода تَفَعَّلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ تَفَعَّلَ</span><p class="rule-study-text">порода تَفَعَّلَ. باب تفعل مزيد بالتاء وتضعيف العين؛ مصدره تفعّل، وله معانٍ منها المطاوعة والتكلف.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ تَفَعَّلَ</span><span class="rule-term-ru">بَابُ تَفَعَّلَ — порода تَفَعَّلَ: принятие действия, постепенность или усилие</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْلَا</span><span class="rule-term-ru">частица условия/побуждения; значение зависит от контекста</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : تَعَلَّمَ , تَحَدَّثَ ، تَغَدَّى .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفا الزِّيادة : التَّاء ، والتَّضعيف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : تفَعُّلٌ (كُلُّ فعلٍ بُدِئَ بالتَّاء الزَّائدة ضُمَّ ما قبل آخره ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : تحَدَّثَ : تحَدُّثٌ ، تَسَلَّمَ : تَسَلُّمٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من معانيه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">- الْمُطَاوَعَةُ : وهي قَبُولُ أَثَرِ الفعلِ , فيصير المفعول فاعلا ، أي : أنَّ المطاوعةَ تَجْعَلُ الفعلَ المتعدَّي إلى مفعول واحد لازماً ، نحو : كسَّرتُ الزُّجَاجَ , فتَكَسَّرَ الزُّجَاجُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">وتجعل المتعدي إلى مفعولين متعديًّا إلى مفعول واحد ، نحو :                                علَّمْتُ الطالبَ القرآنَ ، فتعلَّمَ الطالبُ القرآنَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الثَّالِثُ</div><div class="rule-source-line">بَـابُ تَفَعَّلَ</div><div class="rule-source-line">من أمثلته : تَعَلَّمَ , تَحَدَّثَ ، تَغَدَّى .</div><div class="rule-source-line">حرفا الزِّيادة : التَّاء ، والتَّضعيف .</div><div class="rule-source-line">مصدره : تفَعُّلٌ (كُلُّ فعلٍ بُدِئَ بالتَّاء الزَّائدة ضُمَّ ما قبل آخره ) .</div><div class="rule-source-line">نحو : تحَدَّثَ : تحَدُّثٌ ، تَسَلَّمَ : تَسَلُّمٌ .</div><div class="rule-source-line">من معانيه :</div><div class="rule-source-line">- الْمُطَاوَعَةُ : وهي قَبُولُ أَثَرِ الفعلِ , فيصير المفعول فاعلا ، أي : أنَّ المطاوعةَ تَجْعَلُ الفعلَ المتعدَّي إلى مفعول واحد لازماً ، نحو : كسَّرتُ الزُّجَاجَ , فتَكَسَّرَ الزُّجَاجُ .</div><div class="rule-source-line">وتجعل المتعدي إلى مفعولين متعديًّا إلى مفعول واحد ، نحو :                                علَّمْتُ الطالبَ القرآنَ ، فتعلَّمَ الطالبُ القرآنَ .</div><div class="rule-source-line">المشتقات :</div><div class="rule-source-line">اسم المفعول</div><div class="rule-source-line">| اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُتَوَكِّلٌ</div><div class="rule-source-line">| تَوَكُّلٌ</div><div class="rule-source-line">| تَوَكَّلْ</div><div class="rule-source-line">| يَتَوَكَّلُ</div><div class="rule-source-line">| تَوَكَّلَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُتَمَنًّى</div><div class="rule-source-line">| مُتَمَنٍّ (الْمُتَمَنَّي)</div><div class="rule-source-line">| تَمَنٍّ (أصله تَمَنُّيٌ)</div><div class="rule-source-line">| تَمَنَّ</div><div class="rule-source-line">| يَتَمَنَّى</div><div class="rule-source-line">| تَمَنَّى</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُتَحَدَّثٌ</div><div class="rule-source-line">| تَحَدُّثٌ</div><div class="rule-source-line">| تَحَدَّثْ</div><div class="rule-source-line">| يَتَحَدَّثُ</div><div class="rule-source-line">| تَحَدَّثَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُتَدَبَّرٌ</div><div class="rule-source-line">| مُتَدَبَّرٌ</div><div class="rule-source-line">| تَدَبُّرٌ</div><div class="rule-source-line">| تَدَبَّرْ</div><div class="rule-source-line">| يَتَدَبَّرُ</div><div class="rule-source-line">| تَدَبَّرَ</div><div class="rule-source-line">|</div><div class="rule-source-line">|</div><div class="rule-source-line">يجوز حذف إحدى التَّاءين في باب تَفَعَّلَ إذا كان مضارعاً مبدوءاً بالتاء ، نحو قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] والأصل: تَتَنَزَّلُ الملائكةُ  ، وقوله تعالى : [موضع غير واضح في المصدر] والأصل:  ولا تَتَجَسَّسُوا .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'باب تفعل مزيد بالتاء وتضعيف العين؛ مصدره تفعّل، وله معانٍ منها المطاوعة والتكلف.'),
('Мединский курс (Том 4)', '3', 'لَمَّا الْحِينِيَّةُ (لَمَّا со значением «когда/как только»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَمَّا الْحِينِيَّةُ</span><p class="rule-study-text">لَمَّا со значением «когда/как только». لما الحينية ظرف زمان بمعنى حين، تختص بالماضي وتحتاج إلى جواب.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَمَّا الْحِينِيَّةُ</span><span class="rule-term-ru">لَمَّا الْحِينِيَّةُ — когда/как только: ظرف زمان مبني</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ظرفُ زمانٍ مبنيٌّ على السكون في محل نصب . تتضمن معنى الشرط ، فهي تحتاج إلى فعل</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">شرط وإلى جواب . تختص بالزمان الماضي ، فشرطها وجوابها ماضيان .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الأمثلة : قال تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو قولك : لَمَّا وصلتُ المدينة صليتُ ركعتين في المسجد النبوي الشريف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : لَمَّا سَمِعَ الطَّالبُ الأذانَ تَوَضَّأَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب : لماَّ جاءَ المدرسُ دخلَ الطلابُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">لماَّ : ظرف زمان مبني على السكون في محل نصب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">لَمَّا الحِينِيَّةُ</div><div class="rule-source-line">ظرفُ زمانٍ مبنيٌّ على السكون في محل نصب . تتضمن معنى الشرط ، فهي تحتاج إلى فعل</div><div class="rule-source-line">شرط وإلى جواب . تختص بالزمان الماضي ، فشرطها وجوابها ماضيان .</div><div class="rule-source-line">الأمثلة : قال تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">ونحو قولك : لَمَّا وصلتُ المدينة صليتُ ركعتين في المسجد النبوي الشريف .</div><div class="rule-source-line">ونحو : لَمَّا سَمِعَ الطَّالبُ الأذانَ تَوَضَّأَ .</div><div class="rule-source-line">الإعراب : لماَّ جاءَ المدرسُ دخلَ الطلابُ .</div><div class="rule-source-line">لماَّ : ظرف زمان مبني على السكون في محل نصب .</div><div class="rule-source-line">جاء : فعلُ الشرطِ فعلٌ ماضٍ مبني على الفتح .</div><div class="rule-source-line">المدرسُ : فاعل مرفوع وعلامة رفعه الضمة الظاهرة ، وجملة الشرط ( جاءَ المدرسُ ) في</div><div class="rule-source-line">محل جر مضاف إليه .</div><div class="rule-source-line">دخلَ : جواب الشرط فعلٌ ماضٍ مبني على الفتح .</div><div class="rule-source-line">الطُّلابُ : فاعل مرفوع وعلامة رفعه الضمه الظاهرة ، وجملة الجواب ( دخلَ الطُّلابُ )</div><div class="rule-source-line">لا محلَّ لها من الإعراب . ( لأن لَمَّا غير جازمة ) .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'لما الحينية ظرف زمان بمعنى حين، تختص بالماضي وتحتاج إلى جواب.'),
('Мединский курс (Том 4)', '3', 'الِاسْمُ الْمَنْصُوبُ عَلَى الِاخْتِصَاصِ (имя в نصب для выделения/уточнения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الِاسْمُ الْمَنْصُوبُ عَلَى الِاخْتِصَاصِ</span><p class="rule-study-text">имя в نصب для выделения/уточнения. الاختصاص اسم منصوب بفعل محذوف تقديره أخص، يوضح المقصود من ضمير قبله.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الِاسْمُ الْمَنْصُوبُ عَلَى الِاخْتِصَاصِ</span><span class="rule-term-ru">الِاسْمُ الْمَنْصُوبُ عَلَى الِاخْتِصَاصِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الِاخْتِصَاصُ</span><span class="rule-term-ru">выделение/уточнение местоимения через منصوب</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">يُؤْتَى به لبيان المقصود بالضمير الذي قبله ، ويُنْصَبُ على أنه مفعول به لفعل محذوف وجوبا تقديره ( أَخُصُّ ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أنواعـه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أ- معَرَّفٌ بأَلْ ، نحو : نحن الطلابَ نُحِبُّ العلمَ . نحن المسلمين لا نشركُ باللهِ شيئاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ب- معَرَّفٌ بالإضافةِ ، نحو : نحن طلابَ العلمِ نجتهدُ في دروسنا .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله صلى الله عليه وسلم : &quot; إنَّا مَعْشَرَ الأنبياءِ لا نُوْرَثُ &quot;</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب : نحنُ الطُّلاَّبَ نحبُّ العلمَ .                                                       نحنُ : ضمير رفع منفصل مبني على الضم في محل رفع مبتدأ.</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">الطُّلابَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة لفعل محذوف وجوبا، تقديره</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الاسمُ المنصوبُ على الاخْتِصَاصِ</div><div class="rule-source-line">يُؤْتَى به لبيان المقصود بالضمير الذي قبله ، ويُنْصَبُ على أنه مفعول به لفعل محذوف وجوبا تقديره ( أَخُصُّ ) .</div><div class="rule-source-line">أنواعـه :</div><div class="rule-source-line">أ- معَرَّفٌ بأَلْ ، نحو : نحن الطلابَ نُحِبُّ العلمَ . نحن المسلمين لا نشركُ باللهِ شيئاً .</div><div class="rule-source-line">ب- معَرَّفٌ بالإضافةِ ، نحو : نحن طلابَ العلمِ نجتهدُ في دروسنا .</div><div class="rule-source-line">ومنه قوله صلى الله عليه وسلم : &quot; إنَّا مَعْشَرَ الأنبياءِ لا نُوْرَثُ &quot;</div><div class="rule-source-line">الإعراب : نحنُ الطُّلاَّبَ نحبُّ العلمَ .                                                       نحنُ : ضمير رفع منفصل مبني على الضم في محل رفع مبتدأ.</div><div class="rule-source-line">الطُّلابَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة لفعل محذوف وجوبا، تقديره</div><div class="rule-source-line">( أَخُصُّ ) ، وجملة ( نحبُّ العلمَ ) في محلِّ رفع خبر نحن .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'الاختصاص اسم منصوب بفعل محذوف تقديره أخص، يوضح المقصود من ضمير قبله.'),
('Мединский курс (Том 4)', '4', 'بَابُ تَفَاعَلَ (порода تَفَاعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ تَفَاعَلَ</span><p class="rule-study-text">порода تَفَاعَلَ. باب تفاعل مزيد بالتاء والألف، ومن معانيه المشاركة والتظاهر بالصفة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ تَفَاعَلَ</span><span class="rule-term-ru">بَابُ تَفَاعَلَ — порода تَفَاعَلَ: взаимность или притворное проявление качества</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْلَا</span><span class="rule-term-ru">частица условия/побуждения; значение зависит от контекста</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : تَدَارَكَ ، تَعَامَلَ , تَعَاوَنَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفا الزيادة : التَّاء ، والألف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : تَفَاعُلٌ : ( بضم ما قبل آخره ) نحو : تَدَارَكَ : تَدَارُكٌ ، تَنَاوَمَ : تَنَاوُمٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">من معانيه : 1- الْمُشَارَكَةُ ، نحو : تَصَافَحَ الرَّجلانِ . تَقَاتَلَ الجنودُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- إِظْهَارُ مَا ليسَ في البَاطِنِ ، نحو : تَبَاكَى الطفلُ . تَعَامَى الرجلُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">| اسم الفاعل</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الرَّابِعُ</div><div class="rule-source-line">بَـابُ تَفَاعَلَ</div><div class="rule-source-line">من أمثلته : تَدَارَكَ ، تَعَامَلَ , تَعَاوَنَ .</div><div class="rule-source-line">حرفا الزيادة : التَّاء ، والألف .</div><div class="rule-source-line">مصدره : تَفَاعُلٌ : ( بضم ما قبل آخره ) نحو : تَدَارَكَ : تَدَارُكٌ ، تَنَاوَمَ : تَنَاوُمٌ .</div><div class="rule-source-line">من معانيه : 1- الْمُشَارَكَةُ ، نحو : تَصَافَحَ الرَّجلانِ . تَقَاتَلَ الجنودُ .</div><div class="rule-source-line">2- إِظْهَارُ مَا ليسَ في البَاطِنِ ، نحو : تَبَاكَى الطفلُ . تَعَامَى الرجلُ .</div><div class="rule-source-line">المشتقات :</div><div class="rule-source-line">اسم المفعول</div><div class="rule-source-line">| اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُتَدَارَكٌ</div><div class="rule-source-line">| مُتَدَارِكٌ</div><div class="rule-source-line">| تَدَارُكٌ</div><div class="rule-source-line">| تَدَارَكْ</div><div class="rule-source-line">| يَتَدَارَكُ</div><div class="rule-source-line">| تَدَارَكَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُتَعَامٍ</div><div class="rule-source-line">|   تَعَامٍ (أصله تَعَامُيٌ)</div><div class="rule-source-line">| تَعَامَ</div><div class="rule-source-line">| يَتَعَامَى</div><div class="rule-source-line">| تَعَامَى</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُتَعَاوِنٌ</div><div class="rule-source-line">| تَعَاوُنٌ</div><div class="rule-source-line">| تَعَاوَنْ</div><div class="rule-source-line">| يَتَعَاوَنُ</div><div class="rule-source-line">| تَعَاوَنَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| يجوز حذف إحدى التاءين إذا كان الفعل مضارعا مبدوءاً بالتاء , نحو قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] والأصل : ولا تَتَعاونوا . ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] والأصل : ولا تَتَنابزوا  .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'باب تفاعل مزيد بالتاء والألف، ومن معانيه المشاركة والتظاهر بالصفة.'),
('Мединский курс (Том 4)', '4', 'حَذْفُ حَرْفِ الْجَرِّ قَبْلَ الْمَصْدَرِ الْمُؤَوَّلِ (удаление предлога перед развёрнутым масдаром)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَذْفُ حَرْفِ الْجَرِّ قَبْلَ الْمَصْدَرِ الْمُؤَوَّلِ</span><p class="rule-study-text">удаление предлога перед развёрнутым масдаром. قد يحذف حرف الجر قبل المصدر المؤول ويبقى المصدر في محل جر أو نصب بحسب التحليل.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">حَذْفُ حَرْفِ الْجَرِّ قَبْلَ الْمَصْدَرِ الْمُؤَوَّلِ</span><span class="rule-term-ru">حَذْفُ حَرْفِ الْجَرِّ قَبْلَ الْمَصْدَرِ الْمُؤَوَّلِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">يجوز حذف حرف الجر الواقع قبل المصدر المؤوَّل .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : أمرنا الله أن نصلي، والتقدير: بأن نصلي، ونحو : أعوذ بالله أن أكون من الجاهلين،</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">والتقدير: مِنْ أَنْ أَكُونَ من الجاهلين. ومنه قوله تعالى: [موضع غير واضح في المصدر] أي : بِأنَّه لا إله إلا هو .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حذفُ حرفِ الجرِّ قبلَ المصدرِ الْمُؤَوَّلِ</div><div class="rule-source-line">يجوز حذف حرف الجر الواقع قبل المصدر المؤوَّل .</div><div class="rule-source-line">نحو : أمرنا الله أن نصلي، والتقدير: بأن نصلي، ونحو : أعوذ بالله أن أكون من الجاهلين،</div><div class="rule-source-line">والتقدير: مِنْ أَنْ أَكُونَ من الجاهلين. ومنه قوله تعالى: [موضع غير واضح في المصدر] أي : بِأنَّه لا إله إلا هو .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'قد يحذف حرف الجر قبل المصدر المؤول ويبقى المصدر في محل جر أو نصب بحسب التحليل.'),
('Мединский курс (Том 4)', '4', 'حَذْفُ الْوَاوِ مِنَ الْمُحَذَّرِ مِنْهُ (удаление وَ из конструкции предостережения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَذْفُ الْوَاوِ مِنَ الْمُحَذَّرِ مِنْهُ</span><p class="rule-study-text">удаление وَ из конструкции предостережения. في التحذير قد تذكر الواو أو تحذف بحسب الأسلوب.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَذْفُ الْوَاوِ مِنَ الْمُحَذَّرِ مِنْهُ</span><span class="rule-term-ru">حَذْفُ الْوَاوِ مِنَ الْمُحَذَّرِ مِنْهُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">يجوز حذف الواو من المحذر منه إذا كان ( المحذر منه ) مصدراً مؤوَّلاً ، نحو :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">* إِيَّاكَ والكَذِبَ         إيَّاكَ أَنْ تَكْذِبَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">* إِيَّاكُمْ والنَّومَ في الفَصْلِ        إِيَّاكُمْ أَنْ تَنَامُوا في الفصلِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حذفُ الواوِ من الْمُحَذَّرِ منهُ</div><div class="rule-source-line">يجوز حذف الواو من المحذر منه إذا كان ( المحذر منه ) مصدراً مؤوَّلاً ، نحو :</div><div class="rule-source-line">* إِيَّاكَ والكَذِبَ         إيَّاكَ أَنْ تَكْذِبَ .</div><div class="rule-source-line">* إِيَّاكُمْ والنَّومَ في الفَصْلِ        إِيَّاكُمْ أَنْ تَنَامُوا في الفصلِ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'في التحذير قد تذكر الواو أو تحذف بحسب الأسلوب.'),
('Мединский курс (Том 4)', '4', 'مَصْدَرُ الْمِثَالِ الْوَاوِيِّ (масдар глагола с первой корневой و)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَصْدَرُ الْمِثَالِ الْوَاوِيِّ</span><p class="rule-study-text">масдар глагола с первой корневой و. المثال الواوي قد تحذف واوه في المصدر ويعوض عنها تاء التأنيث.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرُ الْمِثَالِ الْوَاوِيِّ</span><span class="rule-term-ru">مَصْدَرُ الْمِثَالِ الْوَاوِيِّ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">المثالُ الواويُّ له مصدران :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أحدهما بالواو ، نحو : وَعَدَ : وَعْدٌ ، وَعَظَ : وَعْظٌ ، وَزَنَ : وَزْنٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">والثاني بحذف الواو , والتعويض عنها بتاء في آخر المصدر ، نحو : وَعَدَ : عِدَةٌ ،</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">وَعَظَ : عِظَةٌ ، وَزَنَ: زِنَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">مَصْدَرُ الْمِثَالِ الوَاوِيِّ</div><div class="rule-source-line">المثالُ الواويُّ له مصدران :</div><div class="rule-source-line">أحدهما بالواو ، نحو : وَعَدَ : وَعْدٌ ، وَعَظَ : وَعْظٌ ، وَزَنَ : وَزْنٌ .</div><div class="rule-source-line">والثاني بحذف الواو , والتعويض عنها بتاء في آخر المصدر ، نحو : وَعَدَ : عِدَةٌ ،</div><div class="rule-source-line">وَعَظَ : عِظَةٌ ، وَزَنَ: زِنَةٌ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'المثال الواوي قد تحذف واوه في المصدر ويعوض عنها تاء التأنيث.'),
('Мединский курс (Том 4)', '4', 'مَعْنَى لَيْتَ (значение لَيْتَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَعْنَى لَيْتَ</span><p class="rule-study-text">значение لَيْتَ. ليت من أخوات إنّ وتفيد التمني، سواء كان ممكناً أو بعيداً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَعْنَى لَيْتَ</span><span class="rule-term-ru">مَعْنَى لَيْتَ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنْ</span><span class="rule-term-ru">облегчённая لكنّ; не работает как إنّ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">تفيد ليت : التَّمَنَّي ، وهو نوعان :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- طَلَبُ مَالاَ طَمَعَ فِيهِ ، أي لا يمكن الحصول عليه ، نحو قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : ليتني طائرٌ ، ونحو : ليت الشَّبَابَ يعودُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- ما فيه عُسْرٌ ، أي يمكن  الحصول عليه ولكنه صعب الآن ، نحو قول الفقير :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ليت لي مالاً كثيراً ، ونحو : ليتني عَالِمٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">مَعْنَى لَيْتَ</div><div class="rule-source-line">تفيد ليت : التَّمَنَّي ، وهو نوعان :</div><div class="rule-source-line">1- طَلَبُ مَالاَ طَمَعَ فِيهِ ، أي لا يمكن الحصول عليه ، نحو قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : ليتني طائرٌ ، ونحو : ليت الشَّبَابَ يعودُ .</div><div class="rule-source-line">2- ما فيه عُسْرٌ ، أي يمكن  الحصول عليه ولكنه صعب الآن ، نحو قول الفقير :</div><div class="rule-source-line">ليت لي مالاً كثيراً ، ونحو : ليتني عَالِمٌ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'ليت من أخوات إنّ وتفيد التمني، سواء كان ممكناً أو بعيداً.'),
('Мединский курс (Том 4)', '4', 'لَا النَّافِيَةُ لِلْجِنْسِ (لا отрицания рода)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَا النَّافِيَةُ لِلْجِنْسِ</span><p class="rule-study-text">لا отрицания рода. لا النافية للجنس تعمل عمل إنّ وتنفي جنس الاسم كله إذا استوفت الشروط.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا النَّافِيَةُ لِلْجِنْسِ</span><span class="rule-term-ru">لَا النَّافِيَةُ لِلْجِنْسِ — لا отрицания рода: полностью отрицает класс</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">معناها : تنفي الحكمَ عن كلِّ جِنْسِ اسمِها .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">عملُها : تعملُ عملَ إِنَّ ، أي : تنصب الاسم ، وترفع الخبر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">شروطُها :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">1- أن تحتفظ بالترتيب الأصلي للجملة ، الاسم أولاً ، والخبر ثانيا .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">2- أن يكون اسمها وخبرها نكرتين .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">3- ألاَّ تقترن بحرف جر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أنواعُ اسمِها :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">لا النَّافِيَةُ لِلْجِنْسِ</div><div class="rule-source-line">معناها : تنفي الحكمَ عن كلِّ جِنْسِ اسمِها .</div><div class="rule-source-line">عملُها : تعملُ عملَ إِنَّ ، أي : تنصب الاسم ، وترفع الخبر .</div><div class="rule-source-line">شروطُها :</div><div class="rule-source-line">1- أن تحتفظ بالترتيب الأصلي للجملة ، الاسم أولاً ، والخبر ثانيا .</div><div class="rule-source-line">2- أن يكون اسمها وخبرها نكرتين .</div><div class="rule-source-line">3- ألاَّ تقترن بحرف جر .</div><div class="rule-source-line">أنواعُ اسمِها :</div><div class="rule-source-line">1- المضافُ : وهو منصوب ، نحو : لا طالبَ علمٍ مَكْرُوهٌ .</div><div class="rule-source-line">2- الشَّبِيهُ بالمضافِ : وهو منصوب ، نحو : لا طالباً العلمَ مكروهٌ .</div><div class="rule-source-line">( ذَُكِرَ هذان النوعان لِلْعِلْمِ بهما فقط ) .</div><div class="rule-source-line">3- المفردُ ، وهو موضوع دراستنا . والمراد بالمفرد : ما ليس مُضَافاً، ولا شَبِيهاً بالمضاف.</div><div class="rule-source-line">حكم المفرد : الِبنَاءُ على ما يُنْصَبُ به .</div><div class="rule-source-line">يُبْنَى اسم لا المفرد على ما ينصب به ، أي : يُنْظَرُ إلى علامة نصبه قبل دخول لا النافية للجنس ، فإن كانت الفتحة فعلامة بنائه الفتحة ، وإن كانت الكسرة فعلامة بنائه الكسرة ... وهكذا ، نحو : لا طالبَ في الفصل ، لا مُسْلِمَاتِ مُتَبَرَّجَاتٌ ، لا مُسْلِمِينَ كَاذِبُونَ .</div><div class="rule-source-line">ونحو قوله تعالى: [موضع غير واضح في المصدر] وقوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب :</div><div class="rule-source-line">لا إكراهَ في الدينِ .</div><div class="rule-source-line">لا : حرف لنفي الجنس مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">إكراهَ : اسم لا النافية للجنس مبني على الفتح في محل نصب .</div><div class="rule-source-line">في الدينِ : الجار والمجرور في محل رفع خبر لا النافية للجنس</div><div class="rule-source-line">لا مسلماتِ سَافِرَاتٌ .</div><div class="rule-source-line">لا : حرف لنفي الجنس مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">مسلماتِ : اسم لا النافية للجنس مبني على الكسرة في محل نصب .</div><div class="rule-source-line">سافراتٌ : خبر لا النافية للجنس مرفوع وعلامة رفعه الضمة الظاهرة .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'لا النافية للجنس تعمل عمل إنّ وتنفي جنس الاسم كله إذا استوفت الشروط.'),
('Мединский курс (Том 4)', '4', 'الْبَدَلُ (بدل — замена/пояснение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْبَدَلُ</span><p class="rule-study-text">بدل — замена/пояснение. البدل تابع مقصود بالحكم، وله أنواع مثل بدل الكل من الكل، وبعض من كل، واشتمال.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْبَدَلُ</span><span class="rule-term-ru">الْبَدَلُ — замена/поясняющее зависимое слово; تابع</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">البدلُ ، هو : التَّابِعُ المقصودُ بالحكمِ بلا واسطةٍ بينَه وبينَ متبوعِه .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أنواعـه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">1- بَدَلُ كُلٍّ مِن كُلٍّ : نحو : جاء أخوك هاشمٌ . هذا هو الخليفةُ أبو بكرٍ رضي الله عنه.</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">2- بدلُ بَعْضٍ من كلٍّ : يشترط أن يكون جزءا حقيقيا من المبدل منه , ويشتمل على ضمير يعود إلى المبدل منه .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : أكلتُ التفاحةَ نصفَها . عالج الطبيبُ المريضَ أنفَه . ومنه قوله تعالى :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">[موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الْبَدَلُ</div><div class="rule-source-line">البدلُ ، هو : التَّابِعُ المقصودُ بالحكمِ بلا واسطةٍ بينَه وبينَ متبوعِه .</div><div class="rule-source-line">أنواعـه :</div><div class="rule-source-line">1- بَدَلُ كُلٍّ مِن كُلٍّ : نحو : جاء أخوك هاشمٌ . هذا هو الخليفةُ أبو بكرٍ رضي الله عنه.</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">2- بدلُ بَعْضٍ من كلٍّ : يشترط أن يكون جزءا حقيقيا من المبدل منه , ويشتمل على ضمير يعود إلى المبدل منه .</div><div class="rule-source-line">نحو : أكلتُ التفاحةَ نصفَها . عالج الطبيبُ المريضَ أنفَه . ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">3- بدلُ الاشْتِمَالِ : يشترط أن يشتمل على ضمير يعود إلى المبدل منه , وهو ليس جزءاً حقيقياً من المبدل منه ، نحو : أعجبني الخطيبُ عِلْمُهُ .  انتفعتُ بالقرآنِ هَدْيِهِ .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">4- بدلُ الْمُبَايِنِ ، وهو بدلُ الْغَلَطِ ، أوالنَّسْيَانِ ( يقع كثيراً في الكلام المنطوق )</div><div class="rule-source-line">نحو : عاصمة المملكة جدةُ الرياضُ . صليت في المسجد النبويّ الظهرَ العصرَ .</div><div class="rule-source-line">لا يُشترط في البدل : أن يتبع المبدل منه في التنكير ، والتعريف، نحو قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">فـ ( ناصيةٍ ) بدل وهو نكرة والمبدل منه ( الناصية ) وهو معرفة . ومنه قوله تعالى : [موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  .</div><div class="rule-source-line">* يبدل الاسم من الاسم , كما في قوله تعالى: [موضع غير واضح في المصدر]</div><div class="rule-source-line">فـ ( قِتَالٍ ) بدل من ( الشهر الحرام ) وكلاهما اسمٌ مفرد .</div><div class="rule-source-line">ويبدل الفعل من الفعل , كما في قوله تعالى: [موضع غير واضح في المصدر] فـ ( يضاعفْ ) بدل من( يلقَ ) وكلاهما فعل .</div><div class="rule-source-line">وتبدل الجملة من الجملة ,كما في قوله تعالى: [موضع غير واضح في المصدر] ،</div><div class="rule-source-line">فـ ( أمدّكم ) الثانية بدل من ( أمدّكم ) الأولى , وكلاهما جملة .</div><div class="rule-source-line">وتبدل الجملة من الاسم المفرد, كما في قوله تعالى : [موضع غير واضح في المصدر] فجملة ( كيف خلقت ) بدل من الاسم المفرد ( الإبل ) .</div><div class="rule-source-line">الإعراب : جاء أخوك محمدٌ .</div><div class="rule-source-line">جاء : فعل ماضٍ مبني على الفتح .</div><div class="rule-source-line">أخوك : فاعل مرفوع وعلامة رفعه الواو ، وهو مضاف ، وضمير المخاطب (الكاف)</div><div class="rule-source-line">مبني على الفتح في محلِّ جرّ مضاف إليه .</div><div class="rule-source-line">محمدٌ : بدل كلّ من كلّ مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">انتفعت بالقرآنِ هَدْيِهِ .</div><div class="rule-source-line">انتفعت : فعل ماضٍ مبني على السكون لاتَّصاله بالتاء المتحركة ، والتاء : ضمير رفع</div><div class="rule-source-line">متصل مبني على الضم في محل رفع فاعل .</div><div class="rule-source-line">بالقرآنِ : الباء حرف جرّ مبني على الكسر لا محل له من الإعراب .</div><div class="rule-source-line">القرآن : اسم مجرور بالباء وعلامة جرّه الكسرة الظاهرة .</div><div class="rule-source-line">هَدْيِهِ : بدل اشتمال مجرور وعلامة جره الكسرة ، وهو مضاف ، والضمير ( هاء الغيبة )</div><div class="rule-source-line">مبني على الكسر في محل جر مضاف إليه .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 7, 'rule', 'البدل تابع مقصود بالحكم، وله أنواع مثل بدل الكل من الكل، وبعض من كل، واشتمال.'),
('Мединский курс (Том 4)', '4', 'الْأَحْرُفُ الْمُشَبَّهَةُ بِالْفِعْلِ (частицы, похожие на глагол)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَحْرُفُ الْمُشَبَّهَةُ بِالْفِعْلِ</span><p class="rule-study-text">частицы, похожие на глагол. إنّ وأخواتها تشبه الفعل في المعنى والعمل: تنصب الاسم وترفع الخبر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَحْرُفُ الْمُشَبَّهَةُ بِالْفِعْلِ</span><span class="rule-term-ru">الْأَحْرُفُ الْمُشَبَّهَةُ بِالْفِعْلِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنْ</span><span class="rule-term-ru">облегчённая لكنّ; не работает как إنّ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">معناها : إنَّ ، وأنَّ ( لِلتَّأْكِيدِ ) كَأَنَّ ( لِلتَّشْبِيهِ ) لَكِنَّ ( لِلاْسْتِدْرَاكِ ) لَيْتَ ( للتَّمَنَّي )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">لَعَلَّ ( للتَّرَجَّي ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الفرق بين ليتَ ، ولعلَّ : التَّرَجَّي ( لعلَّ ) يكون فيما يُمْكِنُ حصوله ، أما التَّمني ( ليت ) فيكون لِلْمُمْكِنِ حُصُولُه ، وغير الممكن .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">عملها : تنصب الاسم ، وترفع الخبر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أحكامها :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أ- يجوز أن يكون اسمها نكرة ، نحو : كأنَّ شيئاً لم يحدث .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ب- خبرها يكون مفردا ، وجملة فعلية واسمية ، وشبه جملة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الأحرفُ الْمُشَبَّهَةُ بِالْفِعْلِ</div><div class="rule-source-line">معناها : إنَّ ، وأنَّ ( لِلتَّأْكِيدِ ) كَأَنَّ ( لِلتَّشْبِيهِ ) لَكِنَّ ( لِلاْسْتِدْرَاكِ ) لَيْتَ ( للتَّمَنَّي )</div><div class="rule-source-line">لَعَلَّ ( للتَّرَجَّي ) .</div><div class="rule-source-line">الفرق بين ليتَ ، ولعلَّ : التَّرَجَّي ( لعلَّ ) يكون فيما يُمْكِنُ حصوله ، أما التَّمني ( ليت ) فيكون لِلْمُمْكِنِ حُصُولُه ، وغير الممكن .</div><div class="rule-source-line">عملها : تنصب الاسم ، وترفع الخبر .</div><div class="rule-source-line">أحكامها :</div><div class="rule-source-line">أ- يجوز أن يكون اسمها نكرة ، نحو : كأنَّ شيئاً لم يحدث .</div><div class="rule-source-line">ب- خبرها يكون مفردا ، وجملة فعلية واسمية ، وشبه جملة .</div><div class="rule-source-line">نحو قوله تعالى: [موضع غير واضح في المصدر] وقوله تعالى: [موضع غير واضح في المصدر]</div><div class="rule-source-line">وقوله تعالى : [موضع غير واضح في المصدر] إنَّ الطالبَ في الفصلِ . إنَّ الطائرَ فوقَ الشجرةِ .</div><div class="rule-source-line">ج- لا يجوز  أن يتقدم خبرها عليها ، ولا على اسمها ؛ فلا يجوز قولك : غفورٌ إنَّ اللهَ ، ولا يجوز : إنَّ غفورٌ اللهَ .</div><div class="rule-source-line">يجوز أن يتقدم خبرها إذا كان شبه جملة ، واسمها معرفة .</div><div class="rule-source-line">نحو قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : إِنَّ في قُلُوبِنَا الإيمانَ .</div><div class="rule-source-line">ويجب تقديم الخبر إذا كان شبه جملة ، واسم إنَّ نكرة .</div><div class="rule-source-line">نحو قوله تعالى : [موضع غير واضح في المصدر] وقوله تعالى : [موضع غير واضح في المصدر]</div><div class="rule-source-line">ونحو قولك : إنَّ في القَلْبِ إيماناً .</div><div class="rule-source-line">دخولُ نُونِ الْوِقَايَةِ عليها .</div><div class="rule-source-line">يجوز دخول نون الوقاية على إنَّ ، وأنَّ ، ولَكِنَّ ، وكَأَنَّ .</div><div class="rule-source-line">تقول : إنَّنِي ، وإنِّي - أنَّني ، وأنِّي - لكنَّني ، ولكنِّي - كَأَنَّنِي، وكَأنِّي .</div><div class="rule-source-line">أما ليت فلا تحذف منها إلا نادِراً ، وأما لعلَّ فيَقِلُّ دخول نون الوقاية عليها .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 8, 'rule', 'إنّ وأخواتها تشبه الفعل في المعنى والعمل: تنصب الاسم وترفع الخبر.'),
('Мединский курс (Том 4)', '4', 'جَمْعُ أَفْعَلَ الَّذِي مُؤَنَّثُهُ فَعْلَاءُ (множественное прилагательного أَفْعَلُ / فَعْلَاءُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَمْعُ أَفْعَلَ الَّذِي مُؤَنَّثُهُ فَعْلَاءُ</span><p class="rule-study-text">множественное прилагательного أَفْعَلُ / فَعْلَاءُ. أفعل الذي مؤنثه فعلاء يجمع غالباً على فُعْل.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">جَمْعُ أَفْعَلَ الَّذِي مُؤَنَّثُهُ فَعْلَاءُ</span><span class="rule-term-ru">جَمْعُ أَفْعَلَ الَّذِي مُؤَنَّثُهُ فَعْلَاءُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أَفْعَل الذي مؤنثه فَعْلاَء , يُجْمَعُ على ( فُعْل ) للمذكر والمؤنث ؛ تقول :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هذا الرَجُلُ أَعْرَجُ . هذه المرأةُ عَرْجَاءُ . هؤلاءِ الرجالُ عُرْجٌ . هؤلاءِ النَّسَاءُ عُرْجٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وتقول: أَبْكَمُ, بَكْمَاءُ ( بُكْمٌ ) للرجال والنساء . أَعْوَرُ, عَوْرَاءُ ( عُوْرٌ ) للرجال والنساء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">جَمْعُ أَفْعَلَ الَّذي مُؤَنَّثُهُ فَعْلاَءُ</div><div class="rule-source-line">أَفْعَل الذي مؤنثه فَعْلاَء , يُجْمَعُ على ( فُعْل ) للمذكر والمؤنث ؛ تقول :</div><div class="rule-source-line">هذا الرَجُلُ أَعْرَجُ . هذه المرأةُ عَرْجَاءُ . هؤلاءِ الرجالُ عُرْجٌ . هؤلاءِ النَّسَاءُ عُرْجٌ .</div><div class="rule-source-line">وتقول: أَبْكَمُ, بَكْمَاءُ ( بُكْمٌ ) للرجال والنساء . أَعْوَرُ, عَوْرَاءُ ( عُوْرٌ ) للرجال والنساء .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 9, 'rule', 'أفعل الذي مؤنثه فعلاء يجمع غالباً على فُعْل.'),
('Мединский курс (Том 4)', '5', 'بَابُ اِنْفَعَلَ (порода اِنْفَعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ اِنْفَعَلَ</span><p class="rule-study-text">порода اِنْفَعَلَ. باب انفعل مزيد بالهمزة والنون، ومعناه الغالب المطاوعة، ولا يكون إلا لازماً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اِنْفَعَلَ</span><span class="rule-term-ru">بَابُ اِنْفَعَلَ — порода اِنْفَعَلَ: مطاوعة, результат воздействия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : اِنْفَتَحَ ، اِنْكَسَرَ ، اِنْقَطَعَ ، اِنْجَلَى .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفا الزيادة : الهمزة ، والنون .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره :  اِنْفِعَالٌ ( كلّ فعل بُدِئَ بهمزة وصل كُسِرَ الحرف الثالث ، وزِيدَتْ ألف قبل آخره ) ، نحو : اِنْقَطَعَ : اِنْقِطَاعٌ ، اِنْكَسَرَ : اِنْكِسَارٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">معناه : الْمُطَاوَعَةُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : كَسَرْتُ الزُّجاجَ ، فَانْكَسَرَ الزّجاجُ . فَتَحْتُ البابَ ، فَانْفَتَحَ البابُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :                   ( هذا الباب لا يكون إلا لازما )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">| المصدر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الْخَامِسُ</div><div class="rule-source-line">بَـابُ اِنْفَعَلَ</div><div class="rule-source-line">من أمثلته : اِنْفَتَحَ ، اِنْكَسَرَ ، اِنْقَطَعَ ، اِنْجَلَى .</div><div class="rule-source-line">حرفا الزيادة : الهمزة ، والنون .</div><div class="rule-source-line">مصدره :  اِنْفِعَالٌ ( كلّ فعل بُدِئَ بهمزة وصل كُسِرَ الحرف الثالث ، وزِيدَتْ ألف قبل آخره ) ، نحو : اِنْقَطَعَ : اِنْقِطَاعٌ ، اِنْكَسَرَ : اِنْكِسَارٌ .</div><div class="rule-source-line">معناه : الْمُطَاوَعَةُ .</div><div class="rule-source-line">نحو : كَسَرْتُ الزُّجاجَ ، فَانْكَسَرَ الزّجاجُ . فَتَحْتُ البابَ ، فَانْفَتَحَ البابُ .</div><div class="rule-source-line">المشتقات :                   ( هذا الباب لا يكون إلا لازما )</div><div class="rule-source-line">اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُنْفَتِحٌ</div><div class="rule-source-line">| انْفِتَاحٌ</div><div class="rule-source-line">| انْفَتِحْ</div><div class="rule-source-line">| يَنْفَتِحُ</div><div class="rule-source-line">| انْفَتَحَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُنْقَطِعٌ</div><div class="rule-source-line">| انْقِطَاعٌ</div><div class="rule-source-line">| انْقَطِعْ</div><div class="rule-source-line">| يَنْقَطِعُ</div><div class="rule-source-line">| انْقَطَعَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُنْجَلٍ ( الْمُنْجَلِي )</div><div class="rule-source-line">| انْجِلاَءٌ</div><div class="rule-source-line">| انْجَلِ</div><div class="rule-source-line">| يَنْجَلِي</div><div class="rule-source-line">| انْجَلَى</div><div class="rule-source-line">|</div><div class="rule-source-line">|</div><div class="rule-source-line">إذا دخلتْ همزةُ الاستفهامِ على همزةِ الوَصْلِ حُذِفَتْ همزةُ الوصلِ ، نحو :</div><div class="rule-source-line">انفَتَحَ البابُ . أَنْفَتَحَ البابُ ؟        انْقَطَعَ الْحَبْلُ . أَنْقَطَعَ الحبلُ ؟</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'باب انفعل مزيد بالهمزة والنون، ومعناه الغالب المطاوعة، ولا يكون إلا لازماً.'),
('Мединский курс (Том 4)', '5', 'لَوْلَا (частица «если бы не» или побуждение «почему бы не»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَوْلَا</span><p class="rule-study-text">частица «если бы не» или побуждение «почему бы не». لولا تأتي للتحضيض أو الامتناع لوجود، ويختلف إعراب ما بعدها بحسب معناها.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْلَا</span><span class="rule-term-ru">لَوْلَا — частица условия/побуждения; значение зависит от контекста</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لولا : حرف امتناع لوجود ، تتضمَّن معنى الشَّرط ، وهي حرف غير جازم ، يقترن جوابها المثبت باللام ، ويُعْرَبُ ما بعدها مبتدأ خبره محذوف ، تقديره ( موجود ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الأمثلة :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لولا الإسلامُ لَضَلَلْنَا   .     لولا العِلْمُ لَجَهِلْناَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لولا اللهُ ما اهْتَدَيْنَا     .    لولا العِلْمُ ما عَرَفْناَ شيئاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">يجوز أن تدخل عليها أنَّ المصدريّة واسمها ، وخبرها .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : لولا أنَّ البردَ شديدٌ لَخَرَجْتُ من البيت ، والتقدير : لولا شِدَّةُ البردِ لخرجت من البيت .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">لَوْلاَ</div><div class="rule-source-line">لولا : حرف امتناع لوجود ، تتضمَّن معنى الشَّرط ، وهي حرف غير جازم ، يقترن جوابها المثبت باللام ، ويُعْرَبُ ما بعدها مبتدأ خبره محذوف ، تقديره ( موجود ) .</div><div class="rule-source-line">الأمثلة :</div><div class="rule-source-line">لولا الإسلامُ لَضَلَلْنَا   .     لولا العِلْمُ لَجَهِلْناَ .</div><div class="rule-source-line">لولا اللهُ ما اهْتَدَيْنَا     .    لولا العِلْمُ ما عَرَفْناَ شيئاً .</div><div class="rule-source-line">يجوز أن تدخل عليها أنَّ المصدريّة واسمها ، وخبرها .</div><div class="rule-source-line">نحو : لولا أنَّ البردَ شديدٌ لَخَرَجْتُ من البيت ، والتقدير : لولا شِدَّةُ البردِ لخرجت من البيت .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'لولا تأتي للتحضيض أو الامتناع لوجود، ويختلف إعراب ما بعدها بحسب معناها.'),
('Мединский курс (Том 4)', '5', 'لَوْمَا (частица побуждения, близкая к لولا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَوْمَا</span><p class="rule-study-text">частица побуждения, близкая к لولا. لوما تأتي مثل لولا في التحضيض غالباً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْمَا</span><span class="rule-term-ru">لَوْمَا — частица, близкая к لولا в побудительном употреблении</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْلَا</span><span class="rule-term-ru">частица условия/побуждения; значение зависит от контекста</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَوْمَا مِثْلُ ( لَوْلاَ ) ؛ تقول : لوما الإسلامُ لَضَلَلْناَ . لوما العِلْمُ ما عَرَفْنَا شيئاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب : لوما الإسلام لضللنا :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jazm"><span class="rule-example-ar" dir="rtl" lang="ar">لوما ، أو لولا : حرف امتناع لوجود مبني على السكون لا محل له من الإعراب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">الإسلامُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة، والخبر محذوف تقديره ( موجود ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">لضللنا : اللام حرف جواب وربط مبني على الفتح لا محل له من الإعراب ، وجملة الجواب من الفعل والفاعل ( لضللنا ) لا محل لها من الإعراب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">لَوْمَا</div><div class="rule-source-line">لَوْمَا مِثْلُ ( لَوْلاَ ) ؛ تقول : لوما الإسلامُ لَضَلَلْناَ . لوما العِلْمُ ما عَرَفْنَا شيئاً .</div><div class="rule-source-line">الإعراب : لوما الإسلام لضللنا :</div><div class="rule-source-line">لوما ، أو لولا : حرف امتناع لوجود مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">الإسلامُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة، والخبر محذوف تقديره ( موجود ) .</div><div class="rule-source-line">لضللنا : اللام حرف جواب وربط مبني على الفتح لا محل له من الإعراب ، وجملة الجواب من الفعل والفاعل ( لضللنا ) لا محل لها من الإعراب .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'لوما تأتي مثل لولا في التحضيض غالباً.'),
('Мединский курс (Том 4)', '5', 'إِعْرَابُ اسْمِ الْإِشَارَةِ نَعْتًا (разбор указательного имени как نعت)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِعْرَابُ اسْمِ الْإِشَارَةِ نَعْتًا</span><p class="rule-study-text">разбор указательного имени как نعت. اسم الإشارة قد يأتي نعتاً لما قبله إذا وافقه في التعريف والسياق.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابُ اسْمِ الْإِشَارَةِ نَعْتًا</span><span class="rule-term-ru">إِعْرَابُ اسْمِ الْإِشَارَةِ نَعْتًا — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">يُعْرَبُ اسمُ الإشارةِ نعتاً إذا وقع بعد :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">1- العَلَم ، نحو : من إبراهيمُ هذا ؟                                                             هذاْ : اسم إشارة مبني على السكون في محل رفع نعت .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- الْمُعَرَّف بالإضافة : نحو : أرني ساعتَكَ هذهِ .                                             هذهِ : اسم إشارة مبني على الكسر في محل نصب نعت .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">إعراب اسم الإشارة نعتا</div><div class="rule-source-line">يُعْرَبُ اسمُ الإشارةِ نعتاً إذا وقع بعد :</div><div class="rule-source-line">1- العَلَم ، نحو : من إبراهيمُ هذا ؟                                                             هذاْ : اسم إشارة مبني على السكون في محل رفع نعت .</div><div class="rule-source-line">2- الْمُعَرَّف بالإضافة : نحو : أرني ساعتَكَ هذهِ .                                             هذهِ : اسم إشارة مبني على الكسر في محل نصب نعت .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'اسم الإشارة قد يأتي نعتاً لما قبله إذا وافقه في التعريف والسياق.'),
('Мединский курс (Том 4)', '5', 'التَّغْلِيبُ (преобладание одного рода/лица в согласовании)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">التَّغْلِيبُ</span><p class="rule-study-text">преобладание одного рода/лица в согласовании. التغليب استعمال حكم فئة لأكثر من فئة عند الاجتماع، كغلبة المذكر على المؤنث.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">التَّغْلِيبُ</span><span class="rule-term-ru">التَّغْلِيبُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">التَّغليبُ ، هو : تفضيل ، أو تقديم أحد لفظين على الآخر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يُغَلَّبُ الْمُذَكَّرُ على الْمُؤنَّثِ ؛ تقول : أبنائي وبناتي يدرسون ؛ وتقول : النساء والرجال يُصَلّون .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فالخبر ( يدرسون ، ويصلون ) جَاءَ بلفظ المذكَّر تغليباً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ومن التغليب أيضاً قولهم : الأَبَوَانِ ( للأب ، والأم ) والْقَمَرَانِ ( للشمس ، والقمر ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">التَّغْلِيبُ</div><div class="rule-source-line">التَّغليبُ ، هو : تفضيل ، أو تقديم أحد لفظين على الآخر .</div><div class="rule-source-line">يُغَلَّبُ الْمُذَكَّرُ على الْمُؤنَّثِ ؛ تقول : أبنائي وبناتي يدرسون ؛ وتقول : النساء والرجال يُصَلّون .</div><div class="rule-source-line">فالخبر ( يدرسون ، ويصلون ) جَاءَ بلفظ المذكَّر تغليباً .</div><div class="rule-source-line">ومن التغليب أيضاً قولهم : الأَبَوَانِ ( للأب ، والأم ) والْقَمَرَانِ ( للشمس ، والقمر ) .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'التغليب استعمال حكم فئة لأكثر من فئة عند الاجتماع، كغلبة المذكر على المؤنث.'),
('Мединский курс (Том 4)', '5', 'إِضَافَةُ الظَّرْفِ إِلَى الْجُمْلَةِ (идафа обстоятельства к предложению)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِضَافَةُ الظَّرْفِ إِلَى الْجُمْلَةِ</span><p class="rule-study-text">идафа обстоятельства к предложению. قد يضاف الظرف إلى جملة بعده فيكون الظرف منصوباً أو مبنياً بحسب نوعه.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِضَافَةُ الظَّرْفِ إِلَى الْجُمْلَةِ</span><span class="rule-term-ru">إِضَافَةُ الظَّرْفِ إِلَى الْجُمْلَةِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">تُعْرَبُ الجملة الواقعة بعد الظرف : مضافاً إليه في محل جرّ , نحو : مات إبراهيمُ يومَ انْكَسَفَتِ الشَّمسُ . فجملة ( انكسفت الشمس ) في محل جرٍّ مضاف إليه ؛ لِوقوعها بعد الظرف ( يوم ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومن ذلك قولك : سافرتُ يومَ ظهرتِ النتائج . وُلِدْتُ يومَ زار الوزيرُ الجامعة .       ومنه قوله تعالى : [موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">إضافةُ الظرف إلى الجملة</div><div class="rule-source-line">تُعْرَبُ الجملة الواقعة بعد الظرف : مضافاً إليه في محل جرّ , نحو : مات إبراهيمُ يومَ انْكَسَفَتِ الشَّمسُ . فجملة ( انكسفت الشمس ) في محل جرٍّ مضاف إليه ؛ لِوقوعها بعد الظرف ( يوم ) .</div><div class="rule-source-line">ومن ذلك قولك : سافرتُ يومَ ظهرتِ النتائج . وُلِدْتُ يومَ زار الوزيرُ الجامعة .       ومنه قوله تعالى : [موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'قد يضاف الظرف إلى جملة بعده فيكون الظرف منصوباً أو مبنياً بحسب نوعه.'),
('Мединский курс (Том 4)', '6', 'بَابُ اِفْتَعَلَ (порода اِفْتَعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ اِفْتَعَلَ</span><p class="rule-study-text">порода اِفْتَعَلَ. باب افتعل مزيد بالهمزة والتاء، وقد يقع فيه إبدال بحسب الحرف الأول.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اِفْتَعَلَ</span><span class="rule-term-ru">بَابُ اِفْتَعَلَ — порода اِفْتَعَلَ: дополнительная ت после первой корневой</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : اِجْتَمَعَ ، اِنْتَصَرَ ، اِشْتَرَكَ ، اِنْتَهَى .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفا الزيادة : الهمزة ، والتاء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : اِفْتِعَالٌ ( كسرُ ثالثه ، وزيادة ألف قبل آخره ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : اِجْتَمَعَ  : اِجْتِمَاعٌ ، اِنْتَصَرَ : اِنْتِصَارٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من معانيه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">1- الْمُطَاوَعَةُ : نحو : رفعتُ الصَّوتَ، فارتفعَ الصَّوتُ . ملأتُ الكُوبَ، فامْتَلأَ الكُوبُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">2- الْمُشَارَكَةُ : نحو : اشْتَرَكَ ، اجْتَمَعَ ، اخْتَلَفَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ السَّادِسُ</div><div class="rule-source-line">بَـابُ اِفْتَعَلَ</div><div class="rule-source-line">من أمثلته : اِجْتَمَعَ ، اِنْتَصَرَ ، اِشْتَرَكَ ، اِنْتَهَى .</div><div class="rule-source-line">حرفا الزيادة : الهمزة ، والتاء .</div><div class="rule-source-line">مصدره : اِفْتِعَالٌ ( كسرُ ثالثه ، وزيادة ألف قبل آخره ) .</div><div class="rule-source-line">نحو : اِجْتَمَعَ  : اِجْتِمَاعٌ ، اِنْتَصَرَ : اِنْتِصَارٌ .</div><div class="rule-source-line">من معانيه :</div><div class="rule-source-line">1- الْمُطَاوَعَةُ : نحو : رفعتُ الصَّوتَ، فارتفعَ الصَّوتُ . ملأتُ الكُوبَ، فامْتَلأَ الكُوبُ .</div><div class="rule-source-line">2- الْمُشَارَكَةُ : نحو : اشْتَرَكَ ، اجْتَمَعَ ، اخْتَلَفَ .</div><div class="rule-source-line">المشتقات :</div><div class="rule-source-line">اسم المفعول</div><div class="rule-source-line">| اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُشْتَرِكٌ</div><div class="rule-source-line">| اِشْتِرَاكٌ</div><div class="rule-source-line">| اِشْتَرِكْ</div><div class="rule-source-line">| يَشْتَرِكُ</div><div class="rule-source-line">| اِشْتَرَكَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُنْتَهٍ  ( الْمُنْتَهِي )</div><div class="rule-source-line">| اِنْتِهَاءٌ</div><div class="rule-source-line">| اِنْتَهِ</div><div class="rule-source-line">| يَنْتَهِي</div><div class="rule-source-line">| اِنْتَهَى</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُمْتَحَنٌ</div><div class="rule-source-line">| مُمْتَحِنٌ</div><div class="rule-source-line">| اِمْتِحَانٌ</div><div class="rule-source-line">| اِمْتَحِنْ</div><div class="rule-source-line">| يَمْتَحِنُ</div><div class="rule-source-line">| اِمْتَحَنَ</div><div class="rule-source-line">|</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'باب افتعل مزيد بالهمزة والتاء، وقد يقع فيه إبدال بحسب الحرف الأول.'),
('Мединский курс (Том 4)', '6', 'الْإِبْدَالُ (замена звуков/букв в породе اِفْتَعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْإِبْدَالُ</span><p class="rule-study-text">замена звуков/букв в породе اِفْتَعَلَ. إذا جاورت تاء الافتعال بعض الحروف أبدلت حرفاً مناسباً للتخفيف.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْإِبْدَالُ</span><span class="rule-term-ru">الْإِبْدَالُ — фонетическая замена одной буквы другой</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الإبدال ، هو : إحْلاَلُ حرفٍ مكانَ حرفٍ آخرَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">القاعدة :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">1- إذا كانت فاء افتَعَل ( دالاً ، أو ذالاً ، أو زاياً ) أبدلت تاؤه ( دالاً ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : دَعَا : ادَّعَى -  زَحَمَ :  ازْدَحَمَ - ذَكَرَ : اذْدَكَرَ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">2- إذا كانت فاء افتعل ( صاداً , أو ضاداً , أو طاءً , أو ظاءً ) أبدلت تاؤه ( طاءً ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : صَفَا : اصْطَفَى - ضَجَعَ  : اضْطَجَعَ - طَلَعَ : اطَّلَعَ - ظَلَمَ : اظْطَلَمَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">3- إذا كانت فاء افتعل ( واواً ) أُبْدِلَت الواو ( تاء ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الإِبْدَالُ</div><div class="rule-source-line">الإبدال ، هو : إحْلاَلُ حرفٍ مكانَ حرفٍ آخرَ .</div><div class="rule-source-line">القاعدة :</div><div class="rule-source-line">1- إذا كانت فاء افتَعَل ( دالاً ، أو ذالاً ، أو زاياً ) أبدلت تاؤه ( دالاً ) .</div><div class="rule-source-line">نحو : دَعَا : ادَّعَى -  زَحَمَ :  ازْدَحَمَ - ذَكَرَ : اذْدَكَرَ</div><div class="rule-source-line">2- إذا كانت فاء افتعل ( صاداً , أو ضاداً , أو طاءً , أو ظاءً ) أبدلت تاؤه ( طاءً ) .</div><div class="rule-source-line">نحو : صَفَا : اصْطَفَى - ضَجَعَ  : اضْطَجَعَ - طَلَعَ : اطَّلَعَ - ظَلَمَ : اظْطَلَمَ .</div><div class="rule-source-line">3- إذا كانت فاء افتعل ( واواً ) أُبْدِلَت الواو ( تاء ) .</div><div class="rule-source-line">نحو : وَصَلَ : اتَّصَلَ - وَقَى : اتَّقَى .</div><div class="rule-source-line">وكذلك إذا كانت فاء افتعل ( همزة أصلية ) تُبدل الهمزة تاء ، نحو : أخذَ : اِتَّخَذَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'إذا جاورت تاء الافتعال بعض الحروف أبدلت حرفاً مناسباً للتخفيف.'),
('Мединский курс (Том 4)', '6', 'إِذَا الْفُجَائِيَّةُ (внезапная إذا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِذَا الْفُجَائِيَّةُ</span><p class="rule-study-text">внезапная إذا. إذا الفجائية تدخل غالباً على الجملة الاسمية وتفيد المفاجأة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِذَا الْفُجَائِيَّةُ</span><span class="rule-term-ru">إِذَا الْفُجَائِيَّةُ — внезапная إذا: «и вдруг»</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ظَنَّ</span><span class="rule-term-ru">глагол предположения; ставит два مفعول به</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">إذا الفجائية : حرف يُفِيدُ حُدَوثَ أَمْرٍ غَيْرِ مُتَوَقَّعٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">لا تأتي إذا الفجائية في أول الكلام . تدخل على الجملة الاسمية ( المبتدأ والخبر ) ويجوز الابتداء بالنكرة بعدها .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الأمثلة :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">خرجتُ فإذا أسدٌ بالباب . دخلت الفصل فإذا المديرُ جالسٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ظَنَنْتُكَ مُدرساً فإذا أنتَ طبيبٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">قال تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب : [موضع غير واضح في المصدر]</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">إِذَا الفُجَائِيَّةُ</div><div class="rule-source-line">إذا الفجائية : حرف يُفِيدُ حُدَوثَ أَمْرٍ غَيْرِ مُتَوَقَّعٍ .</div><div class="rule-source-line">لا تأتي إذا الفجائية في أول الكلام . تدخل على الجملة الاسمية ( المبتدأ والخبر ) ويجوز الابتداء بالنكرة بعدها .</div><div class="rule-source-line">الأمثلة :</div><div class="rule-source-line">خرجتُ فإذا أسدٌ بالباب . دخلت الفصل فإذا المديرُ جالسٌ .</div><div class="rule-source-line">ظَنَنْتُكَ مُدرساً فإذا أنتَ طبيبٌ .</div><div class="rule-source-line">قال تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب : [موضع غير واضح في المصدر]</div><div class="rule-source-line">الفاء : حرف زائد للتوكيد . وقيل للعطف ، وقيل غير ذلك .</div><div class="rule-source-line">إذا الفجائية : حرف مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">هي : ضمير رفع منفصل مبني على الفتح في محل رفع مبتدأ .</div><div class="rule-source-line">حيَّةٌ : خبر مرفوع و علامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">والجملة الاسمية من المبتدأ والخبر لا محل لها من الإعراب .</div><div class="rule-source-line">تسعى : الجملة الفعليَّة في محلِّ رفع نعت .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'إذا الفجائية تدخل غالباً على الجملة الاسمية وتفيد المفاجأة.'),
('Мединский курс (Том 4)', '6', 'ظَنَّ (ظنّ и два дополнения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ظَنَّ</span><p class="rule-study-text">ظنّ и два дополнения. ظنّ من أفعال القلوب، تنصب مفعولين أصلهما المبتدأ والخبر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ظَنَّ</span><span class="rule-term-ru">ظَنَّ — глагол предположения; ставит два مفعول به</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">تَنْصِبُ ظَنَّ مفعولين أصلهما المبتدأ ، والخبر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : ظننت الطالبَ غائبا . فـ ( الطالب) مفعول به أول , و( غائبا ) مفعول به ثانٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">يجوز أن تدخل ظنَّ على ( أنَّ ، وأنْ ) المصدريتين ، وحينئذ يكون المصدر المؤول في محل نصب سَدَّ مَسَدَّ مفعولي ظَنَّ ، نحو : ظننت أنَّ الطالبَ غائبٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">فالمصدر المؤول ( أنّ الطالبَ غائبٌ ) في محل نصب سَدَّ مَسَدَّ مفعولي ظنَّ ، أي : وقع موقعهما . ونحو : ما ظننت أَنْ يرسبَ الطالبُ ، فالمصدر المؤول ( أَنْ يرسبَ ) في محل نصب سدّ مسدّ مفعولي ظنّ . ومنه قوله تعالى : [موضع غير واضح في المصدر] وقوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">* يَظُنُّ محمدٌ الامتحانَ قريباً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">يظنُّ : فعل مضارع مرفوع وعلامة رفعه الضمة الظاهرة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">ظَنَّ</div><div class="rule-source-line">تَنْصِبُ ظَنَّ مفعولين أصلهما المبتدأ ، والخبر .</div><div class="rule-source-line">نحو : ظننت الطالبَ غائبا . فـ ( الطالب) مفعول به أول , و( غائبا ) مفعول به ثانٍ .</div><div class="rule-source-line">يجوز أن تدخل ظنَّ على ( أنَّ ، وأنْ ) المصدريتين ، وحينئذ يكون المصدر المؤول في محل نصب سَدَّ مَسَدَّ مفعولي ظَنَّ ، نحو : ظننت أنَّ الطالبَ غائبٌ .</div><div class="rule-source-line">فالمصدر المؤول ( أنّ الطالبَ غائبٌ ) في محل نصب سَدَّ مَسَدَّ مفعولي ظنَّ ، أي : وقع موقعهما . ونحو : ما ظننت أَنْ يرسبَ الطالبُ ، فالمصدر المؤول ( أَنْ يرسبَ ) في محل نصب سدّ مسدّ مفعولي ظنّ . ومنه قوله تعالى : [موضع غير واضح في المصدر] وقوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب :</div><div class="rule-source-line">* يَظُنُّ محمدٌ الامتحانَ قريباً .</div><div class="rule-source-line">يظنُّ : فعل مضارع مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">محمدٌ : فاعل مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">الامتحانَ : مفعول به أوَّل منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">قريباً : مفعول به ثانٍ منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">* ما ظَنَنْتُ أن يرسُبَ الطَّالبُ .</div><div class="rule-source-line">ما : حرف نفي مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">ظَنَنْتُ : فعل ماضِ مبني على السكون لا تصاله بالتاء المتحركة .</div><div class="rule-source-line">والتاء : ضمير رفع متصل مبني على الضم في محل رفع فاعل .</div><div class="rule-source-line">أَنْ : حرف نصب ومصدر مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">يرسبَ : فعل مضارع منصوب بأَنْ وعلامة نصبه الفتحة الظاهرة ، والمصدر المؤوَّل</div><div class="rule-source-line">( أن يرسب ) في محل نصب سدَّ مسدَّ مفعولي ظنّ .</div><div class="rule-source-line">الطَّالبُ : فاعل مرفوع وعلامة رفعه الضمة الظاهرة .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'ظنّ من أفعال القلوب، تنصب مفعولين أصلهما المبتدأ والخبر.'),
('Мединский курс (Том 4)', '6', 'صِيَغُ الْمُبَالَغَةِ (формы усиленного действующего имени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">صِيَغُ الْمُبَالَغَةِ</span><p class="rule-study-text">формы усиленного действующего имени. صيغ المبالغة تدل على كثرة الفعل أو قوته، ومنها فعّال وفعول ومفعال.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">صِيَغُ الْمُبَالَغَةِ</span><span class="rule-term-ru">صِيَغُ الْمُبَالَغَةِ — формы интенсивного اسم الفاعل</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">إذا أُرِيدَ باسمِ الفاعلِ الدَّلالةُ على المبالغةِ نُقِلَ إلى إحدى الصيغ الآتية :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">1- فَعَّالٌ : تَوَّابٌ ، غَفَّارٌ ؛ أَكَّالٌ ، شَرَّابٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- فَعِيْلٌ : عَلِيْمٌ ، سَمِيْعٌ ، بَصِيرٌ ، قَدِيرٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">3- فَعُوْلٌ : غَفُورٌ ، شَكُورٌ ؛ أَكُولٌ ، عَبُوسٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">4- مِفْعَالٌ : مِعْطَاءٌ ، مِقْدَامٌ ، مِفْرَاحٌ ، مِحْذَارٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">5- فََعِلٌ : حَذِرٌ ، فَطِنٌ ، جَزِعٌ ، فَرِحٌ ، مَزِقٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">صِيَغُ الْمُبَالَغَةِ</div><div class="rule-source-line">إذا أُرِيدَ باسمِ الفاعلِ الدَّلالةُ على المبالغةِ نُقِلَ إلى إحدى الصيغ الآتية :</div><div class="rule-source-line">1- فَعَّالٌ : تَوَّابٌ ، غَفَّارٌ ؛ أَكَّالٌ ، شَرَّابٌ .</div><div class="rule-source-line">2- فَعِيْلٌ : عَلِيْمٌ ، سَمِيْعٌ ، بَصِيرٌ ، قَدِيرٌ .</div><div class="rule-source-line">3- فَعُوْلٌ : غَفُورٌ ، شَكُورٌ ؛ أَكُولٌ ، عَبُوسٌ .</div><div class="rule-source-line">4- مِفْعَالٌ : مِعْطَاءٌ ، مِقْدَامٌ ، مِفْرَاحٌ ، مِحْذَارٌ .</div><div class="rule-source-line">5- فََعِلٌ : حَذِرٌ ، فَطِنٌ ، جَزِعٌ ، فَرِحٌ ، مَزِقٌ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'صيغ المبالغة تدل على كثرة الفعل أو قوته، ومنها فعّال وفعول ومفعال.'),
('Мединский курс (Том 4)', '6', 'دَخَلَهُ وَدَخَلَ فِيهِ (دخلَه и دخلَ فيه)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">دَخَلَهُ وَدَخَلَ فِيهِ</span><p class="rule-study-text">دخلَه и دخلَ فيه. دخل قد يتعدى بنفسه أو بحرف الجر في، مع فرق في الاستعمال.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">دَخَلَهُ وَدَخَلَ فِيهِ</span><span class="rule-term-ru">دَخَلَهُ وَدَخَلَ فِيهِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">إذا كان المدخولُ مَكَاناً , قلتَ : دخلتُ الغرفةَ ، ودخلتُ المسجدَ . ومنه قوله تعالى : [موضع غير واضح في المصدر] تقول ذلك بدون حرف الجر ( في ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أما إذا لم يكن المدخولُ مكاناً ؛ فتقول : دخلتُ في الامْتِحَانِ ، ودخلتُ في الإسلامِ ،</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله تعالى : [موضع غير واضح في المصدر] تقول ذلك بحرف الجر ( في ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">دَخَلَهُ , ودَخَلَ فِيهِ</div><div class="rule-source-line">إذا كان المدخولُ مَكَاناً , قلتَ : دخلتُ الغرفةَ ، ودخلتُ المسجدَ . ومنه قوله تعالى : [موضع غير واضح في المصدر] تقول ذلك بدون حرف الجر ( في ) .</div><div class="rule-source-line">أما إذا لم يكن المدخولُ مكاناً ؛ فتقول : دخلتُ في الامْتِحَانِ ، ودخلتُ في الإسلامِ ،</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] تقول ذلك بحرف الجر ( في ) .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'دخل قد يتعدى بنفسه أو بحرف الجر في، مع فرق في الاستعمال.'),
('Мединский курс (Том 4)', '7', 'بَابُ اِفْعَلَّ (порода اِفْعَلَّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ اِفْعَلَّ</span><p class="rule-study-text">порода اِفْعَلَّ. باب افعلّ يأتي غالباً للألوان والعيوب، ولا يكون إلا لازماً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اِفْعَلَّ</span><span class="rule-term-ru">بَابُ اِفْعَلَّ — порода اِفْعَلَّ: обычно цвета и телесные признаки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : اِحْمَرَّ ، اِصْفَرَّ ، اِغْبَرَّ ، اِعْوَجَّ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفا الزيادة : الهمزة ، والتَّضعيف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره: اِفْعِلاَلٌ (كسر ثالثه،وزيادة ألف قبل آخره) نحو: اِحْمَرَّ: اِحْمِرَارٌ ، اِغْبَرَّ: اِغْبِرَارٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">معناه : الْمُبَالَغَةُ . ( هذا الباب يأتي في الألوان ، والعيوب ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :                  ( هذا الباب لا يكون إلا لازما )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">| المصدر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">| المضارع</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ السَّابِعُ</div><div class="rule-source-line">بَـابُ اِفْعَلَّ</div><div class="rule-source-line">من أمثلته : اِحْمَرَّ ، اِصْفَرَّ ، اِغْبَرَّ ، اِعْوَجَّ</div><div class="rule-source-line">حرفا الزيادة : الهمزة ، والتَّضعيف .</div><div class="rule-source-line">مصدره: اِفْعِلاَلٌ (كسر ثالثه،وزيادة ألف قبل آخره) نحو: اِحْمَرَّ: اِحْمِرَارٌ ، اِغْبَرَّ: اِغْبِرَارٌ .</div><div class="rule-source-line">معناه : الْمُبَالَغَةُ . ( هذا الباب يأتي في الألوان ، والعيوب ) .</div><div class="rule-source-line">المشتقات :                  ( هذا الباب لا يكون إلا لازما )</div><div class="rule-source-line">اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُصْفَرٌّ ( أصله : مُصْفَرِرٌ )</div><div class="rule-source-line">| اِصْفِرَارٌ</div><div class="rule-source-line">| يَصْفَرُّ</div><div class="rule-source-line">| اِصْفَرَّ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُعْوَجٌّ ( أصله : مُعْوَجِجٌ )</div><div class="rule-source-line">| اِعْوِجَاجٌ</div><div class="rule-source-line">| يَعْوَجُّ</div><div class="rule-source-line">| اِعْوَجَّ</div><div class="rule-source-line">|</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'باب افعلّ يأتي غالباً للألوان والعيوب، ولا يكون إلا لازماً.'),
('Мединский курс (Том 4)', '7', 'بَابُ اِفْعَالَّ (порода اِفْعَالَّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ اِفْعَالَّ</span><p class="rule-study-text">порода اِفْعَالَّ. باب افعالّ يدل على المبالغة في اللون أو الصفة، ولا يكون إلا لازماً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اِفْعَالَّ</span><span class="rule-term-ru">بَابُ اِفْعَالَّ — порода اِفْعَالَّ: усиленный вариант цветов и признаков</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : اِحْمَارَّ ، اِصْفاَرَّ ، اِدْهَامَّ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أحرف الزيادة : الهمزة ، والألف ، والتَّضعيف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : اِفْعِيْلاَلٌ ( كسر ثالثه، وزيادة ألف قبل آخره ), نحو : اِحْمَارَّ : اِحْمِيْرَارٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">معناه : الْمُبَالَغَة . ( هذا الباب يأتي في الألوان فقط ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :                  ( هذا الباب لا يكون إلا لازما )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">| المصدر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">| المضارع</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">بـابُ اِفْعَالَّ</div><div class="rule-source-line">من أمثلته : اِحْمَارَّ ، اِصْفاَرَّ ، اِدْهَامَّ</div><div class="rule-source-line">أحرف الزيادة : الهمزة ، والألف ، والتَّضعيف .</div><div class="rule-source-line">مصدره : اِفْعِيْلاَلٌ ( كسر ثالثه، وزيادة ألف قبل آخره ), نحو : اِحْمَارَّ : اِحْمِيْرَارٌ .</div><div class="rule-source-line">معناه : الْمُبَالَغَة . ( هذا الباب يأتي في الألوان فقط ) .</div><div class="rule-source-line">المشتقات :                  ( هذا الباب لا يكون إلا لازما )</div><div class="rule-source-line">اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُحْمَارٌّ (أصله : مُحْمَارِرٌ )</div><div class="rule-source-line">| اِحْمِيْرَارٌ</div><div class="rule-source-line">| يَحْمَارُُّ</div><div class="rule-source-line">| اِحْمَارَّ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُبْيَاضٌّ (أصله : مُبْيَاضِضٌ)</div><div class="rule-source-line">| اِبْيِيضَاضٌ</div><div class="rule-source-line">| يَبْيَاضُّ</div><div class="rule-source-line">| اِبْيَاضَّ</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'باب افعالّ يدل على المبالغة في اللون أو الصفة، ولا يكون إلا لازماً.'),
('Мединский курс (Том 4)', '7', 'رَأَى (رأى и два значения управления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">رَأَى</span><p class="rule-study-text">رأى и два значения управления. رأى قد تكون بصرية فتنصب مفعولاً واحداً، أو قلبية فتنصب مفعولين.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">رَأَى</span><span class="rule-term-ru">رَأَى — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">| رَأَى</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">رأى نوعان :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">1-  بَصَرِيَّةٌ : تنصب مفعولا واحدا ، نحو : رأيت الطالبَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- قَلْبِيَّةٌ : بمعنى ( عَلِمَ ) تنصب مفعولين ، نحو : رأيت العلمَ نُوراً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : رأى محمدٌ الحقَّ واضحاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">| رَأَى</div><div class="rule-source-line">رأى نوعان :</div><div class="rule-source-line">1-  بَصَرِيَّةٌ : تنصب مفعولا واحدا ، نحو : رأيت الطالبَ .</div><div class="rule-source-line">2- قَلْبِيَّةٌ : بمعنى ( عَلِمَ ) تنصب مفعولين ، نحو : رأيت العلمَ نُوراً .</div><div class="rule-source-line">ونحو : رأى محمدٌ الحقَّ واضحاً .</div><div class="rule-source-line">مفعول به     مفعول به</div><div class="rule-source-line">أوّل           ثَانٍ</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'رأى قد تكون بصرية فتنصب مفعولاً واحداً، أو قلبية فتنصب مفعولين.'),
('Мединский курс (Том 4)', '7', 'مَا الْمَصْدَرِيَّةُ (ما масдарная)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ</span><p class="rule-study-text">ما масдарная. ما المصدرية تؤول مع ما بعدها بمصدر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ</span><span class="rule-term-ru">مَا الْمَصْدَرِيَّةُ — ما, превращающая последующее в смысл масдара</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ما المصدريَّةُ ، هي : التي تُؤَوَّلُ مع ما بعدها بمصدر صريح .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : وجدت قلمي بعد ما انتهت الصلاة ، المصدر المؤَوَّل ( ما انتهت ) في محل جر مضاف إليه ، والتقدير : بعد انتهاء الصلاة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : أتكلم الفرنسية كما يتكلم أهل فرنسا ، المصدر المؤول ( ما يتكلَّم ) في محل جر بحرف الجر الكاف ، والتقدير : كتكلُّمِ أهلِ فرنسا .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : يَسُرُّ المرءَ ما ذهبَ اللَّيَالي ، المصدر المؤوّل ( ما ذهب ) في محل رفع فاعل ، والتقدير : ذَهَابُ اللَّيالي .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله تعالى : [موضع غير واضح في المصدر] أي : بكونكم كافرين .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">وأحرف المصدر, هي : أنْ , وأنَّ , ومَا , وكَيْ , ولَوْ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">مَا الْمَصْدَرِيَّةُ</div><div class="rule-source-line">ما المصدريَّةُ ، هي : التي تُؤَوَّلُ مع ما بعدها بمصدر صريح .</div><div class="rule-source-line">نحو : وجدت قلمي بعد ما انتهت الصلاة ، المصدر المؤَوَّل ( ما انتهت ) في محل جر مضاف إليه ، والتقدير : بعد انتهاء الصلاة .</div><div class="rule-source-line">ونحو : أتكلم الفرنسية كما يتكلم أهل فرنسا ، المصدر المؤول ( ما يتكلَّم ) في محل جر بحرف الجر الكاف ، والتقدير : كتكلُّمِ أهلِ فرنسا .</div><div class="rule-source-line">ونحو : يَسُرُّ المرءَ ما ذهبَ اللَّيَالي ، المصدر المؤوّل ( ما ذهب ) في محل رفع فاعل ، والتقدير : ذَهَابُ اللَّيالي .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] أي : بكونكم كافرين .</div><div class="rule-source-line">وأحرف المصدر, هي : أنْ , وأنَّ , ومَا , وكَيْ , ولَوْ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'ما المصدرية تؤول مع ما بعدها بمصدر.'),
('Мединский курс (Том 4)', '7', 'عَسَى (عسى как глагол надежды)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عَسَى</span><p class="rule-study-text">عسى как глагол надежды. عسى من أفعال الرجاء، تعمل عمل كان، وخبرها غالباً مضارع مع أن.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">عَسَى</span><span class="rule-term-ru">عَسَى — глагол надежды из أفعال الرجاء</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">عسى : فعلٌ ماضٍ جامدٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">معناها:</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- التَّرَجِّي : نحو : عَسَى الطالبُ أَنْ ينجحَ ، أي : يُرْجَى أن ينجح .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- الإِشْفَاقُ : نحو : عَسَى المريضُ أَنْ يموتَ ، أي : يُخْشَى أن يموت .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">عملُها :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">تعملُ عملَ كان ، ترفع الاسم وتنصب الخبر ، وخبرها فعل مضارع يقترن بأنْ كثيرا .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أنوعها :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">عَسَى</div><div class="rule-source-line">عسى : فعلٌ ماضٍ جامدٌ .</div><div class="rule-source-line">معناها:</div><div class="rule-source-line">1- التَّرَجِّي : نحو : عَسَى الطالبُ أَنْ ينجحَ ، أي : يُرْجَى أن ينجح .</div><div class="rule-source-line">2- الإِشْفَاقُ : نحو : عَسَى المريضُ أَنْ يموتَ ، أي : يُخْشَى أن يموت .</div><div class="rule-source-line">عملُها :</div><div class="rule-source-line">تعملُ عملَ كان ، ترفع الاسم وتنصب الخبر ، وخبرها فعل مضارع يقترن بأنْ كثيرا .</div><div class="rule-source-line">أنوعها :</div><div class="rule-source-line">1- ناِقصَةٌ : أي لا تكتفي بِمرفوعها ، نحو : عَسَى اللهُ أَنْ يَغْفِرَ لَنَا  . عسيتُ أن أنجح .</div><div class="rule-source-line">2- تَامَّةٌ : أي تكتفي بِمرفوعها ، نحو : عسى أن يغفر اللهُ لنا . عَسَى أَنْ أنجحَ .</div><div class="rule-source-line">3- جَوَازُ الأَمْرَيْنِ التَّمَامُ ، والنُّقْصَانُ : وذلك إذا تقدم الاسم عليها , نحو :       الطَّالبُ عَسَى أَنْ ينجحَ ، فيجوز :</div><div class="rule-source-line">أ- اعتبارها ناقصة ، وذلك بتقدير ضمير مستتر يعود على الطالب ، نحو :</div><div class="rule-source-line">الطَّالبُ عسى أن ينجحَ ، اسم عسى : ضمير مستتر تقديره هو .</div><div class="rule-source-line">ب- اعتبارها تامَّة : وذلك بعدم تقدير الضمير .</div><div class="rule-source-line">وفي الحالتين يعربُ الاسمُ المتقدِّمُ مبتدأً خبره جملة عسى .</div><div class="rule-source-line">الإعراب :</div><div class="rule-source-line">عسى الطَّالبُ أن ينجحَ .</div><div class="rule-source-line">عسى : فعل ماض ناقص مبني على الفتحة المقدرة .</div><div class="rule-source-line">الطالبُ : اسم عسى مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">أن ينجحَ : المصدر المؤول في محل نصب خبر عسى .</div><div class="rule-source-line">عسى أن ينجحَ الطالبُ .</div><div class="rule-source-line">عسى : فعل ماض تام مبني على الفتحة المقدرة .</div><div class="rule-source-line">أن ينجحَ : المصدر المؤول في محل رفع فاعل عسى .</div><div class="rule-source-line">الطالبُ : فاعل لـ ( ينجح ) مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">الطالبُ عسى أن ينجحَ .</div><div class="rule-source-line">الطالبُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة, خبره جملة ( عسى أن ينجحَ ) .</div><div class="rule-source-line">عسى : • يجوز إعرابها ناقصة وذلك بتقدير اسمها : ضمير مستتر تقديره ( هو ) .</div><div class="rule-source-line">والمصدر المؤوَّل في محلِّ نصب خبرها .</div><div class="rule-source-line">• ويجوز إعرابها تامَّة,وذلك بعدم تقدير الضمير فيكون المصدر المؤوَّل في محل رفع فاعل .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'عسى من أفعال الرجاء، تعمل عمل كان، وخبرها غالباً مضارع مع أن.'),
('Мединский курс (Том 4)', '8', 'بَابُ اسْتَفْعَلَ (порода اسْتَفْعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ اسْتَفْعَلَ</span><p class="rule-study-text">порода اسْتَفْعَلَ. باب استفعل مزيد بالهمزة والسين والتاء، ومن معانيه الطلب والعدّ والوجدان.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اسْتَفْعَلَ</span><span class="rule-term-ru">بَابُ اسْتَفْعَلَ — порода اسْتَفْعَلَ: просьба, поиск или счёт качества</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : اِسْتَخْرَجَ , اِسْتَكْبَرَ , اِسْتَعَانَ , اِسْتَغْنَى .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أحرف الزيادة : الهمزة ، والسِّين ، والتَّاء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : اِسْتِفْعَالٌ ( كسر الثالث ، وزيادة الألف قبل الآخر ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : اسْتَكْبَرَ : اسْتِكْبَارٌ ، اسْتَغْنَى : اسْتِغْنَاءٌ ، اسْتَغْفَرَ : اسْتِغْفَارٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من معانيه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">1- الطَّلَبُ ، نحو : اسْتَغْفَرَ ، واسْتَهْدَى ، أي : طَلَبَ المغفرةَ ، والهِدايةَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">2- الصَّيْرُورَةُ ، نحو : اسْتَحْجَرَ الطِّينُ ، أي : صَارَ حَجَراً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الثَّامِنُ</div><div class="rule-source-line">بَـابُ اسْتَفْعَلَ</div><div class="rule-source-line">من أمثلته : اِسْتَخْرَجَ , اِسْتَكْبَرَ , اِسْتَعَانَ , اِسْتَغْنَى .</div><div class="rule-source-line">أحرف الزيادة : الهمزة ، والسِّين ، والتَّاء .</div><div class="rule-source-line">مصدره : اِسْتِفْعَالٌ ( كسر الثالث ، وزيادة الألف قبل الآخر ) .</div><div class="rule-source-line">نحو : اسْتَكْبَرَ : اسْتِكْبَارٌ ، اسْتَغْنَى : اسْتِغْنَاءٌ ، اسْتَغْفَرَ : اسْتِغْفَارٌ .</div><div class="rule-source-line">من معانيه :</div><div class="rule-source-line">1- الطَّلَبُ ، نحو : اسْتَغْفَرَ ، واسْتَهْدَى ، أي : طَلَبَ المغفرةَ ، والهِدايةَ .</div><div class="rule-source-line">2- الصَّيْرُورَةُ ، نحو : اسْتَحْجَرَ الطِّينُ ، أي : صَارَ حَجَراً .</div><div class="rule-source-line">3- التَّشَبُّهُ ، نحو : اسْتَرْجَلَتِ الْمَرْأَةُ ، أي : تَشَبَّهَتْ بالرَّجُلِ .</div><div class="rule-source-line">المشتقات :</div><div class="rule-source-line">اسم المفعول</div><div class="rule-source-line">| اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُسْتَخْرَجٌ</div><div class="rule-source-line">| مُسْتَخْرِجٌ</div><div class="rule-source-line">| اِسْتِخْرَاجٌ</div><div class="rule-source-line">| اِسْتَخْرِجْ</div><div class="rule-source-line">| يَسْتَخْرِجُ</div><div class="rule-source-line">| اِسْتَخْرَجَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُسْتَهْدًى</div><div class="rule-source-line">| مُسْتَهْدٍ</div><div class="rule-source-line">| اِسْتِهْدَاءٌ</div><div class="rule-source-line">| اِسْتَهْدِ</div><div class="rule-source-line">| يَسْتَهْدِي</div><div class="rule-source-line">| اِسْتَهْدَى</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُسْتَعِيْذٌ</div><div class="rule-source-line">| اِسْتِعَاذَةٌ</div><div class="rule-source-line">| اِسْتَعِذْ</div><div class="rule-source-line">|     يَسْتَعِيذُ</div><div class="rule-source-line">| اِسْتَعَاذَ</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'باب استفعل مزيد بالهمزة والسين والتاء، ومن معانيه الطلب والعدّ والوجدان.'),
('Мединский курс (Том 4)', '8', 'نَفْيُ الْمَاضِي بِـلَا النَّافِيَةِ (отрицание прошедшего через لا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَفْيُ الْمَاضِي بِـلَا النَّافِيَةِ</span><p class="rule-study-text">отрицание прошедшего через لا. لا قد تدخل على الماضي في سياقات مخصوصة، ولا سيما مع التكرار أو الدعاء.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">نَفْيُ الْمَاضِي بِـلَا النَّافِيَةِ</span><span class="rule-term-ru">نَفْيُ الْمَاضِي بِـلَا النَّافِيَةِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">| نَفْيُ الماضِي بِـ ( لا ) النَّافيةِ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">إذا نُفِيَ الماضي بـ ( لا ) النافية وجبَ تَكْرَارُهَا ، كما في قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : لا أكلتُ ولا شربتُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">| نَفْيُ الماضِي بِـ ( لا ) النَّافيةِ</div><div class="rule-source-line">إذا نُفِيَ الماضي بـ ( لا ) النافية وجبَ تَكْرَارُهَا ، كما في قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : لا أكلتُ ولا شربتُ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'لا قد تدخل على الماضي في سياقات مخصوصة، ولا سيما مع التكرار أو الدعاء.'),
('Мединский курс (Том 4)', '8', 'دُخُولُ قَدْ عَلَى الْجُمْلَةِ الْحَالِيَّةِ (قَدْ в предложении состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">دُخُولُ قَدْ عَلَى الْجُمْلَةِ الْحَالِيَّةِ</span><p class="rule-study-text">قَدْ в предложении состояния. قد تدخل على الفعل في جملة الحال، خصوصاً مع الماضي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">دُخُولُ قَدْ عَلَى الْجُمْلَةِ الْحَالِيَّةِ</span><span class="rule-term-ru">دُخُولُ قَدْ عَلَى الْجُمْلَةِ الْحَالِيَّةِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَقَدْ</span><span class="rule-term-ru">усиление прошедшего действия через لام и قد</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите صاحب الحال.</li><li>Проверьте, что الحال объясняет состояние во время действия.</li><li>Если الحال — جملة, найдите الرابط: واو الحال или ضمير.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">إذا دخلت واو الحال على جملة فعلية فعلها ماضٍ مُثْبَتٌ دخلت معها قد ، نحو :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">دخلتُ المسجدَ وقد ركعَ الإمامُ . جملة ( قد ركع الإمامُ ) في محل نصب حال ، ونحو : دخلت الفصل وقد شرح المدرِّسُ الدَّرسَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">دخولُ قَدْ على الجملةِ الْحَالِيَّةِ</div><div class="rule-source-line">إذا دخلت واو الحال على جملة فعلية فعلها ماضٍ مُثْبَتٌ دخلت معها قد ، نحو :</div><div class="rule-source-line">دخلتُ المسجدَ وقد ركعَ الإمامُ . جملة ( قد ركع الإمامُ ) في محل نصب حال ، ونحو : دخلت الفصل وقد شرح المدرِّسُ الدَّرسَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'قد تدخل على الفعل في جملة الحال، خصوصاً مع الماضي.'),
('Мединский курс (Том 4)', '8', 'نَوَاصِبُ الْفِعْلِ الْمُضَارِعِ (частицы نصب для مضارع)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَوَاصِبُ الْفِعْلِ الْمُضَارِعِ</span><p class="rule-study-text">частицы نصب для مضارع. من نواصب المضارع: أن، لن، كي، إذن، ولام التعليل وغيرها، وتجعل المضارع منصوباً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">نَوَاصِبُ الْفِعْلِ الْمُضَارِعِ</span><span class="rule-term-ru">نَوَاصِبُ الْفِعْلِ الْمُضَارِعِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">نواصب الفعل المضارع أربعة أحرف , هي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">أَنْ : حرف نصب , ومصدر , واستقبال , نحو : أُريدُ أنْ أشربَ ، تقدير المصدر :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أريدُ الشُّرْبَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو قوله تعالى : [موضع غير واضح في المصدر] والتقدير : يريدُ اللهُ التوبةَ عليكم .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">لَنْ : حرف نصب , ونفي , واستقبال , نحو : لن تذهبَ معي ، ونحو قوله تعالى :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">[موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">كَيْ : حرف نصب , ومصدر , واستقبال ، تقترن بلام التَّعْلِيل كثيرا ، فإن لم تقترن بها فهي مُقَدَّرَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">نَوَاصِبُ الفعلِ المضارعِ</div><div class="rule-source-line">نواصب الفعل المضارع أربعة أحرف , هي :</div><div class="rule-source-line">1- أَنْ</div><div class="rule-source-line">أَنْ : حرف نصب , ومصدر , واستقبال , نحو : أُريدُ أنْ أشربَ ، تقدير المصدر :</div><div class="rule-source-line">أريدُ الشُّرْبَ .</div><div class="rule-source-line">ونحو قوله تعالى : [موضع غير واضح في المصدر] والتقدير : يريدُ اللهُ التوبةَ عليكم .</div><div class="rule-source-line">لَنْ 2-</div><div class="rule-source-line">لَنْ : حرف نصب , ونفي , واستقبال , نحو : لن تذهبَ معي ، ونحو قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">3- كَيْ</div><div class="rule-source-line">كَيْ : حرف نصب , ومصدر , واستقبال ، تقترن بلام التَّعْلِيل كثيرا ، فإن لم تقترن بها فهي مُقَدَّرَةٌ .</div><div class="rule-source-line">قد تتصل بها ( لا ) النَّافية ، وتكتب هكذا ( لِكَيْلاَ ) .</div><div class="rule-source-line">الأمثلة :</div><div class="rule-source-line">جئت لكي أتعلَّمَ ، التقدير : جئتُ للتعلُّمِ .</div><div class="rule-source-line">ونحو: جِئْتُ كي أتعلَّمَ . اِجْتَهَدْتُ لكيلا أرسبَ. ومنه قوله تعالى: [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب : جئتُ لكي أتعلَّمَ .</div><div class="rule-source-line">جئت : جاء فعل ماضٍ مبني على السكون لاتصاله بالتاء ، والتاء ضمير رفع مبني على الضم في محل رفع فاعل .</div><div class="rule-source-line">اللام : حرف جر مبني على الكسر لا محل له من الإعراب .</div><div class="rule-source-line">كي : حرف نصب ومصدر مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">أتعلَّمَ : فعل مضارع منصوب بكي وعلامة نصبه الفتحة الظاهرة ، والمصدر المؤول</div><div class="rule-source-line">(كي أتعلَّم ) في محل جر .</div><div class="rule-source-line">4- إِذَنْ</div><div class="rule-source-line">إِذَنْ : حرف نصب ، وجواب ، وجزاء ، واستقبال .</div><div class="rule-source-line">شروط عملها :</div><div class="rule-source-line">1- أَنْ تَتَصَدَّرَ جملةَ الجوابِ .</div><div class="rule-source-line">2- أن لا يَفْصِلَ بينها وبين الفعل فاصلٌ ، إلا القسم ، أو ( لا ) النافية .</div><div class="rule-source-line">3- أن يكون زمن الفعل الاستقبال .</div><div class="rule-source-line">وتتحقق هذه الشروط في نحو : سأزورك غداً . إذن أنتظرَك .</div><div class="rule-source-line">ويجوز : إذن واللهِ أنتظرَك ( الفصل بالقسم ) ويجوز : إذن لا أخرجَ من البيت ( الفصل بـ لا النافية ) .</div><div class="rule-source-line">فإذا لم يتحقق شرط من الشروط السابقة لم تعمل النصب .</div><div class="rule-source-line">نحو : أنا إذن أنتظرُك : بالرفع ؛ لأن إذن غير متصدرة .</div><div class="rule-source-line">إذن أنا أنتظرُك : بالرفع ؛ لأن الفاصل ليس القسم ، أولا النافية .</div><div class="rule-source-line">إذن أنتظرُك الآن : بالرفع ؛ لأن زمن الفعل الحال .</div><div class="rule-source-line">الإعراب : إذنْ أنتظرَك .</div><div class="rule-source-line">إذنْ : حرف نصب مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">أنتظرَك : فعل مضارع منصوب بإذن وعلامة نصبه الفتحة الظاهرة ، والفاعل ضمير</div><div class="rule-source-line">مستتر ، تقديره ( أنا ) .</div><div class="rule-source-line">وكاف المخاطب : ضمير نصب متصل مبني على الفتح في محل نصب مفعول به .</div><div class="rule-source-line">إذنْ وَاللهِ أنتظرَك .</div><div class="rule-source-line">إذن : حرف نصب مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">والله : الواو للقسم حرف جر مبني على الفتح لا محل له من الإعراب .</div><div class="rule-source-line">ولفظ الجلالة ( الله ) اسم مجرور وعلامة جره الكسرة الظاهرة .</div><div class="rule-source-line">وجملة القسم لا محل لها من الإعراب ؛ لأنها جملةٌ اعْتِرَاضِيَّةٌ .</div><div class="rule-source-line">أنتظرَك : تُعْرَبُ الإعرابَ السَّابِقَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'من نواصب المضارع: أن، لن، كي، إذن، ولام التعليل وغيرها، وتجعل المضارع منصوباً.'),
('Мединский курс (Том 4)', '8', 'مَعَانِي جَعَلَ (значения جَعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَعَانِي جَعَلَ</span><p class="rule-study-text">значения جَعَلَ. جعل تأتي بمعنى خلق أو صيّر أو شرع، ويختلف عملها بحسب المعنى.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَعَانِي جَعَلَ</span><span class="rule-term-ru">مَعَانِي جَعَلَ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ظَنَّ</span><span class="rule-term-ru">глагол предположения; ставит два مفعول به</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">لِجَعَلَ أربعةُ معانٍ ، هي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- معنى صَيَّرَ ، نحو : جعل الله الخمرَ حراماً ، جعلت الماءَ ثلجاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- معنى ظَنَّ ، نحو قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : أجعلتني مديراً ؟ وهي بهذين المعنيين تنصب مفعولين .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">3- من أفعال الشروع ، تعمل عمل كان ، نحو : جعل المدرِّسُ يَشْرَحُ الدَّرسَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">فـ ( المدرِّسُ ) اسم جعل مرفوع , وجملة ( يشرح ) في محل نصب خبر جعل .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">4- معنى أَوْجَدَ : وهو فعل تَامٌّ ينصب مفعولا واحدا ، نحو : جعلَ اللهُ الهواءَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">مَعَانِي جَعَلَ</div><div class="rule-source-line">لِجَعَلَ أربعةُ معانٍ ، هي :</div><div class="rule-source-line">1- معنى صَيَّرَ ، نحو : جعل الله الخمرَ حراماً ، جعلت الماءَ ثلجاً .</div><div class="rule-source-line">2- معنى ظَنَّ ، نحو قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : أجعلتني مديراً ؟ وهي بهذين المعنيين تنصب مفعولين .</div><div class="rule-source-line">3- من أفعال الشروع ، تعمل عمل كان ، نحو : جعل المدرِّسُ يَشْرَحُ الدَّرسَ .</div><div class="rule-source-line">فـ ( المدرِّسُ ) اسم جعل مرفوع , وجملة ( يشرح ) في محل نصب خبر جعل .</div><div class="rule-source-line">4- معنى أَوْجَدَ : وهو فعل تَامٌّ ينصب مفعولا واحدا ، نحو : جعلَ اللهُ الهواءَ .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'جعل تأتي بمعنى خلق أو صيّر أو شرع، ويختلف عملها بحسب المعنى.'),
('Мединский курс (Том 4)', '8', 'فَتْحُ يَاءِ الْمُتَكَلِّمِ (фатха на ياء المتكلم)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">فَتْحُ يَاءِ الْمُتَكَلِّمِ</span><p class="rule-study-text">фатха на ياء المتكلم. ياء المتكلم قد تفتح في مواضع للتخفيف أو لالتقاء الساكنين بحسب التركيب.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">فَتْحُ يَاءِ الْمُتَكَلِّمِ</span><span class="rule-term-ru">فَتْحُ يَاءِ الْمُتَكَلِّمِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">1- تكونُ ياءُ المتكلِّمِ مفتوحةً مع اسمٍ آخرُه ألفٌ ساكنةٌ ، نحو : عَصَاْيَ ، وفَتَاْيَ ، ودُنْيَاْيَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">2- وتكونُ مفتوحةً كذلك مع اسم آخره ياء ساكنة ، نحو : غَسَلْتُ عَيْنَيَّ ، ويَدَيَّ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">فَتْحُ يَاءِ المتكلَّم</div><div class="rule-source-line">1- تكونُ ياءُ المتكلِّمِ مفتوحةً مع اسمٍ آخرُه ألفٌ ساكنةٌ ، نحو : عَصَاْيَ ، وفَتَاْيَ ، ودُنْيَاْيَ .</div><div class="rule-source-line">2- وتكونُ مفتوحةً كذلك مع اسم آخره ياء ساكنة ، نحو : غَسَلْتُ عَيْنَيَّ ، ويَدَيَّ .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'ياء المتكلم قد تفتح في مواضع للتخفيف أو لالتقاء الساكنين بحسب التركيب.'),
('Мединский курс (Том 4)', '9', 'الْأَفْعَالُ الرُّبَاعِيَّةُ الْمُجَرَّدَةُ وَالْمَزِيدَةُ (четырёхбуквенные простые и производные глаголы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَفْعَالُ الرُّبَاعِيَّةُ الْمُجَرَّدَةُ وَالْمَزِيدَةُ</span><p class="rule-study-text">четырёхбуквенные простые и производные глаголы. الرباعي المجرد كل حروفه أصلية، والرباعي المزيد زيد على أصوله حرف أو أكثر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَفْعَالُ الرُّبَاعِيَّةُ الْمُجَرَّدَةُ وَالْمَزِيدَةُ</span><span class="rule-term-ru">الْأَفْعَالُ الرُّبَاعِيَّةُ الْمُجَرَّدَةُ وَالْمَزِيدَةُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">أَوَّلاً : الفعلُ الرُّبَاعِيُّ المجرَّدُ ، له بابٌ واحدٌ هو : بَـابُ فَعْلَلَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : دَحْرَجَ ، بَعْثَرَ ، زَلْزَلَ ، وَسْوَسَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : فِعْلاَلٌ ، وفَعْلَلَةٌ ، نحو : زَلْزَلَ : زِلْزَالٌ ، وزَلْزَلَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">| اسم الفاعل</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">| المصدر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">| الأمر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ التَّاسِعُ</div><div class="rule-source-line">الأفعالُ الرُّبَاعِيَّةُ الْمُجَرَّدَةُ ، والْمَزِيدَةُ</div><div class="rule-source-line">أَوَّلاً : الفعلُ الرُّبَاعِيُّ المجرَّدُ ، له بابٌ واحدٌ هو : بَـابُ فَعْلَلَ .</div><div class="rule-source-line">من أمثلته : دَحْرَجَ ، بَعْثَرَ ، زَلْزَلَ ، وَسْوَسَ .</div><div class="rule-source-line">مصدره : فِعْلاَلٌ ، وفَعْلَلَةٌ ، نحو : زَلْزَلَ : زِلْزَالٌ ، وزَلْزَلَةٌ .</div><div class="rule-source-line">المشتقات :</div><div class="rule-source-line">اسم المفعول</div><div class="rule-source-line">| اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُبَعْثَرٌ</div><div class="rule-source-line">| مُبَعْثِرٌ</div><div class="rule-source-line">| بَعْثَرَةٌ</div><div class="rule-source-line">| بَعْثِرْ</div><div class="rule-source-line">| يُبَعْثِرُ</div><div class="rule-source-line">| بَعْثَرَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| ( لازم )</div><div class="rule-source-line">| مُوَسْوِسٌ</div><div class="rule-source-line">| وَسْوَسَةٌ،و وِسْوَاسٌ</div><div class="rule-source-line">| وَسْوِسْ</div><div class="rule-source-line">| يُوَسْوِسُ</div><div class="rule-source-line">| وَسْوَسَ</div><div class="rule-source-line">|</div><div class="rule-source-line">|</div><div class="rule-source-line">ثَانِياً : الفعلُ الرُّبَاعِيُّ الْمَزِيدُ ، وهو نوعان :</div><div class="rule-source-line">1- مزيد بحرف واحد .</div><div class="rule-source-line">2- مزيد بحرفين .</div><div class="rule-source-line">1- المزيدُ بحرفٍ واحدٍ ، له بابٌ واحدٌ ، هو :</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'الرباعي المجرد كل حروفه أصلية، والرباعي المزيد زيد على أصوله حرف أو أكثر.'),
('Мединский курс (Том 4)', '9', 'بَابُ تَفَعْلَلَ (порода تَفَعْلَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ تَفَعْلَلَ</span><p class="rule-study-text">порода تَفَعْلَلَ. تفعلل من مزيد الرباعي بحرف واحد، ومعناه غالباً المطاوعة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ تَفَعْلَلَ</span><span class="rule-term-ru">بَابُ تَفَعْلَلَ — производная четырёхбуквенная порода تَفَعْلَلَ</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ تَفَعَّلَ</span><span class="rule-term-ru">порода تَفَعَّلَ: принятие действия, постепенность или усилие</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : تَدَحْرَجَ ، تَبَعْثَرَ ، تَزَلْزَلَ ، تَوَسْوَسَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرف الزيادة : التَّاء في أَوَّله .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : تَفَعْلُلٌ ( ضمّ ما قبل آخره ) نحو : تَدَحْرَجَ : تَدَحْرُجٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">معناه : المطاوعةُ ، نحو : دَحْرَجْتُ الكرةَ ، فَتَدَحْرَجَتِ الكرةُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :                    ( هذا الباب لا يكون إلا لازما )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">| المصدر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">| الأمر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">بَـابُ تَفَعْلَلَ</div><div class="rule-source-line">من أمثلته : تَدَحْرَجَ ، تَبَعْثَرَ ، تَزَلْزَلَ ، تَوَسْوَسَ .</div><div class="rule-source-line">حرف الزيادة : التَّاء في أَوَّله .</div><div class="rule-source-line">مصدره : تَفَعْلُلٌ ( ضمّ ما قبل آخره ) نحو : تَدَحْرَجَ : تَدَحْرُجٌ .</div><div class="rule-source-line">معناه : المطاوعةُ ، نحو : دَحْرَجْتُ الكرةَ ، فَتَدَحْرَجَتِ الكرةُ .</div><div class="rule-source-line">المشتقات :                    ( هذا الباب لا يكون إلا لازما )</div><div class="rule-source-line">اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">|   مُتَبَعْثِرٌ</div><div class="rule-source-line">| تَبَعْثُرٌ</div><div class="rule-source-line">| تَبَعْثَرْ</div><div class="rule-source-line">| يَتَبَعْثَرُ</div><div class="rule-source-line">| تَبَعْثَرَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُتَزَلْزِلٌ</div><div class="rule-source-line">| تَزَلْزُلٌ</div><div class="rule-source-line">| تَزَلْزَلْ</div><div class="rule-source-line">| يَتَزَلْزَلُ</div><div class="rule-source-line">| تَزَلْزَلَ</div><div class="rule-source-line">|</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'تفعلل من مزيد الرباعي بحرف واحد، ومعناه غالباً المطاوعة.'),
('Мединский курс (Том 4)', '9', 'بَابُ اِفْعَنْلَلَ (порода اِفْعَنْلَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ اِفْعَنْلَلَ</span><p class="rule-study-text">порода اِفْعَنْلَلَ. افعَنْلَل من مزيد الرباعي بحرفين: الهمزة والنون، ولا يكون إلا لازماً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اِفْعَنْلَلَ</span><span class="rule-term-ru">بَابُ اِفْعَنْلَلَ — производная четырёхбуквенная порода اِفْعَنْلَلَ</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">2- المزيدُ بحرفينِ ، له بابانِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : اِحْرَنْجَمَ ، اِفْرَنْقَعَ ، اِقْعَنْسَسَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفا الزيادة : الهمزة ، والنُّون .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : اِفْعِنْلاَلٌ ( كسر ثالثه ، وزيادة ألف قبل آخره ) نحو : اِفْرَنْقَعَ : اِفْرِنْقَاعٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">معناه : الْمُطَاوَعَةُ ، نحو : فَرْقَعْتُ الأَصَابِعَ ، فافْرَنْقَعَتِ الأَصَابِعُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : حَرْجَمْتُ الإبِلَ ، فَاحْرَنْجَمَتِ الإبلُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :                    ( هذا الباب لا يكون إلا لازما )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">2- المزيدُ بحرفينِ ، له بابانِ :</div><div class="rule-source-line">أ- بَـابُ اِفْعَنْلَلَ</div><div class="rule-source-line">من أمثلته : اِحْرَنْجَمَ ، اِفْرَنْقَعَ ، اِقْعَنْسَسَ .</div><div class="rule-source-line">حرفا الزيادة : الهمزة ، والنُّون .</div><div class="rule-source-line">مصدره : اِفْعِنْلاَلٌ ( كسر ثالثه ، وزيادة ألف قبل آخره ) نحو : اِفْرَنْقَعَ : اِفْرِنْقَاعٌ .</div><div class="rule-source-line">معناه : الْمُطَاوَعَةُ ، نحو : فَرْقَعْتُ الأَصَابِعَ ، فافْرَنْقَعَتِ الأَصَابِعُ .</div><div class="rule-source-line">ونحو : حَرْجَمْتُ الإبِلَ ، فَاحْرَنْجَمَتِ الإبلُ .</div><div class="rule-source-line">المشتقات :                    ( هذا الباب لا يكون إلا لازما )</div><div class="rule-source-line">اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">|  مُحْرَنْجِمٌ</div><div class="rule-source-line">| اِحْرِنْجَامٌ</div><div class="rule-source-line">| اِحْرَنْجِمْ</div><div class="rule-source-line">| يَحْرَنْجِمُ</div><div class="rule-source-line">| اِحْرَنْجَمَ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُفْرَنْقِعٌ</div><div class="rule-source-line">| اِفْرِنْقَاعٌ</div><div class="rule-source-line">| اِفْرَنْقِعْ</div><div class="rule-source-line">| يَفْرَنْقِعُ</div><div class="rule-source-line">| اِفْرَنْقَعَ</div><div class="rule-source-line">|</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'افعَنْلَل من مزيد الرباعي بحرفين: الهمزة والنون، ولا يكون إلا لازماً.'),
('Мединский курс (Том 4)', '9', 'بَابُ افْعَلَلَّ (порода افْعَلَلَّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَابُ افْعَلَلَّ</span><p class="rule-study-text">порода افْعَلَلَّ. افعللّ من مزيد الرباعي بحرفين، ومعناه المبالغة ولا يكون إلا لازماً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ افْعَلَلَّ</span><span class="rule-term-ru">بَابُ افْعَلَلَّ — производная четырёхбуквенная порода افْعَلَلَّ</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اِفْعَلَّ</span><span class="rule-term-ru">порода اِفْعَلَّ: обычно цвета и телесные признаки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите باب и дополнительные буквы زيادات.</li><li>Сверьте الماضي، المضارع، الأمر، المصدر، اسم الفاعل واسم المفعول по таблице шарха.</li><li>Проверьте значение باب: تعدية، مطاوعة، مشاركة، مبالغة или طلب.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">من أمثلته : اِطْمَأَنَّ ، اِقْشَعَرَّ ، اِشْمَأَزَّ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حرفا الزيادة : الهمزة ، والتَّضعيف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مصدره : اِفْعِلْلاَلٌ ( كسر ثالثه ، وزيادة ألف قبل آخره ) نحو : اِشْمَأَزَّ : اِشْمِئْزَازٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">معناه : الْمُبَالَغَةُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">المشتقات :                    ( هذا الباب لا يكون إلا لازماً )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">| المصدر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">| الأمر</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">ب- بَـابُ افْعَلَلَّ</div><div class="rule-source-line">من أمثلته : اِطْمَأَنَّ ، اِقْشَعَرَّ ، اِشْمَأَزَّ .</div><div class="rule-source-line">حرفا الزيادة : الهمزة ، والتَّضعيف .</div><div class="rule-source-line">مصدره : اِفْعِلْلاَلٌ ( كسر ثالثه ، وزيادة ألف قبل آخره ) نحو : اِشْمَأَزَّ : اِشْمِئْزَازٌ .</div><div class="rule-source-line">معناه : الْمُبَالَغَةُ .</div><div class="rule-source-line">المشتقات :                    ( هذا الباب لا يكون إلا لازماً )</div><div class="rule-source-line">اسم الفاعل</div><div class="rule-source-line">| المصدر</div><div class="rule-source-line">| الأمر</div><div class="rule-source-line">| المضارع</div><div class="rule-source-line">| الماضي</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُطْمَئِنٌّ</div><div class="rule-source-line">| اِطْمِئْنَانٌ</div><div class="rule-source-line">| اِطْمَئِنَّ</div><div class="rule-source-line">| يَطْمَئِنُّ</div><div class="rule-source-line">| اِطْمَأَنَّ</div><div class="rule-source-line">|</div><div class="rule-source-line">| مُقْشَعِرٌّ</div><div class="rule-source-line">| اِقْشِعْرَارٌ</div><div class="rule-source-line">| اِقْشَعِرَّ</div><div class="rule-source-line">| يَقْشَعِرُّ</div><div class="rule-source-line">| اِقْشَعَرَّ</div><div class="rule-source-line">|</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'افعللّ من مزيد الرباعي بحرفين، ومعناه المبالغة ولا يكون إلا لازماً.'),
('Мединский курс (Том 4)', '9', 'ضَمِيرُ الْفَصْلِ (разделительное местоимение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمِيرُ الْفَصْلِ</span><p class="rule-study-text">разделительное местоимение. ضمير الفصل يفصل بين الخبر والتابع، ويفيد الحصر والتأكيد.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمِيرُ الْفَصْلِ</span><span class="rule-term-ru">ضَمِيرُ الْفَصْلِ — разделительное местоимение между подлежащим и خبر/تابع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْبَدَلُ</span><span class="rule-term-ru">замена/поясняющее зависимое слово; تابع</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите тип ضمير: منفصل، متصل или مستتر.</li><li>Проверьте его место: رفع، نصب или جرّ.</li><li>Если местоимений несколько, соблюдайте порядок رتب الضمائر.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">| ضَمِيرُ الفَصْلِ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">ضميرُ رفعٍ مُنفصلٍ ، يُؤْتَى به لِلْفَصْلِ بين ما هو خبرٌ ، وما هو تابعٌ .  : ضميرُ الفصلِ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">والمراد بالتَّابع هنا : النَّعْتُ ، والْبَدَلُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">شروطه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">1- أن يكونَ ضميرَ رفعٍ منفصلاً .                   2- أن يُطابق ما قبله .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ويُشترط في ما قبله ، وما بعده أن يكونا معرفتين .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">فائدته :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">| ضَمِيرُ الفَصْلِ</div><div class="rule-source-line">ضميرُ رفعٍ مُنفصلٍ ، يُؤْتَى به لِلْفَصْلِ بين ما هو خبرٌ ، وما هو تابعٌ .  : ضميرُ الفصلِ</div><div class="rule-source-line">والمراد بالتَّابع هنا : النَّعْتُ ، والْبَدَلُ .</div><div class="rule-source-line">شروطه :</div><div class="rule-source-line">1- أن يكونَ ضميرَ رفعٍ منفصلاً .                   2- أن يُطابق ما قبله .</div><div class="rule-source-line">ويُشترط في ما قبله ، وما بعده أن يكونا معرفتين .</div><div class="rule-source-line">فائدته :</div><div class="rule-source-line">1- الْحَصْرُ .              2- التَّأكيدُ .              3- إلزامُ أن يكون ما بعده خبراً .</div><div class="rule-source-line">إعرابه : لا محلَّ له من الإعراب .</div><div class="rule-source-line">الأمثلة :</div><div class="rule-source-line">محمدٌ هُوَ النَّاجِحُ . فاطمةُ هِيَ الفائزةُ . أولئكَ هُمُ الفائزون . أولئك هُنَّ المؤمناتُ .</div><div class="rule-source-line">توضيح :</div><div class="rule-source-line">إذا قلت : محمدٌ الناجحُ ، جاز إعراب الناجح خبراً ، وجاز إعرابه نعتاً على اعتبار أنّ الخبرَ آتٍ . فإذا أدخلت ضمير الفصل ، وقلت : محمد هو الناجح ، صار إعراب الناجح خبراً لا غير .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'ضمير الفصل يفصل بين الخبر والتابع، ويفيد الحصر والتأكيد.'),
('Мединский курс (Том 4)', '9', 'إِقَامَةُ إِذَا الْفُجَائِيَّةِ مَقَامَ الْفَاءِ (замена فاء ответа внезапной إذا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِقَامَةُ إِذَا الْفُجَائِيَّةِ مَقَامَ الْفَاءِ</span><p class="rule-study-text">замена فاء ответа внезапной إذا. قد تقوم إذا الفجائية مقام الفاء في جواب الشرط في مواضع.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِقَامَةُ إِذَا الْفُجَائِيَّةِ مَقَامَ الْفَاءِ</span><span class="rule-term-ru">إِقَامَةُ إِذَا الْفُجَائِيَّةِ مَقَامَ الْفَاءِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِذَا الْفُجَائِيَّةُ</span><span class="rule-term-ru">внезапная إذا: «и вдруг»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">إذا كان جواب الشرط جملة اسمية وجب اقترانه بالفاء . يجوز إقامة إذا الفجائية مقام</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الفاء , كما في قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">وقوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">* يُشترط أن يكون الجواب جملة اسميّة ، وأن تكون أداة الشرط ( إنْ ، أو إذا ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">إقامةُ إذا الفجائيَّةِ مَقَامَ الفَاءِ</div><div class="rule-source-line">إذا كان جواب الشرط جملة اسمية وجب اقترانه بالفاء . يجوز إقامة إذا الفجائية مقام</div><div class="rule-source-line">الفاء , كما في قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">وقوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">* يُشترط أن يكون الجواب جملة اسميّة ، وأن تكون أداة الشرط ( إنْ ، أو إذا ) .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'قد تقوم إذا الفجائية مقام الفاء في جواب الشرط في مواضع.'),
('Мединский курс (Том 4)', '9', 'تَقَدُّمُ هَمْزَةِ الِاسْتِفْهَامِ عَلَى حُرُوفِ الْعَطْفِ (вопросительная хамза перед союзами)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَقَدُّمُ هَمْزَةِ الِاسْتِفْهَامِ عَلَى حُرُوفِ الْعَطْفِ</span><p class="rule-study-text">вопросительная хамза перед союзами. همزة الاستفهام لها الصدارة فتتقدم على حروف العطف.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">تَقَدُّمُ هَمْزَةِ الِاسْتِفْهَامِ عَلَى حُرُوفِ الْعَطْفِ</span><span class="rule-term-ru">تَقَدُّمُ هَمْزَةِ الِاسْتِفْهَامِ عَلَى حُرُوفِ الْعَطْفِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">تتقدم همزة  الاستفهام على حروف العطف ، نحو قوله تعالى : [موضع غير واضح في المصدر] ..  [موضع غير واضح في المصدر]</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">وقوله تعالى : [موضع غير واضح في المصدر] ..  [موضع غير واضح في المصدر]  .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أما أخواتها فَتَتَأَخَّرُ عن حروف العطف ، كما في قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : وهل هذا جائز ؟ وكيف حصل ذلك ؟</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">تَقَدُّمُ همزةِ الاستفهامِ على حروفِ الْعَطْفِ</div><div class="rule-source-line">تتقدم همزة  الاستفهام على حروف العطف ، نحو قوله تعالى : [موضع غير واضح في المصدر] ..  [موضع غير واضح في المصدر]</div><div class="rule-source-line">وقوله تعالى : [موضع غير واضح في المصدر] ..  [موضع غير واضح في المصدر]  .</div><div class="rule-source-line">أما أخواتها فَتَتَأَخَّرُ عن حروف العطف ، كما في قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : وهل هذا جائز ؟ وكيف حصل ذلك ؟</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 7, 'rule', 'همزة الاستفهام لها الصدارة فتتقدم على حروف العطف.'),
('Мединский курс (Том 4)', '9', 'مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ (ما масдарно-временная)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ</span><p class="rule-study-text">ما масдарно-временная. ما المصدرية الظرفية تؤول مع الفعل بمصدر في معنى الظرف الزماني.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ</span><span class="rule-term-ru">مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ — ما со значением масдара и времени</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ</span><span class="rule-term-ru">ما, превращающая последующее в смысл масдара</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">هي : التي تُؤَوَّلُ بمصدر صريح مع الدَّلالة على الظَّرفيَّة .  ما المصدريَّة الظَّرفيَّة ،</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو قول أبي بكر رضي الله عنه : &quot; أَطِيعُونِي مَا أَطَعْتُ اللهَ فِيكُمْ &quot; أي : مُدَّةَ إطاعتي اللهَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو قولك : سيبقى الإسلامُ ما بَقِيَ الْعَالَمُ ، أي : مدة بقاء العالم .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : سأجلسُ على هذا الكرسيَّ ما لم يأتِ صاحبُه ، أي : مدة عَدَمِ إِتْيَانِ صاحبِه .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">وكما في قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب : [موضع غير واضح في المصدر]</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jazm"><span class="rule-example-ar" dir="rtl" lang="ar">ما : حرفُ مصدرٍ مبنيٌّ على السُّكون لا محل له من الإعراب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">مَا الْمَصْدَرِيَّةُ الظَّرْفِيَّةُ</div><div class="rule-source-line">هي : التي تُؤَوَّلُ بمصدر صريح مع الدَّلالة على الظَّرفيَّة .  ما المصدريَّة الظَّرفيَّة ،</div><div class="rule-source-line">نحو قول أبي بكر رضي الله عنه : &quot; أَطِيعُونِي مَا أَطَعْتُ اللهَ فِيكُمْ &quot; أي : مُدَّةَ إطاعتي اللهَ .</div><div class="rule-source-line">ونحو قولك : سيبقى الإسلامُ ما بَقِيَ الْعَالَمُ ، أي : مدة بقاء العالم .</div><div class="rule-source-line">ونحو : سأجلسُ على هذا الكرسيَّ ما لم يأتِ صاحبُه ، أي : مدة عَدَمِ إِتْيَانِ صاحبِه .</div><div class="rule-source-line">وكما في قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب : [موضع غير واضح في المصدر]</div><div class="rule-source-line">ما : حرفُ مصدرٍ مبنيٌّ على السُّكون لا محل له من الإعراب .</div><div class="rule-source-line">دُمْتُ : فعلٌ ماضٍ ناقصٌ مبنيٌّ على السُّكون لاتصاله بالتاء ، والتاء في محل رفع اسم دام .</div><div class="rule-source-line">حيًّا : خبر دام منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">والمصدر المؤوَّل ( ما دمت حَيًّا ) في محل نصب مفعول فيه .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 8, 'rule', 'ما المصدرية الظرفية تؤول مع الفعل بمصدر في معنى الظرف الزماني.'),
('Мединский курс (Том 4)', '9', 'جَوَازُ فَكِّ الْإِدْغَامِ فِي الْفِعْلِ الْمُضَعَّفِ (допустимость раскрытия идгама в удвоенном глаголе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَوَازُ فَكِّ الْإِدْغَامِ فِي الْفِعْلِ الْمُضَعَّفِ</span><p class="rule-study-text">допустимость раскрытия идгама в удвоенном глаголе. في المضاعف قد يفك الإدغام في بعض التصاريف أو القراءات.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">جَوَازُ فَكِّ الْإِدْغَامِ فِي الْفِعْلِ الْمُضَعَّفِ</span><span class="rule-term-ru">جَوَازُ فَكِّ الْإِدْغَامِ فِي الْفِعْلِ الْمُضَعَّفِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jazm"><span class="rule-example-ar" dir="rtl" lang="ar">يجوزُ فكُّ الإدغامِ في الفعل المضارع المضعَّف المجزوم ، وفي الأمر منه .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : لَمْ يَشُدَّ ، ويجوز فَكُّ الإدغام ؛ فتقول : لم يَشْدُدْ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : شُدَّ ، ويجوز : اُشْدُدْ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله تعالى: [موضع غير واضح في المصدر] وقوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">جَوَازُ فَكَّ الإِدْغَامِ في الفعلِ الْمُضَعَّفِ</div><div class="rule-source-line">يجوزُ فكُّ الإدغامِ في الفعل المضارع المضعَّف المجزوم ، وفي الأمر منه .</div><div class="rule-source-line">نحو : لَمْ يَشُدَّ ، ويجوز فَكُّ الإدغام ؛ فتقول : لم يَشْدُدْ .</div><div class="rule-source-line">ونحو : شُدَّ ، ويجوز : اُشْدُدْ .</div><div class="rule-source-line">ومنه قوله تعالى: [موضع غير واضح في المصدر] وقوله تعالى : [موضع غير واضح في المصدر] .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 9, 'rule', 'في المضاعف قد يفك الإدغام في بعض التصاريف أو القراءات.'),
('Мединский курс (Том 4)', '9', 'مِنْ التَّبْعِيضِيَّةُ وَالْمُنَادَى الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ (частичная مِنْ и обращение с ياء المتكلم)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مِنْ التَّبْعِيضِيَّةُ وَالْمُنَادَى الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ</span><p class="rule-study-text">частичная مِنْ и обращение с ياء المتكلم. من قد تفيد التبعيض، والمنادى المضاف إلى ياء المتكلم له أوجه في الاستعمال.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مِنْ التَّبْعِيضِيَّةُ وَالْمُنَادَى الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ</span><span class="rule-term-ru">مِنْ التَّبْعِيضِيَّةُ وَالْمُنَادَى الْمُضَافُ إِلَى يَاءِ الْمُتَكَلِّمِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">قال تعالى : [موضع غير واضح في المصدر] مِنْ مَا رزقناهم : هذه مِنْ التَّبْعِيضِيَّة ، وهي حرف جر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فمعنى ( مِمَّا رزقناهم ) أي : بعض الذي رزقناهم .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قولك : مِنَ الطُّلابِ مَنْ يعرف الإنكليزيَّة ، أي : بَعْضُهم يعرِف الإنكليزية ، ونحو : أنت مِن أحسنِ الطُّلابِ أدباً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">المنادى المضاف إلى ياء المتكلم يجوز في يائه خمسة أوجه , هي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">1- حذف الياء مع بقاء الكسرة , نحو : يا رَبِّ ، ويا قَوْمِ . وهذا هو الأكثر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- إثبات الياء ساكنة , نحو : يا رَبِّيْ ، ويا قَوْمِيْ . وهذا أقلُّ من الأوَّل .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">3- إثبات الياء مفتوحة , نحو : يا رَبِّيَ ، ويا قَوْمِيَ . وهذا أقلُّ من السَّابق .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">مِنْ التَّبْعِيضِيَّة</div><div class="rule-source-line">قال تعالى : [موضع غير واضح في المصدر] مِنْ مَا رزقناهم : هذه مِنْ التَّبْعِيضِيَّة ، وهي حرف جر .</div><div class="rule-source-line">فمعنى ( مِمَّا رزقناهم ) أي : بعض الذي رزقناهم .</div><div class="rule-source-line">ومنه قولك : مِنَ الطُّلابِ مَنْ يعرف الإنكليزيَّة ، أي : بَعْضُهم يعرِف الإنكليزية ، ونحو : أنت مِن أحسنِ الطُّلابِ أدباً .</div><div class="rule-source-line">الْمُنَادَى الْمُضَافُ إلى ياءِ الْمُتَكَلِّمِ</div><div class="rule-source-line">المنادى المضاف إلى ياء المتكلم يجوز في يائه خمسة أوجه , هي :</div><div class="rule-source-line">1- حذف الياء مع بقاء الكسرة , نحو : يا رَبِّ ، ويا قَوْمِ . وهذا هو الأكثر .</div><div class="rule-source-line">2- إثبات الياء ساكنة , نحو : يا رَبِّيْ ، ويا قَوْمِيْ . وهذا أقلُّ من الأوَّل .</div><div class="rule-source-line">3- إثبات الياء مفتوحة , نحو : يا رَبِّيَ ، ويا قَوْمِيَ . وهذا أقلُّ من السَّابق .</div><div class="rule-source-line">4- قَلْبُ الياء ألفا , نحو : يا رَبَّا ، ويا قَوْمَا . ويجوز أن تلحقها هاء السَّكت عند الوقف؛</div><div class="rule-source-line">: يا رَبَّاه ، ويا قَوْمَاهْ . فتقول</div><div class="rule-source-line">5- قَلْبُ الياء ألفا , ثم حَذْفُ الألفِ , ويُسْتَغْنَى عنها بالفتحة , نحو : يا رَبَّ ، ويا قَوْمَ .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 10, 'rule', 'من قد تفيد التبعيض، والمنادى المضاف إلى ياء المتكلم له أوجه في الاستعمال.'),
('Мединский курс (Том 4)', '10', 'الضَّمَائِرُ (местоимения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الضَّمَائِرُ</span><p class="rule-study-text">местоимения. الضمائر منها بارز ومستتر، والمنفصل والمتصل، ولها مواقع رفع ونصب وجر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمَائِرُ</span><span class="rule-term-ru">الضَّمَائِرُ — местоимения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنْ</span><span class="rule-term-ru">облегчённая لكنّ; не работает как إنّ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الضَّمائرُ: ألفاظ موضوعة للكناية عن المتكلم، أو المخاطب، أو الغائب, نيابة عن الأسماء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فائدتها : الاختصار .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أنواعها : تنقسم الضمائر إلى قسمين :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أ- ضمائرُ بَارِزَةٌ .                  ب- ضمائرُ مُسْتَتِرَةٌ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">تنقسم الضمائر البَارِزَةُ إلى قسمين :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أ- ضمائرُ مُتَّصِلَةٌ                   ب- ضمائرُ مُنْفَصِلَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَوَّلاً : الضَّمَائِرُ الْمُتَّصِلَةُ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الْعَاشِرُ</div><div class="rule-source-line">الضَّمَائِرُ</div><div class="rule-source-line">الضَّمائرُ: ألفاظ موضوعة للكناية عن المتكلم، أو المخاطب، أو الغائب, نيابة عن الأسماء .</div><div class="rule-source-line">فائدتها : الاختصار .</div><div class="rule-source-line">أنواعها : تنقسم الضمائر إلى قسمين :</div><div class="rule-source-line">أ- ضمائرُ بَارِزَةٌ .                  ب- ضمائرُ مُسْتَتِرَةٌ</div><div class="rule-source-line">تنقسم الضمائر البَارِزَةُ إلى قسمين :</div><div class="rule-source-line">أ- ضمائرُ مُتَّصِلَةٌ                   ب- ضمائرُ مُنْفَصِلَةٌ .</div><div class="rule-source-line">أَوَّلاً : الضَّمَائِرُ الْمُتَّصِلَةُ</div><div class="rule-source-line">الضمائرُ المتَّصلة ، هي : التي لا يُبْدَأُ بها في النطق , ولا تَقَعُ بعد ( إلاَّ )</div><div class="rule-source-line">كالتاء ، والهاء في قولك : رأيتُهُ .</div><div class="rule-source-line">تنقسم الضمائر المتصلة باعتبار موقعها الإعرابي إلى ثلاثة أقسام ، هي :</div><div class="rule-source-line">أ- ضمائرُ رفعٍ , وهي :</div><div class="rule-source-line">1- التاء المتحركة , نحو : ذَهَبْتَُِ .</div><div class="rule-source-line">2- واو الجماعة , نحو : ذَهَبُوا ، يَذْهَبُونَ ، اذْهَبُوا .</div><div class="rule-source-line">3- ألف الاثنين , نحو : ذَهَبَا ، يَذْهَبَانِ ، اذْهَبَا .</div><div class="rule-source-line">4- ياء المخاطبة , نحو : تَذْهَبِينَ ، اذْهَبِي .</div><div class="rule-source-line">5- نون النسوة , نحو : ذَهَبْنَ ، يَذْهَبْنَ ، اذْهَبْنَ .</div><div class="rule-source-line">6- نا الْمُتَكَلِّمِين , نحو : ذَهَبْنَا .</div><div class="rule-source-line">ب- ضمائرُ نصبٍ , وهي :</div><div class="rule-source-line">1- ياء المتكلّم , نحو : سَأَلَنِي ، يَسْأَلُنِى ، اسْأَلْنِي .</div><div class="rule-source-line">2- كاف المخاطَب , نحو : سَألَكَ ، يَسْأَلُكَ .</div><div class="rule-source-line">3- هاء الغائب , نحو : سَأَلَهُ، يَسْأَلُهُ ، اسْأَلْهُ .</div><div class="rule-source-line">4- نا الْمُتَكَلَّمِين , نحو : سَأَلَنَا ، يَسْأَلُنَا ، اسْأَلْنَا .</div><div class="rule-source-line">ج- ضمائرُ جرٍّ , وهي :</div><div class="rule-source-line">1- ياء المتكلّم , نحو : كتابي ، لي .</div><div class="rule-source-line">2- كاف المخاطَب , نحو : كتابك ، لك .</div><div class="rule-source-line">3- هاء الغائب , نحو : كتابه ، له .</div><div class="rule-source-line">4- نا الْمُتَكَلَّمِين , نحو : كتابنا ، لنا .</div><div class="rule-source-line">ثَانِياً : الضَّمَائِرُ الْمُنْفَصِلَةُ</div><div class="rule-source-line">هي : التي يُبْدَأُ بها في النُّطْقِ ، وتَقَعُ بعد ( إلاَّ ) . الضمائرُ المنفصلةُ ،</div><div class="rule-source-line">نحو : أنا مجتهد وأنت كسلان ، ونحو : ما رأيتُ إلا إِيَّاكَ .</div><div class="rule-source-line">تنقسم الضمائر المنفصلة باعتبار موقعها الإعرابي إلى قسمين هما :</div><div class="rule-source-line">أ- ضمائرُ رفعٍ , وهي :</div><div class="rule-source-line">1- المتكلَّم : أنا ،  ونحن .</div><div class="rule-source-line">2- المخاطَب : أَنْتَِ ، وأَنْتُمَا ، وأَنْتُمْ ،وأَنْتُنَّ .</div><div class="rule-source-line">3- الغائب : هُوَ ، وهِيَ ، وهُمَا ، وهُمْ ، وهُنَّ .</div><div class="rule-source-line">ب- ضمائرُ نصبٍ , وهي :</div><div class="rule-source-line">1- المتكلَّم : إِيَّايَ ، إِيَّانَا .</div><div class="rule-source-line">2- المخاطَب : إِيَّاكَِ ،  إِيَّاكُمَا ، إِيَّاكُمْ ، إِيَّاكُنَّ .</div><div class="rule-source-line">3- الغائب : إِيَّاهُ ، إِيَّاهَا ، إِيَّاهُمَا ، إِيَّاهُمْ ، إِيَّاهُنَّ .</div><div class="rule-source-line">ضمائرُ الجرِّ لا تأتي إلاَّ مُتَّصِلَةً .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'الضمائر منها بارز ومستتر، والمنفصل والمتصل، ولها مواقع رفع ونصب وجر.'),
('Мединский курс (Том 4)', '10', 'رُتَبُ الضَّمَائِرِ (порядок местоимений)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">رُتَبُ الضَّمَائِرِ</span><p class="rule-study-text">порядок местоимений. إذا اجتمع أكثر من ضمير روعي ترتيب المتكلم ثم المخاطب ثم الغائب بحسب القاعدة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">رُتَبُ الضَّمَائِرِ</span><span class="rule-term-ru">رُتَبُ الضَّمَائِرِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمَائِرُ</span><span class="rule-term-ru">местоимения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">للضّمائرِ ثلاثُ رُتَبٍ ، هي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- الْمُتَكَلِّمُ            2- الْمُخَاطَبُ              3- الْغَائِبُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">مواضعُ الإتيانِ بضميرِ النَّصبِ المنفصلِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">يجب استعمال ضمير النصب المنفصل في المواضع الآتية :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">1- إذا تقدم المفعول به على عامله , نحو قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أَإيَّايَ تَسْأَلُ ؟ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">2- إذا وقع الضمير بعد حرف العطف , نحو : رَأَيْتُكَ وإِيَّاهُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">رُتَبُ الضَّمَائِرِ</div><div class="rule-source-line">للضّمائرِ ثلاثُ رُتَبٍ ، هي :</div><div class="rule-source-line">1- الْمُتَكَلِّمُ            2- الْمُخَاطَبُ              3- الْغَائِبُ .</div><div class="rule-source-line">مواضعُ الإتيانِ بضميرِ النَّصبِ المنفصلِ :</div><div class="rule-source-line">يجب استعمال ضمير النصب المنفصل في المواضع الآتية :</div><div class="rule-source-line">1- إذا تقدم المفعول به على عامله , نحو قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك :</div><div class="rule-source-line">أَإيَّايَ تَسْأَلُ ؟ .</div><div class="rule-source-line">2- إذا وقع الضمير بعد حرف العطف , نحو : رَأَيْتُكَ وإِيَّاهُ .</div><div class="rule-source-line">3- إذا وقع الضمير بعد ( إلاّ ) نحو : ما رأيتُ إلاَّ إِيَّاكَ .</div><div class="rule-source-line">4- إذا وقع الضمير بعد ضمير نصب متصل , نحو : أَعْطَيْتُهُ إِيَّاهُ .</div><div class="rule-source-line">5- إذا وقع الضمير مفعولا لمصدر أُضِيفَ إلى فاعله , نحو: زيارةُ المدِيرِ إِيَّانَا غداً إن شاء الله . فالمدير : مُضاف إليه ( وهو فاعل في الأصل ) وإِيَّانَا : مفعول به عامله المصدر ؛ لأنَّ المصدرَ يَعْمَلُ عَمَلَ فِعْلِهِ ؛ إذ أصل الجملة : يَزُورُنَا المديرُ غداً إن شاء الله .</div><div class="rule-source-line">حُكْمُ الْوَصْلِ ، وَالْفَصْلِ :</div><div class="rule-source-line">إذا اجتمع ضميران للنصب ، وكان الضميران من رتبة واحدة , وجب الفصل بينهما ,  نحو : أَعْطَيْتُهُ إِيَّاهُ ، يجب الفصل هنا ؛ لأن الضميرين من رُتبة واحده ، هي رتبة الغائب .</div><div class="rule-source-line">أما إذا كان الضميران من رتبة مختلفة فيجوز الفصل والوصل ، نحو : أَعْطَيْتُكَ إِيَّاهُ        ( بِالْفَصْل ) ويجوز : أَعْطَيْتُكَهُ ( بِالْوَصْلِ ) لأن الضميرين من رتبة مختلفة ، فالأول للمخاطَب ، والثاني للغائب .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'إذا اجتمع أكثر من ضمير روعي ترتيب المتكلم ثم المخاطب ثم الغائب بحسب القاعدة.'),
('Мединский курс (Том 4)', '11', 'الْمَفْعُولُ الْمُطْلَقُ (абсолютное дополнение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَفْعُولُ الْمُطْلَقُ</span><p class="rule-study-text">абсолютное дополнение. المفعول المطلق مصدر منصوب يذكر لتأكيد الفعل أو بيان نوعه أو عدده.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَفْعُولُ الْمُطْلَقُ</span><span class="rule-term-ru">الْمَفْعُولُ الْمُطْلَقُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">المفعولُ المطلقُ : مَصْدَرٌ يُذْكَرُ بعدَ فِعْلٍ من لَفْظِهِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أنواعه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- مُؤَكِّدٌ لفعله .             2- مُبَيَّنٌ لنوع الفعل .             3- مُبَيَّنٌ لعدد الفعل .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">4- مصدرٌ نَائِبٌ عن فعله .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">فمثال المؤكِّد لفعله : فهمت الدرس فهماً . أكلت أكلاً . نمتُ نوماً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومثال الْمُبَيَّن للنوع : فهمت الدرس فهماً جيداً . أكلتُ أَكْلَ الجَائِعِ . فهمتُ المسألةَ فَهْمَ العُلماءِ . ومنه قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الْحَادِي عَشَرَ</div><div class="rule-source-line">الْمَفْعُولُ الْمُطْلَقُ</div><div class="rule-source-line">المفعولُ المطلقُ : مَصْدَرٌ يُذْكَرُ بعدَ فِعْلٍ من لَفْظِهِ .</div><div class="rule-source-line">أنواعه :</div><div class="rule-source-line">1- مُؤَكِّدٌ لفعله .             2- مُبَيَّنٌ لنوع الفعل .             3- مُبَيَّنٌ لعدد الفعل .</div><div class="rule-source-line">4- مصدرٌ نَائِبٌ عن فعله .</div><div class="rule-source-line">فمثال المؤكِّد لفعله : فهمت الدرس فهماً . أكلت أكلاً . نمتُ نوماً .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">ومثال الْمُبَيَّن للنوع : فهمت الدرس فهماً جيداً . أكلتُ أَكْلَ الجَائِعِ . فهمتُ المسألةَ فَهْمَ العُلماءِ . ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">وهذا النوع لا بُدَّ أن يكون ما بعد المصدر صِفةً ، أو مضافاً إليه ، كما ترى في الأمثلة .</div><div class="rule-source-line">ومثال الْمُبيَّن للعدد : طبعت الكتاب طَبْعَةً ، أو طَبْعَتَيْنِ ، أو طَبَعَاتٍ .</div><div class="rule-source-line">وسجدت لله سَجْدَةً ، أو سَجْدَتَيْنِ ، أو سَجَدَاتٍ .</div><div class="rule-source-line">ومثال النائب عن فعله : مهلاً ، وصبراً ، وحمداً ، وشكراً ؛ ونحو : سبحانَ اللهِ ،</div><div class="rule-source-line">ومَعَاذَ اللهِ ، ولَبَّيْكَ ، ونحو : سمعاً وطاعةً .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'المفعول المطلق مصدر منصوب يذكر لتأكيد الفعل أو بيان نوعه أو عدده.'),
('Мединский курс (Том 4)', '11', 'حَذْفُ الْعَامِلِ (удаление управляющего глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَذْفُ الْعَامِلِ</span><p class="rule-study-text">удаление управляющего глагола. قد يحذف عامل المفعول المطلق إذا دل عليه السياق.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">حَذْفُ الْعَامِلِ</span><span class="rule-term-ru">حَذْفُ الْعَامِلِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّمَا</span><span class="rule-term-ru">частица ограничения: «только, лишь»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">المفعول المطلق المؤكد لفعله : لا يجوز حذف عامله ؛ لأنه إنمّا جيء بالمصدر لتأكيد معنى عامله ، وتقويته .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أما المبين للنوع ، والعدد فيجوز حذف عاملهما بشرط الدلالة عليهما .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : قُدُوماً مُبَارَكاً ، أي : قدمتَ قدوماً مباركاً ، ونحو : حَجًّا مَبْرُوراً ، أي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">حَجَجْتَ حَجاًّ مَبروراً ، ونحو : كم قراءةً قرأتَ الدرسَ ؟ قِرَاءَتَيْنِ ، أي : قرأته قراءتين ، ونحو :كم سجدةً لله سجدتَ ؟ سَجَدَاتٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حَذْفُ الْعَامِلِ</div><div class="rule-source-line">المفعول المطلق المؤكد لفعله : لا يجوز حذف عامله ؛ لأنه إنمّا جيء بالمصدر لتأكيد معنى عامله ، وتقويته .</div><div class="rule-source-line">أما المبين للنوع ، والعدد فيجوز حذف عاملهما بشرط الدلالة عليهما .</div><div class="rule-source-line">نحو : قُدُوماً مُبَارَكاً ، أي : قدمتَ قدوماً مباركاً ، ونحو : حَجًّا مَبْرُوراً ، أي :</div><div class="rule-source-line">حَجَجْتَ حَجاًّ مَبروراً ، ونحو : كم قراءةً قرأتَ الدرسَ ؟ قِرَاءَتَيْنِ ، أي : قرأته قراءتين ، ونحو :كم سجدةً لله سجدتَ ؟ سَجَدَاتٍ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'قد يحذف عامل المفعول المطلق إذا دل عليه السياق.'),
('Мединский курс (Том 4)', '11', 'النَّائِبُ عَنِ الْمَصْدَرِ (заместитель масдара)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">النَّائِبُ عَنِ الْمَصْدَرِ</span><p class="rule-study-text">заместитель масдара. ينوب عن المصدر ما يدل عليه، فيعرب مفعولاً مطلقاً نائباً عن المصدر.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">النَّائِبُ عَنِ الْمَصْدَرِ</span><span class="rule-term-ru">النَّائِبُ عَنِ الْمَصْدَرِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنْ</span><span class="rule-term-ru">облегчённая لكنّ; не работает как إنّ</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَائِبٌ عَنِ الْمَصْدَرِ</span><span class="rule-term-ru">слово, заменяющее масдар в роли مفعول مطلق</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ينوب عن المصدر ما يدل عليه ، فَيُعْرَبُ مفعولا مطلقاً نائبا عن المصدر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">وينوب عن المصدر ما يلي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">1- ألفاظُ ( كُلٍّ ، وبَعْضٍ , و أَيٍّ ) مضافة إلى المصدر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : فهمتُ الدرسَ كُلَّ الْفَهْمِ . فهمتُ الدرسَ بَعْضَ الفهمِ . أَيَّ فَهْمٍ فهمتَ الدرسَ ؟</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ومثلها : كَمْ , نحو : كم قراءةً قرأت الدرسَ ؟</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">2- صفةُ المصدرِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : فهمتُ الدرسَ جيِّداً ، أي : فهماً جيداً ، ونحو : ساعدته أَحْسَنَ المساعدةِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">النَّائِبُ عَنِ الْمَصْدَرِ</div><div class="rule-source-line">ينوب عن المصدر ما يدل عليه ، فَيُعْرَبُ مفعولا مطلقاً نائبا عن المصدر .</div><div class="rule-source-line">وينوب عن المصدر ما يلي :</div><div class="rule-source-line">1- ألفاظُ ( كُلٍّ ، وبَعْضٍ , و أَيٍّ ) مضافة إلى المصدر .</div><div class="rule-source-line">نحو : فهمتُ الدرسَ كُلَّ الْفَهْمِ . فهمتُ الدرسَ بَعْضَ الفهمِ . أَيَّ فَهْمٍ فهمتَ الدرسَ ؟</div><div class="rule-source-line">ومثلها : كَمْ , نحو : كم قراءةً قرأت الدرسَ ؟</div><div class="rule-source-line">2- صفةُ المصدرِ :</div><div class="rule-source-line">نحو : فهمتُ الدرسَ جيِّداً ، أي : فهماً جيداً ، ونحو : ساعدته أَحْسَنَ المساعدةِ .</div><div class="rule-source-line">3- عددُهُ :</div><div class="rule-source-line">نحو : زرتك ثلاثَ زياراتٍ ، ونحو : ضربته عشرين ضربةً . ومنه قوله تعالى: [موضع غير واضح في المصدر] .</div><div class="rule-source-line">4- المصدرُ الَّذي يُلاَقِيهِ في الاشْتِقَاقِ :</div><div class="rule-source-line">نحو : تَبَسَّمْتُ ابْتِسَاماً ، أُحِبُّ اللهَ حُباًّ جَماًّ . ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">فابتسام ليس مصدراً لـ ( تبسَّم ) ولكنهما يلتقيان في الاشتقاق فكلّ منهما مُشتق من الفعل ( بَسَمَ ) .</div><div class="rule-source-line">5- اسمُ المصدرِ ، وهو ما دلَّ على الْحَدَثِ كالمصدرِ، ولكنْ حروفُه أقلُّ من حروف المصدر, نحو : كَلَّمته كَلاَماً ، وصَلَّيت صَلاَةً , وقَبَّلْتُ ابني قُبْلَةً ، وَاغْتَسَلْتُ غُسْلاً ،</div><div class="rule-source-line">وأَعْطَيْتُهُ عَطَاءً . فالْكَلاَمُ ليس مصدراً أصلاً ، ولكنه يدل على الْحَدَث كالمصدر ، وحروفه أقلُّ من حروف المصدر الأصلي ( تَكَلُّماً ) ولا فِعْلَ ثُلاَثِيَّ له ؛ ولذلك سُمَّي اسم مصدر .</div><div class="rule-source-line">6- اسمُ الإشارةِ :</div><div class="rule-source-line">نحو : أتعامله تلك المعاملةَ ؟ ضربته هذا الضربَ لأنه كسلان .</div><div class="rule-source-line">7- الضَّميرُ العَائِدُ إلى المصدرِ :</div><div class="rule-source-line">نحو : قرأت قراءةً لم يقرأها غيري . ومنه قوله تعالى: [موضع غير واضح في المصدر] .</div><div class="rule-source-line">فالضمير في يقرأها عائد إلى المصدر ( قراءةً ) والضمير في ( لا أعذبه ) عائد إلى المصدر   ( عذاباً ) ولذلك يُعرب مفعولا مطلقاً .</div><div class="rule-source-line">8- مُرَادِفُهُ :</div><div class="rule-source-line">نحو : قُمْتُ وُقُوفاً . جَلَسْتُ قُعُوداً . فَرِحْتُ جَذَلاً . عِشْتُ حَيَاةً سعيدةً .</div><div class="rule-source-line">فالوقوف مُرَادِفٌ ومُمَاثِلٌ في المعنى لِلْقِيَام ... وهكذا الباقي .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'ينوب عن المصدر ما يدل عليه، فيعرب مفعولاً مطلقاً نائباً عن المصدر.'),
('Мединский курс (Том 4)', '11', 'أَقْسَامُ الْمَصْدَرِ (виды масдара)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَقْسَامُ الْمَصْدَرِ</span><p class="rule-study-text">виды масдара. المصدر ينقسم باعتبارات متعددة، ويستعمل في مواضع نحوية وصرفية.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">أَقْسَامُ الْمَصْدَرِ</span><span class="rule-term-ru">أَقْسَامُ الْمَصْدَرِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ مُطْلَقٌ</span><span class="rule-term-ru">абсолютное дополнение: масдар действия</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَائِبٌ عَنِ الْمَصْدَرِ</span><span class="rule-term-ru">слово, заменяющее масдар в роли مفعول مطلق</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">تَمْيِيزٌ</span><span class="rule-term-ru">разъясняющее дополнение, снимающее неопределённость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- مَصْدَرُ الْمَرَّة : يذكر لبيان عدد الفعل .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">يُصَاغُ من الثُّلاثيِّ المجرَّدِ على وزن ( فَعْلَة ) نحو : سَجْدَة ، ورَكْعَة ، وضَرْبَة ، وأَكْلَة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">تقول : سجدتُ للهِ سَجْدَةً ، وركعتُ رَكْعَةً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">ويُصاغ من غير الثُّلاثي المجرَّد بزيادة ( تاء ) في آخر مصدره الأصلي .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : كَبَّر          تَكْبِيرٌ        تَكْبِيرَة ٌ. سَلَّمَ         تَسْلِيمٌ         تسليمةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">إذا كان المصدر الأصلي مختوما ( بالتاء ) في أصل بنائه ذُكِرَ بعده ما يدل على العدد, ككلمة ( واحدة ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : تَرْجَمْتُ الكتابَ تَرْجَمَةً واحدةً . اسْتَرَحْتُ اسْتِرَاحَةً واحدةً . أَقَمْتُ إِقَامَةً واحدةً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">أقسام المصدر</div><div class="rule-source-line">1- مَصْدَرُ الْمَرَّة : يذكر لبيان عدد الفعل .</div><div class="rule-source-line">يُصَاغُ من الثُّلاثيِّ المجرَّدِ على وزن ( فَعْلَة ) نحو : سَجْدَة ، ورَكْعَة ، وضَرْبَة ، وأَكْلَة .</div><div class="rule-source-line">تقول : سجدتُ للهِ سَجْدَةً ، وركعتُ رَكْعَةً .</div><div class="rule-source-line">ويُصاغ من غير الثُّلاثي المجرَّد بزيادة ( تاء ) في آخر مصدره الأصلي .</div><div class="rule-source-line">نحو : كَبَّر          تَكْبِيرٌ        تَكْبِيرَة ٌ. سَلَّمَ         تَسْلِيمٌ         تسليمةٌ .</div><div class="rule-source-line">إذا كان المصدر الأصلي مختوما ( بالتاء ) في أصل بنائه ذُكِرَ بعده ما يدل على العدد, ككلمة ( واحدة ) .</div><div class="rule-source-line">نحو : تَرْجَمْتُ الكتابَ تَرْجَمَةً واحدةً . اسْتَرَحْتُ اسْتِرَاحَةً واحدةً . أَقَمْتُ إِقَامَةً واحدةً .</div><div class="rule-source-line">2- مصدرُ الْهَيْئَةِ : يُذْكَرُ لبيانِ هَيْئَةِ الفعلِ وصفتِه .</div><div class="rule-source-line">يُصاغ من الثُّلاثي المجرَّد على وزن ( فِعْلَة ) نحو : إِكْلَة ، ومِشْيَة ، وجِلْسَة ، وقِتْلَة .</div><div class="rule-source-line">تقول : أكلتُ إِكْلَةَ الْجَائِعِ . مَشَيْتُ مِشْيَةَ الأسدِ . مَاتَ مِيتَةً حَسنَةً . ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] لا يُصَاغ مصدرُ الهيئةِ من غيرِ الثُّلاثيِّ المجرَّدِ .</div><div class="rule-source-line">3- المصدرُ الْمِيمِيُّ : هو ما كانَ في أوَّلِه مِيمٌ زائدةٌ .</div><div class="rule-source-line">يُصاغ من الثلاثي المجرد على وزنين :</div><div class="rule-source-line">أ- مَفْعِل ، وذلك إذا كانَ معتلَّ الأوَّلِ صحيحَ الآخِرِ .</div><div class="rule-source-line">نحو : وَعَدَ : مَوْعِدٌ - وَقَفَ : مَوْقِفٌ - وَضَعَ : مَوْضِعٌ .</div><div class="rule-source-line">تقول : مَوْعِدُ اللهِ حَقٌّ ، أي : وَعْدُ اللِه حقٌّ ؛ وتقول : مَوْقِفُكَ معي كان عظيماً ، أي :</div><div class="rule-source-line">وقوفك معي . ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">ب- مَفْعَل : وذلك إذا لم يكن معتلَّ الأوَّلِ ، أي : ليس مِثَالاً .</div><div class="rule-source-line">نحو : ضَرَبَ : مَضْرَبٌ ، نَهَجَ : مَنْهَجٌ ، نَجَا : مَنْجَاةٌ ، قَالَ : مَقَالَةٌ .</div><div class="rule-source-line">تقول : نَهَجْتُ مَنْهَجَ الصَّالحين ، وسَلَكْتُ مَسْلَكَهُم ؛ وتقول : الصَّدْقُ مَنْجَاةٌ ، والكَذِبُ مَفْسَدَةٌ .</div><div class="rule-source-line">ويُصاغ من غير الثُّلاثي المجرَّد على زِنَةِ اسمِ المفعولِ (ميم مضمومة ، وفتح ما قبل</div><div class="rule-source-line">الآخر ) نحو : مُنْقَلَبٌ ، ومُمَزَّقٌ ، ومُخْتَلَفٌ ، ومُجْتَمَعٌ ، ومُسْتَقًى ، ومُدْخَل ، ومُخْرَج .</div><div class="rule-source-line">تقول : مُجْتَمَعُ الطُّلابِ خَيْرٌ ، أي : اجْتِمَاعُهُم ؛ وتقول : مُسْتَقَى الزَّرْعِ يُحْيِيهِ ، أي :</div><div class="rule-source-line">سَقْيُ الزَّرْع يُحْيِيه . ومنه قوله تعالى : [موضع غير واضح في المصدر]</div><div class="rule-source-line">وقوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب : أكلتُ أكلاً .        ضربته ضربتين .        ضربته عشرين ضربةً .</div><div class="rule-source-line">فهمت جيِّداً .       فهمت كُلَّ الفهمِ .     مَهْلاً .     أتعامله هذهِ الْمُعَامَلَةَ .</div><div class="rule-source-line">أكلا : مفعول مطلق منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">ضربتين : مفعول مطلق منصوب وعلامة نصبه الياء .</div><div class="rule-source-line">عشرين ضربةً : عشرين : مفعول مطلق نائب عن المصدر منصوب وعلامة نصبه الياء .</div><div class="rule-source-line">ضربةً : تمييز ذات منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">جيِّداً : مفعول مطلق نائب عن المصدر منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">كُلَّ الفهمِ : كلَّ : مفعول مطلق نائب عن المصدر منصوب وعلامة نصبه الفتحة</div><div class="rule-source-line">الظاهرة ، وهو مضاف .</div><div class="rule-source-line">الفهم : مضاف إليه مجرور وعلامة جرّه الكسرة الظاهرة .</div><div class="rule-source-line">مهلا : مفعول مطلق نائب عن فعله منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">هذهِ المعاملةَ : هذه : اسم إشارة مبني على الكسر في محل نصب مفعول مطلق نائب</div><div class="rule-source-line">عن المصدر.</div><div class="rule-source-line">المعاملة : بدل منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'المصدر ينقسم باعتبارات متعددة، ويستعمل في مواضع نحوية وصرفية.'),
('Мединский курс (Том 4)', '12', 'الْمَفْعُولُ لَهُ أَوْ لِأَجْلِهِ (дополнение причины/цели)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَفْعُولُ لَهُ أَوْ لِأَجْلِهِ</span><p class="rule-study-text">дополнение причины/цели. المفعول له مصدر منصوب يبين سبب وقوع الفعل ويشترط اتحاد الفاعل والزمان غالباً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَفْعُولُ لَهُ أَوْ لِأَجْلِهِ</span><span class="rule-term-ru">الْمَفْعُولُ لَهُ أَوْ لِأَجْلِهِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ لَهُ</span><span class="rule-term-ru">дополнение причины/цели</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">المفعول له : مصدرٌ يُذكرُ لبيانِ سببِ الفعلِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أحواله :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">1- مُجَرَّدٌ من ( أل ) والإضافة ، نحو : جئت رغبةً في العلم .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">2- مضاف , نحو : تصدقتُ ابتغاءَ مرضاةِ الله .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">3- مُحَلًّى بـ ( أل ) نحو : ضربتُ ابني التأديبَ . وهذا النوع قليل الاستعمال ، وجرُّه كثير ؛ تقول : ضربت ابني للتَّأديبِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">رغبةً : مفعول له منصوب وعلامة نصبه الفتحة الظاهرة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الثَّانِي عَشَرَ</div><div class="rule-source-line">الْمَفْعُولُ لَهُ ، أو لأَجْلِهِ</div><div class="rule-source-line">المفعول له : مصدرٌ يُذكرُ لبيانِ سببِ الفعلِ .</div><div class="rule-source-line">أحواله :</div><div class="rule-source-line">1- مُجَرَّدٌ من ( أل ) والإضافة ، نحو : جئت رغبةً في العلم .</div><div class="rule-source-line">2- مضاف , نحو : تصدقتُ ابتغاءَ مرضاةِ الله .</div><div class="rule-source-line">3- مُحَلًّى بـ ( أل ) نحو : ضربتُ ابني التأديبَ . وهذا النوع قليل الاستعمال ، وجرُّه كثير ؛ تقول : ضربت ابني للتَّأديبِ .</div><div class="rule-source-line">الإعراب :</div><div class="rule-source-line">رغبةً : مفعول له منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">ابتغاءَ : مفعول له منصوب وعلامة نصبه الفتحة الظاهرة ، وهو مضاف ،</div><div class="rule-source-line">مرضاةِ : مضاف إليه مجرور وعلامة جره الكسرة .</div><div class="rule-source-line">التأديبَ : مفعول له منصوب وعلامة نصبه الفتحة الظاهرة .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'المفعول له مصدر منصوب يبين سبب وقوع الفعل ويشترط اتحاد الفاعل والزمان غالباً.'),
('Мединский курс (Том 4)', '12', 'لَا الْعَاطِفَةُ (لا как союз противопоставления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَا الْعَاطِفَةُ</span><p class="rule-study-text">لا как союз противопоставления. لا العاطفة تثبت الحكم لما قبلها وتنفيه عما بعدها، ولها شروط في الاستعمال.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا الْعَاطِفَةُ</span><span class="rule-term-ru">لَا الْعَاطِفَةُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْلَا</span><span class="rule-term-ru">частица условия/побуждения; значение зависит от контекста</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْمَا</span><span class="rule-term-ru">частица, близкая к لولا в побудительном употреблении</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">معناها : إخراج ما بعدها من حكم ما قبلها .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">شروطها :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- أن يكون المعطوف مفردا ، والمراد بالمفرد : ما ليس بجملة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">2- أن تقع بعد الإيجاب ، أو الأمر .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">• مثال وقوعها بعد الإيجاب : جاء محمدٌ لا عليٌّ . قرأتُ الكتابَ لا القِصَّةََ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">• مثال وقوعها بعد الأمر : اسألِ المدرسَ لا الطَّالبَ . كُلِ الْمَوْزَ لا التُّفَّاحَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب : جاء محمدٌ لا عليٌّ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">لا الْعَاطِفَةُ</div><div class="rule-source-line">معناها : إخراج ما بعدها من حكم ما قبلها .</div><div class="rule-source-line">شروطها :</div><div class="rule-source-line">1- أن يكون المعطوف مفردا ، والمراد بالمفرد : ما ليس بجملة .</div><div class="rule-source-line">2- أن تقع بعد الإيجاب ، أو الأمر .</div><div class="rule-source-line">• مثال وقوعها بعد الإيجاب : جاء محمدٌ لا عليٌّ . قرأتُ الكتابَ لا القِصَّةََ .</div><div class="rule-source-line">• مثال وقوعها بعد الأمر : اسألِ المدرسَ لا الطَّالبَ . كُلِ الْمَوْزَ لا التُّفَّاحَ .</div><div class="rule-source-line">الإعراب : جاء محمدٌ لا عليٌّ .</div><div class="rule-source-line">جاءَ : فعل ماضٍ مبني على الفتح .</div><div class="rule-source-line">محمدٌ : فاعل مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">لا : حرف عطف مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">عليٌّ : معطوف مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">أحرفُ التَّحْضِيضِ ، والتَّنْدِيمِ</div><div class="rule-source-line">التَّحْضِيضُ ، هو : الحثُّ ، والتَّرْغِيبُ .</div><div class="rule-source-line">التَّنْدِيمُ ، هو : جَعْلُ الْمُخَاطَب يَنْدَمُ على أَمْرٍ قَدْ مَضَى .</div><div class="rule-source-line">وهذه الأحرف هي : هَلاَّ , أَلاَّ ، أَلاَ , لَوْلاَ , لَوْمَا .</div><div class="rule-source-line">• إذا وقع بعدها فعل مضارع فهي للتحضيض .</div><div class="rule-source-line">نحو : هلاَّ تجتهدون . لَوْمَا تصومون . أَلاَ تَتُوبُ من ذَنْبِكَ .</div><div class="rule-source-line">• إذا وقع بعدها فعل ماض فهي للتنديم .</div><div class="rule-source-line">نحو : هَلاَّ اجتهدْتَ .         لولا صُمْتَ .         أَلاَ تُبْتَ .</div><div class="rule-source-line">الإعراب :</div><div class="rule-source-line">هلاَّ تجتهدُ .</div><div class="rule-source-line">هلاَّ : حرف تحضيض مبني على السكون لا محل من الإعراب .</div><div class="rule-source-line">تجتهدُ : فعل مضارع مرفوع وعلامة رفعه الضمة الظاهرة .</div><div class="rule-source-line">هلاَّ اجتهدْتَ .</div><div class="rule-source-line">هلاَّ : حرف تنديم مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">اجتهدْتَ : فعل ماضٍ مبني على السكون لاتصاله بالتاء ، والتاء : ضمير رفع متصل مبني على الفتح في محل رفع فاعل .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'لا العاطفة تثبت الحكم لما قبلها وتنفيه عما بعدها، ولها شروط في الاستعمال.'),
('Мединский курс (Том 4)', '13', 'التَّمْيِيزُ (تمييز — разъясняющее дополнение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">التَّمْيِيزُ</span><p class="rule-study-text">تمييز — разъясняющее дополнение. التمييز اسم نكرة منصوب يفسر إبهاماً في ذات أو نسبة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">التَّمْيِيزُ</span><span class="rule-term-ru">التَّمْيِيزُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ فَعَّلَ</span><span class="rule-term-ru">порода فَعَّلَ: усиление, многократность или перевод в переходность</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">بَابُ اِفْتَعَلَ</span><span class="rule-term-ru">порода اِفْتَعَلَ: дополнительная ت после первой корневой</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَقَدْ</span><span class="rule-term-ru">усиление прошедшего действия через لام и قد</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنْ</span><span class="rule-term-ru">облегчённая لكنّ; не работает как إنّ</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">تَمْيِيزٌ</span><span class="rule-term-ru">разъясняющее дополнение, снимающее неопределённость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">التَّمْيِيزُ : اسمٌ نكرةٌ يتضمَّنُ معنى ( مِنْ ) البَيَانِيَّة ، ويُذكر لِبيَان ما قبله من إِبْهَامٍ ، أو إِجْمَالٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أنواعه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">أ- تمييز الذَّاتِ .        ب- تمييز النِّسْبَةِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يُوَضَّحُ كلمةً مُبْهَمَةً قبلَه . ويقع بعد الْمَقَادِيرِ ، والمقادير أربعة أنواع ، هي :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- الْمَقَايِيسُ ( الْمَمْسُوحَاتُ ، أي : الْمَسَاحَةُ ) نحو : عندي مِتْرٌ قُمَاشاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : بِعْتُ ذِرَاعاً وَرَقاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- الْمَوْزُونَاتُ , نحو : تَصَدَّقْتُ بِغِرَامٍ ذَهَباً . اشتريتُ رِطْلاً عَسَلاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الثَّالِثَ عَشَرَ</div><div class="rule-source-line">التَّمْيِيزُ</div><div class="rule-source-line">التَّمْيِيزُ : اسمٌ نكرةٌ يتضمَّنُ معنى ( مِنْ ) البَيَانِيَّة ، ويُذكر لِبيَان ما قبله من إِبْهَامٍ ، أو إِجْمَالٍ .</div><div class="rule-source-line">أنواعه :</div><div class="rule-source-line">أ- تمييز الذَّاتِ .        ب- تمييز النِّسْبَةِ .</div><div class="rule-source-line">أ- تمييزُ الذَّاتِ</div><div class="rule-source-line">يُوَضَّحُ كلمةً مُبْهَمَةً قبلَه . ويقع بعد الْمَقَادِيرِ ، والمقادير أربعة أنواع ، هي :</div><div class="rule-source-line">1- الْمَقَايِيسُ ( الْمَمْسُوحَاتُ ، أي : الْمَسَاحَةُ ) نحو : عندي مِتْرٌ قُمَاشاً .</div><div class="rule-source-line">ونحو : بِعْتُ ذِرَاعاً وَرَقاً .</div><div class="rule-source-line">2- الْمَوْزُونَاتُ , نحو : تَصَدَّقْتُ بِغِرَامٍ ذَهَباً . اشتريتُ رِطْلاً عَسَلاً .</div><div class="rule-source-line">3- الْمَكِيلاَتُ , نحو : دفعتُ صَاعاً تَمْراً . لَهُ قَفِيزٌ بُرًّا . ( القَفِيزُ : مِكْيَالٌ قَدِيمٌ ) .</div><div class="rule-source-line">4- الْعَدَدُ , نحو : قرأتُ أحدَ عشرَ كتاباً ، أو بعد كناية العدد ، نحو : كَمْ كتاباً عندكَ ؟</div><div class="rule-source-line">الكلمات التي تحتها خط تمييز ذات ؛ لأنها وقعت بعد المقادير المذكورة .</div><div class="rule-source-line">أحكامه :</div><div class="rule-source-line">أ- يجوزُ نصبُه , نحو : عندي مترٌ قماشاً : تمييز منصوب وعلامة نصبه الفتحة الظاهرة .</div><div class="rule-source-line">ب- يجوزُ جرُّه بـ (مِنْ الْبَيَانِيَّةِ ) نحو : عندي مترٌ مِن قُماشٍ : تمييز مجرور بمن وعلامة جرِّه الكسرة الظاهرة .</div><div class="rule-source-line">ج- يجوزُ جرُّه بالإضافةِ , نحو : عندي مترُ قماشٍ : تمييز مجرور بالإضافة وعلامة جرِّه الكسرة الظاهرة .</div><div class="rule-source-line">مَا يُلْحَقُ بتمييزِ الذَّاتِ :</div><div class="rule-source-line">يُلحق بتمييز الذَّات الدَّالُّ على ما يُشْبِهُ المِقْدَارَ .</div><div class="rule-source-line">نحو : عندي كيسٌ أرزاً . اشتريت جَرَّةً عسلاً . ما في السماء قَدْرُ رَاحَةٍ سَحَاباً .</div><div class="rule-source-line">أريدُ مِلْءَ ملعقةٍ عسلاً .</div><div class="rule-source-line">الكلمات التي تحتها خط ليست مقادير حقيقية ؛ لأنَّها لا تدلُّ على مِقْدَارٍ مُعَيَّنٍ مَحْدُود، ولكنها تُشبه المقادير التي ذكرناها سابقاً في مُطْلَق الْمِقْدار . فالكِيسُ مثلا يُشْبِهُ المكيال ، وقدْر راحة تدلّ على المقياس ؛ ولذلك عُدَّتْ من تمييز الذات .</div><div class="rule-source-line">ويجوز فيما يُشبه المقدار الأوجه الإعرابية الثلاثة السابقة ؛ فتقول : عندي كيسٌ أَرُزاً ، وعندي كيسٌ مِنْ أَرُزٍ ، وعندي كيسُ أَرُزٍ .</div><div class="rule-source-line">* أما إذا أضيف ما يشبه المقدار إلى غير التمييز جاز في التمييز وجهان :</div><div class="rule-source-line">النَّصب ، والجر بمن البيانية ( ولا يجوز الجر بالإضافة ) نحو : ما في السماءِ قدرُ راحةٍ سحاباً ، ويجوز : ما في السماء قدرُ راحةٍ مِنْ سحابٍ .</div><div class="rule-source-line">وتقول : أريدُ ملءَ ملعقةٍ عَسَلاً ، ويجوز : أريد ملءَ ملعقةٍ من عَسَلٍ . ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div><div class="rule-source-line">ب- تمييزُ النَّسْبَةِ</div><div class="rule-source-line">يُوَضَّح جُمْلَةً مُبْهَمَةَ النَّسْبَةِ قبلَه , نحو : حَسُنَ الطالبُ خُلُقاً , أي: حَسُنَ مِن جِهَةِ خُلُقِه .</div><div class="rule-source-line">أصله :</div><div class="rule-source-line">إما فاعل ، وإما مبتدأ ، وإما مفعول به .   أصله</div><div class="rule-source-line">1- ما أصله فاعل , نحو : حَسُنَ الطالبُ خُلُقاً ، أي : حَسُنَ خُلُقُ الطَّالبِ .</div><div class="rule-source-line">ونحو : اِزْدَادَ عليٌّ عِلْماً ، أي : ازداد عِلْمُ عليٍّ .</div><div class="rule-source-line">2- ما أصله مبتدأ ، نحو : أنا أكثرُ منك مالاً ، أي : مالِي أكثر .</div><div class="rule-source-line">3- ما أصله مفعول به , نحو : غَرَسْتُ الحديقةَ أَزْهَاراً ، أي : غرستُ أزهارَ الحديقةِ .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] أي : وفجرنا عيونَ الأرضِ .</div><div class="rule-source-line">حكمه : النَّصْبُ .</div><div class="rule-source-line">مواضعه :</div><div class="rule-source-line">يكثر تمييز النَّسبة في المواضع الآتية :</div><div class="rule-source-line">1- التَّفْضِيلِ , نحو : أنت أجملُ مني صوتاً .</div><div class="rule-source-line">2- التَّعَجُّبُ , نحو : ما أحسنَ علياًّ خطاًّ .</div><div class="rule-source-line">3- الْمَدْحُ والذَّمُ , نحو : نِعْمَ خُلُقاً الصَِّدْقُ . بِئْسَ خُلُقاً الكَذِبُ .</div><div class="rule-source-line">4- باب فَعُلَ , نحو : حَسُنَ , وكَبُرَ , وعَظُمَ .</div><div class="rule-source-line">5- باب اِفْتَعَلَ , نحو : امْتَلأَ , وارْتَفَعَ , وازْدَادَ , واشْتَعَلَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'التمييز اسم نكرة منصوب يفسر إبهاماً في ذات أو نسبة.'),
('Мединский курс (Том 4)', '13', 'صِيغَتَا التَّعَجُّبِ (две формы удивления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">صِيغَتَا التَّعَجُّبِ</span><p class="rule-study-text">две формы удивления. للتعجب صيغتان قياسيتان: ما أفعلَه وأفعلْ به.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">صِيغَتَا التَّعَجُّبِ</span><span class="rule-term-ru">صِيغَتَا التَّعَجُّبِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">للتَّعَجُّبِ صِيغَتَانِ قِيَاسِيَّتَانِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- ما أَفْعَلَهُ ! نحو: مَا أَحْسَنَ الاستقامةَ! ونحو قوله تعالى: [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">2- أَفْعِلْ بِهِ ! نحو : أَحْسِنْ بالاستقامةِ ! ونحو قوله تعالى : [موضع غير واضح في المصدر] .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الإعراب :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- ما أجملَ الوردةَ !</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">ما : نكرة تامَّة مبنية على السكون في محل رفع مبتدأ . ( ما : بمعنى شيء ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أجْمَلَ : فعل ماض مبني على الفتح , والفاعل ضمير مستتر وجوبا تقديره ( هو ) يعود إلى ( ما ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">صِيْغَتَا التَّعَجُّبِ</div><div class="rule-source-line">للتَّعَجُّبِ صِيغَتَانِ قِيَاسِيَّتَانِ :</div><div class="rule-source-line">1- ما أَفْعَلَهُ ! نحو: مَا أَحْسَنَ الاستقامةَ! ونحو قوله تعالى: [موضع غير واضح في المصدر] .</div><div class="rule-source-line">2- أَفْعِلْ بِهِ ! نحو : أَحْسِنْ بالاستقامةِ ! ونحو قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الإعراب :</div><div class="rule-source-line">1- ما أجملَ الوردةَ !</div><div class="rule-source-line">ما : نكرة تامَّة مبنية على السكون في محل رفع مبتدأ . ( ما : بمعنى شيء ) .</div><div class="rule-source-line">أجْمَلَ : فعل ماض مبني على الفتح , والفاعل ضمير مستتر وجوبا تقديره ( هو ) يعود إلى ( ما ) .</div><div class="rule-source-line">الوردةَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة . والجملة الفعلية في محل رفع خبر المبتدأ .</div><div class="rule-source-line">2- أَجْمِلْ بِالوردةِ !</div><div class="rule-source-line">أَجْمِلْ : فعل أمر مبني على السكون ، والفاعل ضمير مستتر وجوبا تقديره ( أنت ) .</div><div class="rule-source-line">بِـ : حرف جر زائد مبني على الكسر لا محلّ له من الإعراب .</div><div class="rule-source-line">الوردةِ : مفعول به منصوب وعلامة نصبه الفتحة المقدرة منع من ظهورها اشتغال المحل بالكسرة .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'للتعجب صيغتان قياسيتان: ما أفعلَه وأفعلْ به.'),
('Мединский курс (Том 4)', '14', 'الْحَالُ (обстоятельство состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْحَالُ</span><p class="rule-study-text">обстоятельство состояния. الحال اسم منصوب يبين هيئة صاحبه وقت وقوع الفعل.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">الْحَالُ — обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-term-ru">имя действующего лица/предмета</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-term-ru">имя объекта действия</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите صاحب الحال.</li><li>Проверьте, что الحال объясняет состояние во время действия.</li><li>Если الحال — جملة, найдите الرابط: واو الحال или ضمير.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">الحالُ : وَصْفٌ فَضْلَة نكرة ، يُذْكَرُ لِبَيَانِ هَيْئَةِ صَاحِبِهِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">والمرادُ بالوصفِ : الْمُشْتَقُّ ، نحو :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- اسم الفاعل : جاء الطالب ضاحكاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- اسم المفعول : خرج محمد مسروراً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">3- الصَّفَةُ الْمُشَبَّهَةُ ( أي : الْمُشَبَّهَة باسم الفاعل ) : جاءَ يونسُ حزيناً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">وتُشْتَقُّ من الفعل اللاَّزِم . وأوزانها كثيرة منها : فَعِيلٌ (حَزِينٌ ) وفَعِلٌ ( فَرِحٌ )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">وفُعَالٌ ( شُجَاعٌ ) وفَعْلٌ ( ضَخْمٌ ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الرَّابِعَ عَشَرَ</div><div class="rule-source-line">الْحَالُ</div><div class="rule-source-line">الحالُ : وَصْفٌ فَضْلَة نكرة ، يُذْكَرُ لِبَيَانِ هَيْئَةِ صَاحِبِهِ .</div><div class="rule-source-line">والمرادُ بالوصفِ : الْمُشْتَقُّ ، نحو :</div><div class="rule-source-line">1- اسم الفاعل : جاء الطالب ضاحكاً .</div><div class="rule-source-line">2- اسم المفعول : خرج محمد مسروراً .</div><div class="rule-source-line">3- الصَّفَةُ الْمُشَبَّهَةُ ( أي : الْمُشَبَّهَة باسم الفاعل ) : جاءَ يونسُ حزيناً .</div><div class="rule-source-line">وتُشْتَقُّ من الفعل اللاَّزِم . وأوزانها كثيرة منها : فَعِيلٌ (حَزِينٌ ) وفَعِلٌ ( فَرِحٌ )</div><div class="rule-source-line">وفُعَالٌ ( شُجَاعٌ ) وفَعْلٌ ( ضَخْمٌ ) .</div><div class="rule-source-line">والمرادُ بالفَضْلَةِ : ما ليسَ رُكْناً أَسَاسِيّاً في الجملة .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'الحال اسم منصوب يبين هيئة صاحبه وقت وقوع الفعل.'),
('Мединский курс (Том 4)', '14', 'صَاحِبُ الْحَالِ (слово, состояние которого объясняет الحال)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">صَاحِبُ الْحَالِ</span><p class="rule-study-text">слово, состояние которого объясняет الحال. صاحب الحال غالباً معرفة، وقد يأتي نكرة بشروط.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">صَاحِبُ الْحَالِ</span><span class="rule-term-ru">صَاحِبُ الْحَالِ — слово, состояние которого объясняет الحال</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите صاحب الحال.</li><li>Проверьте, что الحال объясняет состояние во время действия.</li><li>Если الحال — جملة, найдите الرابط: واو الحال или ضمير.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">الحالُ تُبَيِّنُ هيئةَ صاحبِها , وصاحبُ الحالِ يكونُ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- فاعلا , نحو : جاء الطالبُ ضاحكاً . نَامَ الطفلُ بَاكِياً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- مفعولا به , نحو : أكلت اللَّحْمَ مَشْوِيّاً . رأيتُ الهلالَ طَالِعاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">3- فاعلا ومفعولا به معاً , نحو : كلَّمْتُ المديرَ مَاشِيَيْنِ . اِسْتَقْبَلْتُ أَبِي مُبْتَسِمَيْنِ</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">4- نائبَ فاعلٍ , نحو : أُكِلَ اللَّحْمُ مَشْوِيّاً . طُبِعَ الكتابُ مُجَلَّداً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">5- مبتدأ , نحو : دخلتُ على المدير وعنده مدرسُنا جالساً . الفَاكِهَةُ نَاضِجَةً مُفِيدَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">6- خبرا , نحو : هذا مدرسُنا قادماً . هذا الهلالُ طَالِعاً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">صَاحِبُ الحالِ</div><div class="rule-source-line">الحالُ تُبَيِّنُ هيئةَ صاحبِها , وصاحبُ الحالِ يكونُ :</div><div class="rule-source-line">1- فاعلا , نحو : جاء الطالبُ ضاحكاً . نَامَ الطفلُ بَاكِياً .</div><div class="rule-source-line">2- مفعولا به , نحو : أكلت اللَّحْمَ مَشْوِيّاً . رأيتُ الهلالَ طَالِعاً .</div><div class="rule-source-line">3- فاعلا ومفعولا به معاً , نحو : كلَّمْتُ المديرَ مَاشِيَيْنِ . اِسْتَقْبَلْتُ أَبِي مُبْتَسِمَيْنِ</div><div class="rule-source-line">4- نائبَ فاعلٍ , نحو : أُكِلَ اللَّحْمُ مَشْوِيّاً . طُبِعَ الكتابُ مُجَلَّداً .</div><div class="rule-source-line">5- مبتدأ , نحو : دخلتُ على المدير وعنده مدرسُنا جالساً . الفَاكِهَةُ نَاضِجَةً مُفِيدَةٌ .</div><div class="rule-source-line">6- خبرا , نحو : هذا مدرسُنا قادماً . هذا الهلالُ طَالِعاً .</div><div class="rule-source-line">7- جارًّا ومجروراً , نحو : مررت بهندٍ جالسةً . كتبتُ بالقلمِ مكسوراً .</div><div class="rule-source-line">8- مضافا إليه , نحو : يُعْجِبُنِي تَأْدِيبُ الغُلاَمِ مُذْنِباً ، ونحو قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">الأصل في صاحب الحال أن يكون معرفة , وقد يأتي نكرة بأحد الْمُسَوَّغَاتِ الآتية :</div><div class="rule-source-line">1- إذا تقدَّمتِ الحالُ على صاحبِها , نحو : جاءني سائلاً طالبٌ .</div><div class="rule-source-line">2- إذا خُصِّصَ صاحبُ الحالِ بوصفٍ ، أو إضافةٍ , نحو :</div><div class="rule-source-line">أ- جاءني طالبٌ مجتهدٌ سائلاً ( وصف ) .</div><div class="rule-source-line">ب- جاءني طالبُ علمٍ سائلاً ( إضافة ) .</div><div class="rule-source-line">3- إذا تقدَّمَ على صاحبِ الحالِ نَهْيٌ ، أو نَفْيٌ ، أو استفهامٌ , نحو :</div><div class="rule-source-line">- ما جاء طالبٌ مُتَأَخَّراً ( نفي ) .</div><div class="rule-source-line">- لا يدخلْ طالبٌ الفصلَ مُتَأَخَّراً ( نهي ) .</div><div class="rule-source-line">- هل جاء طالبٌ مُتَأَخَّراً ؟ ( استفهام ) .</div><div class="rule-source-line">4- إذا كانَ الحالُ جملةً مسبوقةً بالواوِ , نحو : جاءني طالبٌ وهو مبتسمٌ .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">قد يأتي صاحب الحال نكرة بلا مُسَوِّغٍ , كما في الحديث : &quot; صلَّى رسولُ اللهِ ( قاعداً وصَلَّى وَرَاءَهُ رِجاَلٌ قِيَاماً &quot;.</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'صاحب الحال غالباً معرفة، وقد يأتي نكرة بشروط.'),
('Мединский курс (Том 4)', '14', 'أَنْوَاعُ الْحَالِ (виды حال)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنْوَاعُ الْحَالِ</span><p class="rule-study-text">виды حال. الحال تكون مفردة أو جملة اسمية/فعلية أو شبه جملة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">أَنْوَاعُ الْحَالِ</span><span class="rule-term-ru">أَنْوَاعُ الْحَالِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите صاحب الحال.</li><li>Проверьте, что الحال объясняет состояние во время действия.</li><li>Если الحال — جملة, найдите الرابط: واو الحال или ضمير.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">1- الحالُ الْمُفْرَدَةُ ( أي : ما ليس بجملة ) نحو : جاء الطَّالبُ مَسْرُوراً ,</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جاء الطَّالبان مَسْرُورَيْنِ , جاء الطُّلابُ مَسْرُورِيْنَ , جاءت الطَّالباتُ مَسْرُورَاتٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">مسروراً : حال منصوب وعلامة نصبه الفتحة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">مسرورينَِ : حال منصوب وعلامة نصبه الياء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">مسروراتٍ : حال منصوب وعلامة نصبه الكسرة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- الحالُ الجملةُ , والجملة نوعان :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أ- اِسْمِيَّةٌ , نحو : جاء الطالبُ وهو يضحكُ . جاء الطالبُ كِتَابُهُ في يَدِهِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">أنواعُ الحالِ</div><div class="rule-source-line">1- الحالُ الْمُفْرَدَةُ ( أي : ما ليس بجملة ) نحو : جاء الطَّالبُ مَسْرُوراً ,</div><div class="rule-source-line">جاء الطَّالبان مَسْرُورَيْنِ , جاء الطُّلابُ مَسْرُورِيْنَ , جاءت الطَّالباتُ مَسْرُورَاتٍ .</div><div class="rule-source-line">مسروراً : حال منصوب وعلامة نصبه الفتحة .</div><div class="rule-source-line">مسرورينَِ : حال منصوب وعلامة نصبه الياء .</div><div class="rule-source-line">مسروراتٍ : حال منصوب وعلامة نصبه الكسرة .</div><div class="rule-source-line">2- الحالُ الجملةُ , والجملة نوعان :</div><div class="rule-source-line">أ- اِسْمِيَّةٌ , نحو : جاء الطالبُ وهو يضحكُ . جاء الطالبُ كِتَابُهُ في يَدِهِ .</div><div class="rule-source-line">• الجملة الاسمية ( هو يضحك ، كتابه في يده ) في محل نصب حال .</div><div class="rule-source-line">ب- فِعْلِيَّةٌ , نحو : جاء الطالبُ يضحكُ . دخل الطالبُ وقد شُرِحَ الدرسُ .</div><div class="rule-source-line">• الجملة الفعلية ( يضحك ، شُرِحَ الدرسُ ) في محل نصب حال .</div><div class="rule-source-line">3- شِبْهُ الجملةِ ، وهي نوعان :</div><div class="rule-source-line">أ- جَارٌّ ومَجْرُورٌ , نحو : رأيتُ العُصْفُورَ عَلَى الْغُصْنِ . ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">ب- ظَرْفٌ , نحو : رأيتُ القَائِدَ بَيْنَ جُنُودِهِ . نظرتُ إلى العصفور فوقَ الشَّجرةِ .</div><div class="rule-source-line">شبه الجملة ( الجار والمجرور , والظَّرف ) في محل نصب حال .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'الحال تكون مفردة أو جملة اسمية/فعلية أو شبه جملة.'),
('Мединский курс (Том 4)', '14', 'الرَّابِطُ فِي جُمْلَةِ الْحَالِ (связка в предложении حال)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الرَّابِطُ فِي جُمْلَةِ الْحَالِ</span><p class="rule-study-text">связка в предложении حال. جملة الحال تحتاج إلى رابط: واو الحال أو ضمير أو هما معاً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الرَّابِطُ فِي جُمْلَةِ الْحَالِ</span><span class="rule-term-ru">الرَّابِطُ فِي جُمْلَةِ الْحَالِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">صَاحِبُ الْحَالِ</span><span class="rule-term-ru">слово, состояние которого объясняет الحال</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите صاحب الحال.</li><li>Проверьте, что الحال объясняет состояние во время действия.</li><li>Если الحال — جملة, найдите الرابط: واو الحال или ضمير.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">يُشترط في الحال الجملة أن تشتمل على رابط يعود إلى صاحب الحال , والرَّابط ثلاثة أنواع :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">1- الضَّميرُ وحدَه , نحو : جاءَ الطَّالبُ يضحكُ , الرابط : ضمير مستتر تقديره : هو .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : جاءَ الطُّلابُ يضحكون ، الرابط : واو الجماعة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : جاءَ الطَّالبانِ يضحكان ، الرابط ألف الاثنين .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : جاءتِ الطَّالباتُ يضحكْنَ ، الرابط نون النِّسوة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ومنه قوله تعالى : [موضع غير واضح في المصدر] الرابط : واو الجماعة .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- الواوُ وحدَها , نحو : وصلت مكة والشَّمْسُ تَغْرُبُ . وصلتُ مكَّةَ وقد غَرَبَتِ الشَّمسُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الرَّابِطُ</div><div class="rule-source-line">يُشترط في الحال الجملة أن تشتمل على رابط يعود إلى صاحب الحال , والرَّابط ثلاثة أنواع :</div><div class="rule-source-line">1- الضَّميرُ وحدَه , نحو : جاءَ الطَّالبُ يضحكُ , الرابط : ضمير مستتر تقديره : هو .</div><div class="rule-source-line">ونحو : جاءَ الطُّلابُ يضحكون ، الرابط : واو الجماعة .</div><div class="rule-source-line">ونحو : جاءَ الطَّالبانِ يضحكان ، الرابط ألف الاثنين .</div><div class="rule-source-line">ونحو : جاءتِ الطَّالباتُ يضحكْنَ ، الرابط نون النِّسوة .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] الرابط : واو الجماعة .</div><div class="rule-source-line">2- الواوُ وحدَها , نحو : وصلت مكة والشَّمْسُ تَغْرُبُ . وصلتُ مكَّةَ وقد غَرَبَتِ الشَّمسُ .</div><div class="rule-source-line">3- الواوُ والضَّميرُ معاً , نحو : جاء الطالبُ وهو يضحك . حججتُ وأنا صغيرٌ .</div><div class="rule-source-line">ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">الجمعُ على فِعَالٍ ، وفُعُولٍ</div><div class="rule-source-line">قال تعالى : [موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  .</div><div class="rule-source-line">وفي الحديث : &quot; خَرَجَ رَسُولُ اللهِ ( فَإِذَا نِسْوَةٌ جُلُوسٌ &quot; .</div><div class="rule-source-line">قِيَاماً ، وقُعُوداً ، وجُلُوسٌ : جَمْعٌ لِلْمُذَكَّرِ وَالْمُؤَنَّثِ . فقِيَامٌ جَمْعُ قَائِمٍ ، وقَائِمَةٍ .</div><div class="rule-source-line">وقُعُودٌ : جَمْعُ قَاعِدٍ ، وقَاعِدَةٍ . وجُلُوسٌ : جَمْعُ جَالِسٍ ، وجَالِسَةٍ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'جملة الحال تحتاج إلى رابط: واو الحال أو ضمير أو هما معاً.'),
('Мединский курс (Том 4)', '15', 'الِاسْتِثْنَاءُ (исключение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الِاسْتِثْنَاءُ</span><p class="rule-study-text">исключение. الاستثناء إخراج ما بعد أداة الاستثناء من حكم ما قبلها، وله متصل ومنقطع ومفرغ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الِاسْتِثْنَاءُ</span><span class="rule-term-ru">الِاسْتِثْنَاءُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">اسْتِثْنَاءٌ</span><span class="rule-term-ru">исключение</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْتَثْنًى</span><span class="rule-term-ru">исключаемое слово</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْتَثْنًى مِنْهُ</span><span class="rule-term-ru">то, из чего делается исключение</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">سِوَى</span><span class="rule-term-ru">слово исключения, подобное غير</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا خَلَا</span><span class="rule-term-ru">исключение через ما خلا</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا عَدَا</span><span class="rule-term-ru">исключение через ما عدا</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الاستثناءُ : إِخْرَاجُ مَا بَعْدَ أَدَاةِ الاسْتِثْنَاءِ مِنْ حُكْمِ ما قَبْلَهَا .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">أَرْكَانُهُ : ثلاثة , هي : المستثنَى مِنْهُ , وأداةُ الاستثناءِ , والمستثنَى .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : نجحَ الطُّلابُ              إِلاَّ             طالباً منهم .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أدواته كثيرة , منها :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- إلاَّ : حرف .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">2- غَيْرُ ، وسِوَى : اسمان .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">3- مَاعَدَا ، ومَاخَلاَ : فعلان .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ الْخَامِسَ عَشَرَ</div><div class="rule-source-line">الاِسْتِثْنَاءُ</div><div class="rule-source-line">الاستثناءُ : إِخْرَاجُ مَا بَعْدَ أَدَاةِ الاسْتِثْنَاءِ مِنْ حُكْمِ ما قَبْلَهَا .</div><div class="rule-source-line">أَرْكَانُهُ : ثلاثة , هي : المستثنَى مِنْهُ , وأداةُ الاستثناءِ , والمستثنَى .</div><div class="rule-source-line">نحو : نجحَ الطُّلابُ              إِلاَّ             طالباً منهم .</div><div class="rule-source-line">المستثنى منه       أداة الاستثناء       المستثنى</div><div class="rule-source-line">أدواته كثيرة , منها :</div><div class="rule-source-line">1- إلاَّ : حرف .</div><div class="rule-source-line">2- غَيْرُ ، وسِوَى : اسمان .</div><div class="rule-source-line">3- مَاعَدَا ، ومَاخَلاَ : فعلان .</div><div class="rule-source-line">أقسامُه : مُتَّصِلٌ ، وَمُنْقَطِعٌ .</div><div class="rule-source-line">1- الْمُتَّصِلُ : هو ما كان المستثنى بعضاً من المستثنى منه .</div><div class="rule-source-line">نحو : حَضَرَ المدرسون إلاَّ مدرساً منهم . حفظت القرآن إلا سورةَ البقرةِ .</div><div class="rule-source-line">وهو قسمان :</div><div class="rule-source-line">أ- مُتَّصِلٌ تَامٌّ مُوجَبٌ .                        ب- مُتَّصِلٌ تَامٌّ غَيْرُ مُوجَبٍ .</div><div class="rule-source-line">* فإذا ذُكر المستثنى منه فهو تامٌّ ، وإذا لم يسبق بنهي , أو نفي , أو استفهام فهو موجبٌ.</div><div class="rule-source-line">نحو : نجحَ الطُّلابُ إلا طالباً منهم ( متصل تام موجب ) ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">* أما إذا سُبِق بنهي , أو نفي , أو استفهام فهو غير موجب , نحو : ما نجح الطلابُ إلا طالباً منهم . هل نجح الطلابُ إلا إيَّاكَ ؟ لا تسأل أحداً إلا المدرسَ . ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] . ( هذه الأمثلة مُتَّصِلَةٌ تَامَّةٌ غيرُ موجبةٍ ) .</div><div class="rule-source-line">* وإذا حُذف المستثنى منه سُمِّيَ الاستثناءُ حينئذٍ مُفَرَّغاً ،ولا يكونُ المفرَّغُ إلا غَيْرَ مُوجَبٍ،   نحو : ما حضر إلا عليٌّ . لا تسألْ إلا خالداً . هل مررت إلا بعليٍّ ؟ ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">2- الْمُنْقَطِعُ : هو ما لم يكن المستثنى بعضاً من المستثنى منه ، نحو : حضر الطلابُ إلا المدرسين . أكلت الطعامَ إلا الدواءَ . ومنه قوله تعالى : [موضع غير واضح في المصدر] .</div><div class="rule-source-line">ويكون تاماًّ مُوجَباً كما في الأمثلة السابقة , ويكون تامًّا غيرَ موجبٍ ، نحو :              ما حضر الطلابُ إلا المدرسين .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'الاستثناء إخراج ما بعد أداة الاستثناء من حكم ما قبلها، وله متصل ومنقطع ومفرغ.'),
('Мединский курс (Том 4)', '15', 'حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُتَّصِلِ (разбор исключаемого с إلا в связанном исключении)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُتَّصِلِ</span><p class="rule-study-text">разбор исключаемого с إلا в связанном исключении. في المتصل التام الموجب يجب نصب المستثنى، وفي غير الموجب يجوز النصب أو الإتباع.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُتَّصِلِ</span><span class="rule-term-ru">حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُتَّصِلِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">اسْتِثْنَاءٌ</span><span class="rule-term-ru">исключение</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْتَثْنًى</span><span class="rule-term-ru">исключаемое слово</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">1- يجبُ نصبُه , وذلك إذا كان متصلا تاماًّ مُوجباً , نحو : نجح الطلاب إلا طالباً منهم .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">2- يجوزُ النَّصْبُ ، والإتْبَاعُ ( على أنه بَدَلُ بَعْضٍ مِنْ كُلّ , وهو الأَفْصَحُ ) وذلك إذا كان متَّصلا تاماًّ غيرَ موجب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : ما نجح الطلابُ إِلاَّ طالباً منهم : مستثنى جائز النَّصب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">ويجوز : ما نجح الطلابُ إِلاَّ طالبٌ منهم : بدل مرفوع .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : ما مررتُ بِأحدٍ إِلاَّ طالباً منهم . ويجوز : إِلاَّ طالبٍ : بدل مجرور .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : هل سألتَ الطلابَ إلا حامداً ( بالنَّصب على أنه مستثنى منصوب ، أو بدل منصوب ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حكمُ المستثنى بـ ( إِلاَّ ) في الاستثناءِ الْمُتَّصِلِ</div><div class="rule-source-line">1- يجبُ نصبُه , وذلك إذا كان متصلا تاماًّ مُوجباً , نحو : نجح الطلاب إلا طالباً منهم .</div><div class="rule-source-line">2- يجوزُ النَّصْبُ ، والإتْبَاعُ ( على أنه بَدَلُ بَعْضٍ مِنْ كُلّ , وهو الأَفْصَحُ ) وذلك إذا كان متَّصلا تاماًّ غيرَ موجب .</div><div class="rule-source-line">نحو : ما نجح الطلابُ إِلاَّ طالباً منهم : مستثنى جائز النَّصب .</div><div class="rule-source-line">ويجوز : ما نجح الطلابُ إِلاَّ طالبٌ منهم : بدل مرفوع .</div><div class="rule-source-line">ونحو : ما مررتُ بِأحدٍ إِلاَّ طالباً منهم . ويجوز : إِلاَّ طالبٍ : بدل مجرور .</div><div class="rule-source-line">ونحو : هل سألتَ الطلابَ إلا حامداً ( بالنَّصب على أنه مستثنى منصوب ، أو بدل منصوب ) .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'في المتصل التام الموجب يجب نصب المستثنى، وفي غير الموجب يجوز النصب أو الإتباع.'),
('Мединский курс (Том 4)', '15', 'حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُنْقَطِعِ (исключаемое с إلا в разорванном исключении)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُنْقَطِعِ</span><p class="rule-study-text">исключаемое с إلا в разорванном исключении. المستثنى في المنقطع يجب نصبه في جميع أحواله.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُنْقَطِعِ</span><span class="rule-term-ru">حُكْمُ الْمُسْتَثْنَى بِـإِلَّا فِي الِاسْتِثْنَاءِ الْمُنْقَطِعِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">اسْتِثْنَاءٌ</span><span class="rule-term-ru">исключение</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْتَثْنًى</span><span class="rule-term-ru">исключаемое слово</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">يجبُ نصبُه في جميعِ أحوالِهِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : حضر المدرسون إلا الطلابَ .        ما حضر المدرسون إلا الطلابَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حكمُ المستثنى بـ ( إِلاَّ ) في الاستثناءِ الْمُنْقَطِعِ</div><div class="rule-source-line">يجبُ نصبُه في جميعِ أحوالِهِ .</div><div class="rule-source-line">نحو : حضر المدرسون إلا الطلابَ .        ما حضر المدرسون إلا الطلابَ .</div><div class="rule-source-line">مستثنى منصوب                        مستثنى منصوب</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'المستثنى في المنقطع يجب نصبه في جميع أحواله.'),
('Мединский курс (Том 4)', '15', 'حُكْمُ الِاسْتِثْنَاءِ الْمُفَرَّغِ (разбор неполного исключения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حُكْمُ الِاسْتِثْنَاءِ الْمُفَرَّغِ</span><p class="rule-study-text">разбор неполного исключения. في الاستثناء المفرغ يعرب ما بعد إلا بحسب ما يطلبه العامل، وتكون إلا ملغاة إعرابياً.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">حُكْمُ الِاسْتِثْنَاءِ الْمُفَرَّغِ</span><span class="rule-term-ru">حُكْمُ الِاسْتِثْنَاءِ الْمُفَرَّغِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">اسْتِثْنَاءٌ</span><span class="rule-term-ru">исключение</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْتَثْنًى</span><span class="rule-term-ru">исключаемое слово</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">يُعْرَبُ بِحَسَبِ ما يَطْلُبُهُ العَامِلُ ، نحو : ما جاء إلا عليٌّ ( فاعل مرفوع ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : لا تسألْ إلا خالداً ( مفعول به منصوب ) ما مررتُ إلا بخالدٍ ( اسم مجرور ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : ما كنت إلا طالباً (خبر كان منصوب) ونحو: ما جِئتُ إلا ماشياً (حال منصوبة).</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وتكون ( إلاَّ ) مُلْغَاةً من النَّاحيةِ الإعرابيَّةِ ,كأنها غير مذكورةٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حكمُ المستثنى بـ ( إِلاَّ ) في الاستثناءِ الْمُفَرَّغِ</div><div class="rule-source-line">يُعْرَبُ بِحَسَبِ ما يَطْلُبُهُ العَامِلُ ، نحو : ما جاء إلا عليٌّ ( فاعل مرفوع ) .</div><div class="rule-source-line">ونحو : لا تسألْ إلا خالداً ( مفعول به منصوب ) ما مررتُ إلا بخالدٍ ( اسم مجرور ) .</div><div class="rule-source-line">ونحو : ما كنت إلا طالباً (خبر كان منصوب) ونحو: ما جِئتُ إلا ماشياً (حال منصوبة).</div><div class="rule-source-line">وتكون ( إلاَّ ) مُلْغَاةً من النَّاحيةِ الإعرابيَّةِ ,كأنها غير مذكورةٍ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'في الاستثناء المفرغ يعرب ما بعد إلا بحسب ما يطلبه العامل، وتكون إلا ملغاة إعرابياً.'),
('Мединский курс (Том 4)', '15', 'حُكْمُ الْمُسْتَثْنَى بِـغَيْرِ وَسِوَى (исключение через غير и سوى)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـغَيْرِ وَسِوَى</span><p class="rule-study-text">исключение через غير и سوى. المستثنى بعد غير وسوى مجرور بالإضافة، وغير وسوى يعربان إعراب المستثنى بإلا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـغَيْرِ وَسِوَى</span><span class="rule-term-ru">حُكْمُ الْمُسْتَثْنَى بِـغَيْرِ وَسِوَى — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْتَثْنًى</span><span class="rule-term-ru">исключаемое слово</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">سِوَى</span><span class="rule-term-ru">слово исключения, подобное غير</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">حكم المستثنى بغير ، وسوى : الْجَرُّ بالإضافةِ دائماً . وغيرُ ، وسِوَى يُعربان إعرابَ المستثنى بـ ( إِلاَّ ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : أ- نجح الطلابُ          غيرَ                        طالبٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ب- ما نجح الطلابُ      غيرَُ                    طالبٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">يجوز فيه وجهان : بدل مرفوع          مضاف إليه مجرور</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ج- ما جاء غيرُ عليٍّ .       لا تسأل غيرَ  عليٍّ .          ما مررتُ بغيرِ عليٍّ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حكمُ المستثنى بِـ غَيْرِ ، وسِوَى</div><div class="rule-source-line">حكم المستثنى بغير ، وسوى : الْجَرُّ بالإضافةِ دائماً . وغيرُ ، وسِوَى يُعربان إعرابَ المستثنى بـ ( إِلاَّ ) .</div><div class="rule-source-line">نحو : أ- نجح الطلابُ          غيرَ                        طالبٍ .</div><div class="rule-source-line">مستثنى واجب النصب        مضاف إليه مجرور</div><div class="rule-source-line">ب- ما نجح الطلابُ      غيرَُ                    طالبٍ .</div><div class="rule-source-line">يجوز فيه وجهان : بدل مرفوع          مضاف إليه مجرور</div><div class="rule-source-line">أو مستثنى منصوب</div><div class="rule-source-line">ج- ما جاء غيرُ عليٍّ .       لا تسأل غيرَ  عليٍّ .          ما مررتُ بغيرِ عليٍّ .</div><div class="rule-source-line">فاعل   مضاف إليه    مفعول به   مضاف إليه     اسم مجرور   مضاف إليه</div><div class="rule-source-line">مرفوع     مجرور      منصوب      مجرور                         مجرور</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'المستثنى بعد غير وسوى مجرور بالإضافة، وغير وسوى يعربان إعراب المستثنى بإلا.'),
('Мединский курс (Том 4)', '15', 'حُكْمُ الْمُسْتَثْنَى بِـمَا خَلَا وَمَا عَدَا (исключение через ما خلا и ما عدا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـمَا خَلَا وَمَا عَدَا</span><p class="rule-study-text">исключение через ما خلا и ما عدا. ما خلا وما عدا فعلان ماضيان جامدان، وما بعدهما مفعول به منصوب.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">حُكْمُ الْمُسْتَثْنَى بِـمَا خَلَا وَمَا عَدَا</span><span class="rule-term-ru">حُكْمُ الْمُسْتَثْنَى بِـمَا خَلَا وَمَا عَدَا — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْتَثْنًى</span><span class="rule-term-ru">исключаемое слово</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا خَلَا</span><span class="rule-term-ru">исключение через ما خلا</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا عَدَا</span><span class="rule-term-ru">исключение через ما عدا</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مَا خَلاَ ، ومَا عَدَا : فعلان ماضيان جامدان .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">حكمُ المستثنى بهما : النَّصبُ على أنه مفعولٌ به , والفاعل ضمير مستتر تقديره ( هو )</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">يعود إلى كلمة ( بعض ) المفهومة من الجملة , نحو : قرأتُ الكُتُبَ ما خَلاَ كتاباً : مفعول</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">به منصوب . كافأتُ الطلابَ ما عدا طالباً : مفعول به منصوب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">حكمُ المستثنى بِـ مَا خَلاَ ، وَمَا عَدَا</div><div class="rule-source-line">مَا خَلاَ ، ومَا عَدَا : فعلان ماضيان جامدان .</div><div class="rule-source-line">حكمُ المستثنى بهما : النَّصبُ على أنه مفعولٌ به , والفاعل ضمير مستتر تقديره ( هو )</div><div class="rule-source-line">يعود إلى كلمة ( بعض ) المفهومة من الجملة , نحو : قرأتُ الكُتُبَ ما خَلاَ كتاباً : مفعول</div><div class="rule-source-line">به منصوب . كافأتُ الطلابَ ما عدا طالباً : مفعول به منصوب .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 6, 'rule', 'ما خلا وما عدا فعلان ماضيان جامدان، وما بعدهما مفعول به منصوب.'),
('Мединский курс (Том 4)', '15', 'الضَّمِيرُ الْوَاقِعُ خَبَرًا لِكَانَ (местоимение в роли خبر كان)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الضَّمِيرُ الْوَاقِعُ خَبَرًا لِكَانَ</span><p class="rule-study-text">местоимение в роли خبر كان. إذا وقع الضمير خبراً لكان جاز فيه الوصل والفصل.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمِيرُ الْوَاقِعُ خَبَرًا لِكَانَ</span><span class="rule-term-ru">الضَّمِيرُ الْوَاقِعُ خَبَرًا لِكَانَ — название правила; русский смысл указан в заголовке карточки</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите тип ضمير: منفصل، متصل или مستتر.</li><li>Проверьте его место: رفع، نصب или جرّ.</li><li>Если местоимений несколько, соблюдайте порядок رتب الضمائر.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">إذا وقع الضَّميرُ خبراً لِكَانَ جَازَ فيه الْوَصْلُ ، والْفَصْلُ , نحو: أَخْشَى أَنْ أَكُونَهُ (بالوَصْل) ويجوز : أَخْشَى أَنْ أَكُونَ إِيَّاهُ ( بالفَصْل ) ونحو : الصَّدِيقُ كُنْتَهُ ، وكُنْتَ إِيَّاهُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الضَّمِيرُ الْوَاِقعُ خَبَراً لِكَانَ</div><div class="rule-source-line">إذا وقع الضَّميرُ خبراً لِكَانَ جَازَ فيه الْوَصْلُ ، والْفَصْلُ , نحو: أَخْشَى أَنْ أَكُونَهُ (بالوَصْل) ويجوز : أَخْشَى أَنْ أَكُونَ إِيَّاهُ ( بالفَصْل ) ونحو : الصَّدِيقُ كُنْتَهُ ، وكُنْتَ إِيَّاهُ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 7, 'rule', 'إذا وقع الضمير خبراً لكان جاز فيه الوصل والفصل.'),
('Мединский курс (Том 4)', '15', 'أَلَا حَرْفُ اسْتِفْتَاحٍ وَتَنْبِيهٍ (ألا как частица начала и привлечения внимания)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَلَا حَرْفُ اسْتِفْتَاحٍ وَتَنْبِيهٍ</span><p class="rule-study-text">ألا как частица начала и привлечения внимания. ألا حرف استفتاح وتنبيه مبني لا محل له من الإعراب.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلَا حَرْفُ اسْتِفْتَاحٍ وَتَنْبِيهٍ</span><span class="rule-term-ru">أَلَا حَرْفُ اسْتِفْتَاحٍ وَتَنْبِيهٍ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أَلاَ : حرفُ استفتاحٍ وتنبيهٍ , نحو قوله تعالى : [موضع غير واضح في المصدر] وقوله تعالى :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">[موضع غير واضح في المصدر] ونحو قولك : أَلاَ إنَّ المؤمنين هُمُ المفلحون .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jazm"><span class="rule-example-ar" dir="rtl" lang="ar">* ألا : حرف استفتاح وتنبيه مبني على السكون لا محل له من الإعراب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">( أَلاَ ) حَرْفُ اِسْتِفْتَاحٍ وتَنْبِيهٍ</div><div class="rule-source-line">أَلاَ : حرفُ استفتاحٍ وتنبيهٍ , نحو قوله تعالى : [موضع غير واضح في المصدر] وقوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] ونحو قولك : أَلاَ إنَّ المؤمنين هُمُ المفلحون .</div><div class="rule-source-line">* ألا : حرف استفتاح وتنبيه مبني على السكون لا محل له من الإعراب .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 8, 'rule', 'ألا حرف استفتاح وتنبيه مبني لا محل له من الإعراب.'),
('Мединский курс (Том 4)', '15', 'جَمْعُ دِينَارٍ عَلَى غَيْرِ قِيَاسٍ (множественное دينار не по обычному القياس)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَمْعُ دِينَارٍ عَلَى غَيْرِ قِيَاسٍ</span><p class="rule-study-text">множественное دينار не по обычному القياس. دينار يجمع على دنانير على غير قياس، ومثله ديوان وقيراط وديماس.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">جَمْعُ دِينَارٍ عَلَى غَيْرِ قِيَاسٍ</span><span class="rule-term-ru">جَمْعُ دِينَارٍ عَلَى غَيْرِ قِيَاسٍ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">دِينَارٌ ، جَمْعُهُ : دَنَانِيرُ , وذلك على غير قياس ؛ إذِ الْقِيَاسُ أن يكون جمعه : دَيَانِيرُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ومثله : دِيْوَانٌ ، جمعه : دَوَاوِينُ , على غير قياس , والقياس : دَيَاوِينُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : قِيْرَاطٌ ، جمعه : قَرَارِيطُ ، على غير قياس ، والقياس : قَيَارِيطُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ونحو : دِيْمَاسٌ ، جمعه : دَمَامِيسُ ، على غير قياس ، والقياس : دَيَامِيسُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">جَمْعُ دِينَارٍ عَلَى غَيْرِ قِيَاسٍ</div><div class="rule-source-line">دِينَارٌ ، جَمْعُهُ : دَنَانِيرُ , وذلك على غير قياس ؛ إذِ الْقِيَاسُ أن يكون جمعه : دَيَانِيرُ .</div><div class="rule-source-line">ومثله : دِيْوَانٌ ، جمعه : دَوَاوِينُ , على غير قياس , والقياس : دَيَاوِينُ .</div><div class="rule-source-line">ونحو : قِيْرَاطٌ ، جمعه : قَرَارِيطُ ، على غير قياس ، والقياس : قَيَارِيطُ .</div><div class="rule-source-line">ونحو : دِيْمَاسٌ ، جمعه : دَمَامِيسُ ، على غير قياس ، والقياس : دَيَامِيسُ .</div><div class="rule-source-line">[موضع غير واضح في المصدر]</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 9, 'rule', 'دينار يجمع على دنانير على غير قياس، ومثله ديوان وقيراط وديماس.'),
('Мединский курс (Том 4)', '16', 'تَوْكِيدُ الْأَفْعَالِ بِنُونِ التَّوْكِيدِ (усиление глаголов نون التوكيد)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَوْكِيدُ الْأَفْعَالِ بِنُونِ التَّوْكِيدِ</span><p class="rule-study-text">усиление глаголов نون التوكيد. نون التوكيد ثقيلة وخفيفة، وتدخل على الأمر والمضارع بشروط، ولا تؤكد الماضي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">تَوْكِيدُ الْأَفْعَالِ بِنُونِ التَّوْكِيدِ</span><span class="rule-term-ru">تَوْكِيدُ الْأَفْعَالِ بِنُونِ التَّوْكِيدِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَوْلَا</span><span class="rule-term-ru">частица условия/побуждения; значение зависит от контекста</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّمَا</span><span class="rule-term-ru">частица ограничения: «только, лишь»</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">الْحَالُ</span><span class="rule-term-ru">обстоятельство состояния; обычно منصوب</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">نُونُ التَّوْكِيدِ</span><span class="rule-term-ru">نون усиления глагола: ثقيلة или خفيفة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مُعْرَبٌ</span><span class="rule-term-ru">слово с изменяемым окончанием</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">نونُ التوكيدِ نوعانِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أ- ثَقِيلَةٌ .           ب- خَفِيفَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أحكامُ توكيدِ الأفعالِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- الماضي : لا يُؤَكَّدُ بنونِ التَّوكيدِ ، وإنّما يُؤَكَّدُ بقَدْ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">2- الأمر : يجوز توكيده مطلقا ، : أي بدون شرط ، نحو : اِذْهَبَنَّ ، اِذْهَبَنْ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">3- المضارع : له أربع حالات :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أ- يجوزُ توكيدُه : وذلك إذا سُبِقَ بِطَلَبٍ ، نحو : هل تُسَافِرَنَّ وأنت مريضٌ ؟</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَرْسُ السَّادِسَ عَشَرَ</div><div class="rule-source-line">تَوْكِيدُ الأفعالِ بِنُونِ التَّوْكِيدِ</div><div class="rule-source-line">نونُ التوكيدِ نوعانِ :</div><div class="rule-source-line">أ- ثَقِيلَةٌ .           ب- خَفِيفَةٌ .</div><div class="rule-source-line">أحكامُ توكيدِ الأفعالِ :</div><div class="rule-source-line">1- الماضي : لا يُؤَكَّدُ بنونِ التَّوكيدِ ، وإنّما يُؤَكَّدُ بقَدْ .</div><div class="rule-source-line">2- الأمر : يجوز توكيده مطلقا ، : أي بدون شرط ، نحو : اِذْهَبَنَّ ، اِذْهَبَنْ .</div><div class="rule-source-line">3- المضارع : له أربع حالات :</div><div class="rule-source-line">أ- يجوزُ توكيدُه : وذلك إذا سُبِقَ بِطَلَبٍ ، نحو : هل تُسَافِرَنَّ وأنت مريضٌ ؟</div><div class="rule-source-line">لِيَقْرَأَنَّ كلُّ طالبٍ دَرْسَهُ . هَلاَّ تَجْتَهِدَنَّ . لاتُهْمِلَنَّ دُرُوسَكَ . ومنه قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] ...  [موضع غير واضح في المصدر]  .</div><div class="rule-source-line">ب- قَرِيبٌ مِنَ الواجبِ : وذلك إذا وقع بعد ( إِمَّا ) الشرطية ( أصلها إنْ الشرطية وما الزائدة ) نحو قوله تعالى : [موضع غير واضح في المصدر] وقوله تعالى : [موضع غير واضح في المصدر] ونحو :         إِمَّا تُسَافِرَنَّ إِلى مَكَّةَ أُسَافِرْ مَعَكَ .</div><div class="rule-source-line">ج- يجبُ توكيدُه : وذلك إذا وقع جواباً للقسم , وكان مُتَّصِلاً بلام جَوَابِ الْقَسَمِ , ومُثْبَتاً ( غيرَ منفيٍّ ) ومُسْتَقْبَلاً ، نحو: واللهِ لأَجْتَهِدَنَّ ، ونحو قوله تعالى :</div><div class="rule-source-line">[موضع غير واضح في المصدر] .</div><div class="rule-source-line">د- يمتنعُ توكيدُه : وذلك إذا لم يتحقَّقْ أحدُ الشُّروطِ الثَّلاثةِ السَّابقةِ .</div><div class="rule-source-line">نحو : واللهِ لسوف أجتهدُ . يمتنع توكيده ؛ لكونه مفصولا من لام الجواب بسوف .</div><div class="rule-source-line">ونحو : واللهِ لا أُدَخَّنُ . يمتنع توكيده ؛ لكونه مَنْفِيًّا .</div><div class="rule-source-line">ونحو : واللهِ لأَخْرُجُ الآنَ . يمتنع توكيده ؛ لكونه دالاًّ على الحال .</div><div class="rule-source-line">أحكامُ آخِرِ الفعلِ الْمُؤَكَّدِ بنونِ التَّوكيدِ :</div><div class="rule-source-line">1- إذا اتَّصلتْ نونُ التَّوكيدِ بالفعلِ اتِّصالاً مُباشراً بُنِيَ على الفتحِ .</div><div class="rule-source-line">نحو : اِذْهَبَنَّ - لا تَذْهَبَنَّ - يَذْهَبَنَّ . اِذْهَبَنْ - لا تَذْهَبَنْ - يَذْهَبَنْ .</div><div class="rule-source-line">2- إذا اتصلت نون التوكيد بفعل متَّصل بواو الجماعة حُذِفَتْ نونُ الرَّفعِ لِتَوَالِي الأَمْثَالِ ( أي : تَوَالِي ثلاثِ نُونَاتٍ ) ثم تُحْذَفُ واو الجماعة لالْتِقَاءِ السَّاكِنَيْنِ , ويُضَمُّ آخِرُ الفعلِ لِلدَّلاَلَةِ على أنّ المحذوفَ واوُ الجماعةِ , نحو : يَذْهَبُنَّ ، ويَذْهَبُنْ .</div><div class="rule-source-line">ويكونُ الفعلُ مُعْرَباً .</div><div class="rule-source-line">3- إذا اتَّصلت نون التوكيد بفعل متَّصل بياء المخاطَبة حُذفتْ نونُ الرَّفعِ لتوالي الأمثالِ ، ثم تُحذفُ ياءُ المخاطَبةِ لالتقاءِ السَّاكنين ، ويُكْسَرُ آخِرُ الفعلِ للدَّلالة على أنّ المحذوف ياء المخاطبة , نحو : تَذْهَبِنَّ ، وتَذْهَبِنْ . ويكون معرباً أيضاً .</div><div class="rule-source-line">4- إذا اتصلت نون التوكيد بفعل متصل بألف الاثنين حُذفت نون الرفع لتوالي الأمثال ، ولا تُحذف ألف الاثنين ( لِئَلاَّ يلْتَبِسَ بالمفرد ) وتُكْسَرُ نون التوكيد , نحو : يَذْهَبَانِّ .</div><div class="rule-source-line">وهو معربٌ أيضاً . ولا يجوز أن تتَّصل به النُّون الخفيفة .</div><div class="rule-source-line">5- إذا اتصلت نون التوكيد بفعل متصل بنون النَّسْوةِ لا تحذف نون النسوة , وتُزَادُ ألفٌ فَاصِلَةٌ ( لِلْفَصْلِ بين نون النِّسوة ونون التَّوكيد ) وتُكْسَرُ نون التوكيد ( تَشْبِيهاً لها بالمثنى ) نحو يَذْهَبْنَانِّ .</div><div class="rule-source-line">وهو مبنيٌّ على السُّكون لاتَّصَاله بنون النَّسْوَة . ولا يجوز أن تتصل به النون الخفيفة .</div><div class="rule-source-line">6- إذا أردنا توكيدَ الفعلِ المعتلِّ الآخِرِ بنون التَّوكيد في حالتي الجزم ، والأمر رَدَدْنَا حرفَ الْعِلَّةِ المحذوفَ , نحو :   اُدْعُ : اُدْعُوَنَّ  .      لا تَدْعُ : لا تَدْعُوَنَّ</div><div class="rule-source-line">اِرْمِ : اِرْمِيَنَّ  .        لا تَرْمِ : لا تَرْمِيَنَّ .</div><div class="rule-source-line">اِسْعَ : اِسْعَيَنَّ .       لا تَسْعَ : لا تَسْعَيَنَّ</div><div class="rule-source-line">الإعراب :</div><div class="rule-source-line">* يَذْهَبَنَّ : فعل مضارع مبني على الفتح ( لاتِّصاله مباشرة بنون التَّوكيد الثقيلة ) والفاعل</div><div class="rule-source-line">ضمير مستتر تقديره ( هو ) .</div><div class="rule-source-line">ونون التوكيد : حرفٌ مبنيٌّ على الفتح لا محل له من الإعراب .</div><div class="rule-source-line">* اِذْهَبَنْ : فعل أمر مبني على الفتح ( لاتِّصاله مباشرةً بنون التَّوكيد الخفيفة ) والفاعل ضمير مستتر تقديره ( أنت ) .</div><div class="rule-source-line">ونون التوكيد : حرف مبني على السكون لا محل له من الإعراب .</div><div class="rule-source-line">* يَذْهَبُنَّ : فعل مضارع مرفوع وعلامة رفعه النُّون المحذوفة لتوالي الأمثال ، واو الجماعة</div><div class="rule-source-line">المحذوفة لالتقاء الساكنين في محل رفع فاعل .</div><div class="rule-source-line">ونون التوكيد : حرف مبني على الفتح لا محل له من الإعراب .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'نون التوكيد ثقيلة وخفيفة، وتدخل على الأمر والمضارع بشروط، ولا تؤكد الماضي.'),
('Мединский курс (Том 4)', '16', 'بَلْ الِابْتِدَائِيَّةُ (начальная بل)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَلْ الِابْتِدَائِيَّةُ</span><p class="rule-study-text">начальная بل. بل الابتدائية تفيد الإضراب إذا وقع بعدها جملة اسمية أو فعلية.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ الِابْتِدَائِيَّةُ</span><span class="rule-term-ru">بَلْ الِابْتِدَائِيَّةُ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرٌ</span><span class="rule-term-ru">масдар: имя действия</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ظَنَّ</span><span class="rule-term-ru">глагол предположения; ставит два مفعول به</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">غَيْرُ</span><span class="rule-term-ru">слово исключения; само получает إعراب, следующее слово مجرور بالإضافة</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَبْنِيٌّ</span><span class="rule-term-ru">неизменяемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите المستثنى منه، أداة الاستثناء и المستثنى.</li><li>Определите тип: متصل، منقطع или مفرغ; затем проверьте موجب/غير موجب.</li><li>После этого выберите إعراب المستثنى: نصب، بدل/إتباع или حسب العامل.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">بَلْ : حرفُ ابتداءٍ يُفِيدُ الإِضْرَابَ إذا كان ما بعده جملةً اسميَّةً ، أو فعليَّةً .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">والإضراب ، نوعان : إِبْطَالِيٌّ ، وانْتِقَالِيٌّ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أ- الإِضْرَابُ الإبْطَاليُّ ، كما في قوله تعالى : [موضع غير واضح في المصدر] أي : بل هم عبادٌ مكرمون ، ونحو قولك : لا تَظُنَّنَّ الكَسْلانَ ناجحاً بل هو راسبٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ب- الإِضْرَابُ الانْتِقَالِيُّ ، كما في قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : اتَّقوا اللهَ وأَطِيعُوهُ  بَلْ قُلُوبُكُمْ لاَهِيَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jazm"><span class="rule-example-ar" dir="rtl" lang="ar">* بل : حرفُ ابتداءٍ مبنيٌّ على السُّكونِ لا محلَّ له من الإعراب .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">بَلْ الابْتِدَائِيَّةُ</div><div class="rule-source-line">بَلْ : حرفُ ابتداءٍ يُفِيدُ الإِضْرَابَ إذا كان ما بعده جملةً اسميَّةً ، أو فعليَّةً .</div><div class="rule-source-line">والإضراب ، نوعان : إِبْطَالِيٌّ ، وانْتِقَالِيٌّ .</div><div class="rule-source-line">أ- الإِضْرَابُ الإبْطَاليُّ ، كما في قوله تعالى : [موضع غير واضح في المصدر] أي : بل هم عبادٌ مكرمون ، ونحو قولك : لا تَظُنَّنَّ الكَسْلانَ ناجحاً بل هو راسبٌ .</div><div class="rule-source-line">ب- الإِضْرَابُ الانْتِقَالِيُّ ، كما في قوله تعالى : [موضع غير واضح في المصدر] ونحو قولك : اتَّقوا اللهَ وأَطِيعُوهُ  بَلْ قُلُوبُكُمْ لاَهِيَةٌ .</div><div class="rule-source-line">* بل : حرفُ ابتداءٍ مبنيٌّ على السُّكونِ لا محلَّ له من الإعراب .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'بل الابتدائية تفيد الإضراب إذا وقع بعدها جملة اسمية أو فعلية.'),
('Мединский курс (Том 4)', '17', 'الْمَمْنُوعُ مِنَ الصَّرْفِ (имя, не принимающее танвин)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><p class="rule-study-text">имя, не принимающее танвин. الممنوع من الصرف اسم معرب لا ينون، وينقسم إلى ممنوع لعلة واحدة أو لعلتين.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">الْمَمْنُوعُ مِنَ الصَّرْفِ — диптот: имя без танвина, с особым جرّ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مُعْرَبٌ</span><span class="rule-term-ru">слово с изменяемым окончанием</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, входит ли имя в одну из групп الْمَمْنُوعُ مِنَ الصَّرْفِ.</li><li>Не ставьте танвин.</li><li>В جرّ ставьте фатху вместо كسرة, кроме случаев с أَلْـ или إضافة.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الممنوعُ من الصَّرفِ ، هو : الاسْمُ الْمُعْرَبُ الَّذي لا يُنَوَّنُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أقسامُه: ينقسم إلى قسمين : ممنوع من الصَّرف لِعِلَّةٍ واحدةٍ ,وممنوع من الصَّرف لِعِلَّتَيْنِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">الدَّرْسُ السَّابِعَ عَشَرَ</div><div class="rule-source-line">الْمَمْنُوعُ مِنَ الصَّرْفِ</div><div class="rule-source-line">الممنوعُ من الصَّرفِ ، هو : الاسْمُ الْمُعْرَبُ الَّذي لا يُنَوَّنُ .</div><div class="rule-source-line">أقسامُه: ينقسم إلى قسمين : ممنوع من الصَّرف لِعِلَّةٍ واحدةٍ ,وممنوع من الصَّرف لِعِلَّتَيْنِ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 1, 'rule', 'الممنوع من الصرف اسم معرب لا ينون، وينقسم إلى ممنوع لعلة واحدة أو لعلتين.'),
('Мединский курс (Том 4)', '17', 'الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ (диптот по одной причине)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ</span><p class="rule-study-text">диптот по одной причине. منه المختوم بألف التأنيث وصيغة منتهى الجموع وما شابهها.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ</span><span class="rule-term-ru">الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">исполнитель действия; обычно مرفوع</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: имя без танвина, с особым جرّ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">صِيغَةُ مُنْتَهَى الْجُمُوعِ</span><span class="rule-term-ru">крайняя форма ломаного множественного</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, входит ли имя в одну из групп الْمَمْنُوعُ مِنَ الصَّرْفِ.</li><li>Не ставьте танвин.</li><li>В جرّ ставьте фатху вместо كسرة, кроме случаев с أَلْـ или إضافة.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- المختومُ بألفِ التَّأنيثِ المقصورةِ ، أو الممدودةِ ، بشرط أن تكون الألف زائدةً لا أصليةً ( ويُعرف ذلك بالرجوع إلى أصل الكلمة ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : مَرْضَى , وجَرْحَى , ويَتَامَى ؛ وصَحْرَاء , وأَغْنِيَاء , وحَمْرَاء .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">2- صِيغةُ مُنْتَهَى الْجُمُوعِ ( مَفَاعِلُ , ومَفَاعِيلُ ) وأَشْبَاهِهِمَا , نحو : مَسَاجِدَ , وفَنَادِقَ ؛ ومَصَابِيحَ , وثَعَابِينَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">3- المفردُ الذي على وزنِ مُنتهى الجموعِ ، نحو : بَطَاطِسَ , وطَمَاطِمَ , وطَبَاشِيرَ , وسَرَاوِيلَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">أ- الممنوعُ من الصَّرفِ لِعِلَّةٍ واحدةٍ</div><div class="rule-source-line">1- المختومُ بألفِ التَّأنيثِ المقصورةِ ، أو الممدودةِ ، بشرط أن تكون الألف زائدةً لا أصليةً ( ويُعرف ذلك بالرجوع إلى أصل الكلمة ) .</div><div class="rule-source-line">نحو : مَرْضَى , وجَرْحَى , ويَتَامَى ؛ وصَحْرَاء , وأَغْنِيَاء , وحَمْرَاء .</div><div class="rule-source-line">2- صِيغةُ مُنْتَهَى الْجُمُوعِ ( مَفَاعِلُ , ومَفَاعِيلُ ) وأَشْبَاهِهِمَا , نحو : مَسَاجِدَ , وفَنَادِقَ ؛ ومَصَابِيحَ , وثَعَابِينَ .</div><div class="rule-source-line">3- المفردُ الذي على وزنِ مُنتهى الجموعِ ، نحو : بَطَاطِسَ , وطَمَاطِمَ , وطَبَاشِيرَ , وسَرَاوِيلَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 2, 'rule', 'منه المختوم بألف التأنيث وصيغة منتهى الجموع وما شابهها.'),
('Мединский курс (Том 4)', '17', 'الْعَلَمُ الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ (собственные имена-диптоты по двум причинам)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْعَلَمُ الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ</span><p class="rule-study-text">собственные имена-диптоты по двум причинам. تمنع أعلام مثل المؤنث، الأعجمي، ما على وزن الفعل، المعدول، المختوم بألف ونون، والمركب المزجي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَلَمُ الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ</span><span class="rule-term-ru">الْعَلَمُ الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">بَلْ</span><span class="rule-term-ru">частица перехода/отвода: إضراب إبطالي или انتقالي</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: имя без танвина, с особым جرّ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, входит ли имя в одну из групп الْمَمْنُوعُ مِنَ الصَّرْفِ.</li><li>Не ставьте танвин.</li><li>В جرّ ставьте фатху вместо كسرة, кроме случаев с أَلْـ или إضافة.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">وهو نوعان :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أ- العَلَمُ : تُمْنَعُ الأَعْلاَمُ الآتِيةُ من الصَّرفِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">1- العلمُ المؤنَّثُ : نحو : فاطمةَ , وحمزةَ , ومريمَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">إذا كانَ العلمُ المؤنَّثُ ثلاثياً ساكنَ الوسطِ جَازَ صرفُه ومنعُه , ومَنْعُهُ أَوْلَى .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">نحو : هِنْدٍ , ورِيْمٍ , ودَعْدٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">2- العلمُ الأَعْجَمِيُّ : نحو : إبراهيمَ , وإسحاقَ , ولَنْدَنَ , وباكستانَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">إذا كان العلمُ الأعجميُّ ثلاثياًّ ساكنَ الوسطِ مذكَّراً صُرِفَ , نحو: نُوْحٍ , ولُوْطٍ , وشَاْهٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">ب- الممنوعُ من الصَّرفِ لِعِلَّتَيْنِ</div><div class="rule-source-line">وهو نوعان :</div><div class="rule-source-line">أ- العَلَمُ : تُمْنَعُ الأَعْلاَمُ الآتِيةُ من الصَّرفِ :</div><div class="rule-source-line">1- العلمُ المؤنَّثُ : نحو : فاطمةَ , وحمزةَ , ومريمَ .</div><div class="rule-source-line">إذا كانَ العلمُ المؤنَّثُ ثلاثياً ساكنَ الوسطِ جَازَ صرفُه ومنعُه , ومَنْعُهُ أَوْلَى .</div><div class="rule-source-line">نحو : هِنْدٍ , ورِيْمٍ , ودَعْدٍ .</div><div class="rule-source-line">2- العلمُ الأَعْجَمِيُّ : نحو : إبراهيمَ , وإسحاقَ , ولَنْدَنَ , وباكستانَ .</div><div class="rule-source-line">إذا كان العلمُ الأعجميُّ ثلاثياًّ ساكنَ الوسطِ مذكَّراً صُرِفَ , نحو: نُوْحٍ , ولُوْطٍ , وشَاْهٍ .</div><div class="rule-source-line">أما إذا كان مُؤَنَّثاً فيُمنع من الصَّرف , نحو : مُوْشَ ( مدينة في تركيا ) ونِيْسَ ( مدينة في فرنسا ) وبَلْخَ ( مدينة في أفغانستان ) .</div><div class="rule-source-line">3- العلمُ ووَزْنُ الْفِعْلِ ، نحو : أحْمَدَ , ويَزِيدَ , ويَنْبُعَ .</div><div class="rule-source-line">4- العلمُ الْمَعْدُولُ ، نحو : عُمَرَ ( قَدَّر النحويون أنه معدول من عَامِر ) وزُفَرَ (من َزافِر) وهُبَلَ (من هَابِِل ) .</div><div class="rule-source-line">5- العلمُ المختومُ بِأَلِفٍ ونُونٍ زَائِدَتَيْنِ : نحو : عثمانَ , ورمضانَ , ومروانَ .</div><div class="rule-source-line">6- العلم الْمُرَكَّبُ تَرْكِيباً مَزْجِيّاً ، نحو : حَضْرَمَوْتَ , وبَعْلَبَكَّ , ومَعْدِيكَرِبَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 3, 'rule', 'تمنع أعلام مثل المؤنث، الأعجمي، ما على وزن الفعل، المعدول، المختوم بألف ونون، والمركب المزجي.'),
('Мединский курс (Том 4)', '17', 'الصِّفَةُ الْمَمْنُوعَةُ مِنَ الصَّرْفِ (прилагательные-диптоты)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الصِّفَةُ الْمَمْنُوعَةُ مِنَ الصَّرْفِ</span><p class="rule-study-text">прилагательные-диптоты. من الصفات الممنوعة: أفعل الذي مؤنثه فعلاء، وفعلان، والصفة المعدولة.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الصِّفَةُ الْمَمْنُوعَةُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">الصِّفَةُ الْمَمْنُوعَةُ مِنَ الصَّرْفِ — название правила; русский смысл указан в заголовке карточки</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Сначала найдите عامل и роль слова в предложении.</li><li>Проверьте нужный термин шарха и его русский смысл в карточке.</li><li>Сверьте الحكم с арабскими примерами и إعراب из источника ниже.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ب- الصِّفَةُ : تُمْنَعُ الصَّفاتُ الآتيةُ من الصَّرفِ :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">1- الصِّفَةُ التي على وزنِ ( أَفْعَلَ ) نحو : أَكْبَرَ , وأَحْمَرَ , وأَحْسَنَ . يُشْتَرَطُ أَلاَّ يكون مؤنَّثه بالتَّاء ، فإذا كان مؤنَّثه بالتَّاء صُرِفَ , نحو : أرْمَلٍ ( بالتنوين ) لأن مؤنَّثه بالتَّاء : أَرْمَلَةٌ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">2- الصَّفةُ المختومةُ بألفٍ ونونٍ زائدتينِ ( على وزن فَعْلاَنَ ) نحو : غَضْبَانَ , وفَرْحَانَ , وعَطْشَانَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">3- الصَّفَةُ الْمَعْدُولَةُ : وهي شيئان :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أ- الْعَدَدُ الذي على وَزْنَيْ مَفْعَلٍ ، وفُعَالٍ , نحو : مَثْنَى وثُنَاءَ ، ومَثْلَثَ وثُلاَثَ ... إلخ ، وذلك إلى العدد (10 ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ب- كلمة أُخَرَ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">ب- الصِّفَةُ : تُمْنَعُ الصَّفاتُ الآتيةُ من الصَّرفِ :</div><div class="rule-source-line">1- الصِّفَةُ التي على وزنِ ( أَفْعَلَ ) نحو : أَكْبَرَ , وأَحْمَرَ , وأَحْسَنَ . يُشْتَرَطُ أَلاَّ يكون مؤنَّثه بالتَّاء ، فإذا كان مؤنَّثه بالتَّاء صُرِفَ , نحو : أرْمَلٍ ( بالتنوين ) لأن مؤنَّثه بالتَّاء : أَرْمَلَةٌ .</div><div class="rule-source-line">2- الصَّفةُ المختومةُ بألفٍ ونونٍ زائدتينِ ( على وزن فَعْلاَنَ ) نحو : غَضْبَانَ , وفَرْحَانَ , وعَطْشَانَ .</div><div class="rule-source-line">3- الصَّفَةُ الْمَعْدُولَةُ : وهي شيئان :</div><div class="rule-source-line">أ- الْعَدَدُ الذي على وَزْنَيْ مَفْعَلٍ ، وفُعَالٍ , نحو : مَثْنَى وثُنَاءَ ، ومَثْلَثَ وثُلاَثَ ... إلخ ، وذلك إلى العدد (10 ) .</div><div class="rule-source-line">ب- كلمة أُخَرَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 4, 'rule', 'من الصفات الممنوعة: أفعل الذي مؤنثه فعلاء، وفعلان، والصفة المعدولة.'),
('Мединский курс (Том 4)', '17', 'أَحْكَامُ الْمَمْنُوعِ مِنَ الصَّرْفِ (правила إعراب диптота)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَحْكَامُ الْمَمْنُوعِ مِنَ الصَّرْفِ</span><p class="rule-study-text">правила إعراب диптота. لا ينون، ويجر بالفتحة نيابة عن الكسرة إلا مع أل أو الإضافة، والمنقوص على صيغة منتهى الجموع يعامل معاملة المنقوص.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">أَحْكَامُ الْمَمْنُوعِ مِنَ الصَّرْفِ</span><span class="rule-term-ru">أَحْكَامُ الْمَمْنُوعِ مِنَ الصَّرْفِ — название правила; русский смысл указан в заголовке карточки</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение в نصب</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">قَدْ</span><span class="rule-term-ru">частица; с ماضٍ часто подтверждение, с مضارع — иногда уменьшение/редкость</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِلَّا</span><span class="rule-term-ru">частица исключения</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: имя без танвина, с особым جرّ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">صِيغَةُ مُنْتَهَى الْجُمُوعِ</span><span class="rule-term-ru">крайняя форма ломаного множественного</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в состоянии رفع / именительный статус</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в состоянии نصب / винительный статус</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в состоянии جرّ / родительный статус</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, входит ли имя в одну из групп الْمَمْنُوعُ مِنَ الصَّرْفِ.</li><li>Не ставьте танвин.</li><li>В جرّ ставьте фатху вместо كسرة, кроме случаев с أَلْـ или إضافة.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и разборы из шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أحكامُه :</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أ- الممنوعُ من الصَّرْفِ لا يُنَوَّنُ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">ب- يُجَرُّ بالفتحةِ نيابةً عن الكسرةِ , نحو : صليت في مساجدَ كثيرةٍ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">إلا إذا اقترن بـ ( أل ) أو أُضِيفَ فَيُجَرُّ بالكسرة , نحو : صليتُ في المساجدِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">صليتُ في مساجدِ المدينةِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ج- الاسمُ المنقوصُ الذي على صيغةِ مُنْتَهَى الْجُمُوعِ , نحو ( مَعَانٍ ، وجَوَارٍ ) يُعَامَلُ معاملةَ المفردِ من المنقوصِ ، ككلمة ( قَاضٍ ) .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">تقول : لهذه الكلمةِ مَعَانٍ كثيرةٌ . مبتدأٌ مرفوعٌ بضمَّةٍ مُقَدَّرَةٍ ، والتَّنوينُ لِلْعِوَضِ .</span><span class="rule-example-ru">Пример или إعراب сохранён из арабского шарха.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Текст шарха по этой теме</span><div class="rule-source-ar" dir="rtl" lang="ar"><div class="rule-source-line">أحكامُه :</div><div class="rule-source-line">أ- الممنوعُ من الصَّرْفِ لا يُنَوَّنُ .</div><div class="rule-source-line">ب- يُجَرُّ بالفتحةِ نيابةً عن الكسرةِ , نحو : صليت في مساجدَ كثيرةٍ .</div><div class="rule-source-line">إلا إذا اقترن بـ ( أل ) أو أُضِيفَ فَيُجَرُّ بالكسرة , نحو : صليتُ في المساجدِ .</div><div class="rule-source-line">صليتُ في مساجدِ المدينةِ .</div><div class="rule-source-line">ج- الاسمُ المنقوصُ الذي على صيغةِ مُنْتَهَى الْجُمُوعِ , نحو ( مَعَانٍ ، وجَوَارٍ ) يُعَامَلُ معاملةَ المفردِ من المنقوصِ ، ككلمة ( قَاضٍ ) .</div><div class="rule-source-line">تقول : لهذه الكلمةِ مَعَانٍ كثيرةٌ . مبتدأٌ مرفوعٌ بضمَّةٍ مُقَدَّرَةٍ ، والتَّنوينُ لِلْعِوَضِ .</div><div class="rule-source-line">أعرفُ مَعَانِيَ كثيرةً لهذه الكلمةِ . مفعولٌ به منصوبٌ بالفتحةِ الظَّاهرةِ .</div><div class="rule-source-line">أستعملُ هذه الكلمةَ بِمَعَانٍ كثيرةٍ ، اسمٌ مجرورٌ بفتحةٍ مُقَدَّرَةٍ ، والتَّنوينُ لِلْعِوَضِ .</div><div class="rule-source-line">تَمَّ بِحَمْدِ اللهِ تَعَالَى ، والصَّلاَةُ والسَّلاَمُ عَلَى نَبِيَّنَا مُحَمَّدٍ وآلِهِ وَصَحْبِهِ أَجْمَعِينَ .</div></div></div><div class="rule-check-card"><b>Проверка:</b> арабский источник сохранён ниже полностью в пределах этой темы. Если в исходном DOC/PDF место не читается, оно отмечено как «موضع غير واضح في المصدر», без выдумывания текста.</div></div>', 5, 'rule', 'لا ينون، ويجر بالفتحة نيابة عن الكسرة إلا مع أل أو الإضافة، والمنقوص على صيغة منتهى الجموع يعامل معاملة المنقوص.');
